KB.lade("indien",[{"id":"indien-butter-chicken","name":"Butter Chicken","originalname":"Murgh Makhani","kueche":"indien","region":"Nordindien (Delhi/Punjab)","beliebtheit":98,"hauptkategorie":"fleisch","fleischsorte":"huhn","gang":"hauptgericht","kurz":"Zartes, im Grill angekohltes Hähnchen in einer seidigen, buttrig-säuerlichen Tomatensauce – das Gericht, das für viele Menschen weltweit Indien auf dem Teller bedeutet.","hintergrund":"Butter Chicken wird meist mit dem Restaurant Moti Mahal in Delhi-Daryaganj in Verbindung gebracht, wo in den 1950er-Jahren Kundan Lal Gujral und Kundan Lal Jaggi übrig gebliebenes Tandoori-Hähnchen in einer Butter-Tomaten-Sauce verwertet haben sollen. Wer die Erfindung wirklich für sich beanspruchen darf, ist bis heute umstritten – auch Peshawar vor der Teilung wird als Ursprung genannt. Das Besondere ist die Zweiteilung: erst das kräftig gewürzte, im Tandoor oder Grill angekohlte Hähnchen, dann die milde, cremige Sauce, in der es kurz ziehen darf. Gegessen wird es in Nordindien mit Naan, Roti oder Jeera-Reis. Im TasteAtlas-Ranking indischer Gerichte landet es regelmäßig unter den Spitzenplätzen.","portionen":4,"zeit":{"vorbereitung":45,"garen":60,"ruhen":240},"schwierigkeit":2,"zutaten":[{"gruppe":"Marinade für das Hähnchen","liste":[{"menge":800,"einheit":"g","name":"Hähnchenschenkel ohne Knochen und Haut","hinweis":"Schenkelfleisch bleibt saftiger als Brust; in 3–4 cm große Stücke schneiden"},{"menge":1,"einheit":"EL","name":"Zitronensaft","hinweis":"frisch gepresst"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":2,"einheit":"TL","name":"Kashmiri-Chilipulver","hinweis":"mild und tiefrot; ersatzweise 1 TL edelsüßes Paprikapulver plus 1/4 TL Cayenne"},{"menge":200,"einheit":"g","name":"Vollmilchjoghurt","hinweis":"am besten griechischer Joghurt oder 30 Minuten im Sieb abgetropft"},{"menge":1,"einheit":"EL","name":"Ingwer-Knoblauch-Paste","hinweis":"frisch aus gleichen Teilen Ingwer und Knoblauch im Mörser oder Mixer"},{"menge":1,"einheit":"TL","name":"selbst gemischtes Garam Masala","hinweis":"siehe Gewürzmischung unten"},{"menge":1,"einheit":"EL","name":"Senföl oder Rapsöl","hinweis":"Senföl ist authentisch; vor dem Erhitzen bis zum Rauchen erhitzen, sonst bleibt es scharf-beißend"}]},{"gruppe":"Garam Masala selbst gemischt (Menge reicht für mehrere Gerichte)","liste":[{"menge":2,"einheit":"EL","name":"Koriandersamen","hinweis":""},{"menge":1,"einheit":"EL","name":"Kreuzkümmelsamen","hinweis":""},{"menge":1,"einheit":"TL","name":"schwarze Pfefferkörner","hinweis":""},{"menge":8,"einheit":"Stück","name":"grüne Kardamomkapseln","hinweis":""},{"menge":1,"einheit":"Stück","name":"schwarze Kardamomkapsel","hinweis":"im Asialaden oder Gewürzhandel; gibt die rauchige Note"},{"menge":1,"einheit":"Stück","name":"Zimtstange (Cassia), ca. 5 cm","hinweis":"Cassia ist herber und indischer als Ceylon-Zimt"},{"menge":6,"einheit":"Stück","name":"Gewürznelken","hinweis":""},{"menge":1,"einheit":"Stück","name":"Blüte Macis (Muskatblüte)","hinweis":"ersatzweise eine kräftige Prise frisch geriebene Muskatnuss, erst nach dem Mahlen zugeben"}]},{"gruppe":"Tomatensauce","liste":[{"menge":600,"einheit":"g","name":"reife Tomaten","hinweis":"im Winter besser 1 Dose (400 g) gehackte Tomaten plus 1 EL Tomatenmark"},{"menge":1,"einheit":"EL","name":"Ingwer-Knoblauch-Paste","hinweis":""},{"menge":4,"einheit":"Stück","name":"grüne Kardamomkapseln, leicht angedrückt","hinweis":""},{"menge":30,"einheit":"g","name":"Cashewkerne","hinweis":"geben Bindung und Cremigkeit"},{"menge":40,"einheit":"g","name":"Butter","hinweis":"ungesalzen"},{"menge":1,"einheit":"EL","name":"Ghee oder Öl","hinweis":"Ghee verhindert, dass die Butter zu früh bräunt"},{"menge":1,"einheit":"TL","name":"Kashmiri-Chilipulver","hinweis":""}]},{"gruppe":"Zum Vollenden","liste":[{"menge":150,"einheit":"ml","name":"Sahne (mind. 30 % Fett)","hinweis":""},{"menge":1,"einheit":"TL","name":"Zucker","hinweis":"rundet die Säure der Tomaten ab"},{"menge":1,"einheit":"EL","name":"Kasuri Methi (getrocknete Bockshornkleeblätter)","hinweis":"im Asialaden oder gut sortierten Supermarkt; unverzichtbar für das Aroma"},{"menge":1,"einheit":"EL","name":"kalte Butter","hinweis":"zum Schluss für Glanz"},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]}],"ausruestung":["Grillpfanne, Backofengrill oder Holzkohlegrill","Weite, schwere Pfanne oder Topf mit Deckel","Stabmixer oder Standmixer","Feines Sieb","Gewürzmühle oder Mörser","Kleine Pfanne zum Rösten"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege alle Zutaten ab und stelle sie in Schälchen bereit, denn Butter Chicken geht später sehr schnell. Schneide das Hähnchen in gleichmäßige Stücke von etwa 3 bis 4 cm Kantenlänge, damit sie gleichzeitig gar werden, und tupfe sie mit Küchenpapier trocken, weil Feuchtigkeit die Marinade verwässert und das Anbräunen verhindert. Reibe Ingwer und Knoblauch zu gleichen Teilen fein, am besten im Mörser. Viertle die Tomaten grob, den Strunk lässt du dran, er wird später ohnehin püriert und passiert. Zerstoße die grünen Kardamomkapseln leicht mit dem Messerrücken, damit die Samen Aroma abgeben können.","dauer":0,"tipp":"Richte vorab eine Schüssel mit Eiswasser und einen Teller für das Garam Masala bereit – das Abkühlen der gerösteten Gewürze gehört zur Technik."},{"titel":"Garam Masala rösten und mahlen","aktion":"braten","text":"Erhitze eine kleine, trockene Pfanne bei mittlerer bis niedriger Hitze und gib zuerst Koriander und Kreuzkümmel hinein, denn diese Samen sind hart und brauchen am längsten. Schwenke sie ständig, bis sie nach etwa 1,5 Minuten einen warmen, nussigen Duft verströmen und leicht dunkler werden – Kreuzkümmel wird hellbraun, Koriander goldgelb. Gib dann Pfeffer, Kardamom, Zimt, Nelken und Macis dazu und röste 30 bis 45 Sekunden weiter, bis die Kardamomhülsen leicht knistern und der Duft süßlich-harzig wird. Jetzt muss alles sofort auf den kalten Teller, sonst röstet es in der Restwärme der Pfanne weiter und wird bitter. Sobald die Gewürze völlig kalt sind, mahlst du sie in einer Gewürzmühle fein; die Kardamomhülsen darfst du mitmahlen oder vorher entfernen und nur die Samen verwenden.","dauer":5,"tipp":"Röstaromen entstehen durch Hitze und Maillard-Reaktionen, aber ätherische Öle verfliegen bei zu langer Hitze. Riechst du etwas Beißendes, ist es zu weit – lieber neu anfangen, diese Gewürze kosten wenig."},{"titel":"Hähnchen in zwei Schritten marinieren","aktion":"marinieren","text":"Vermenge die Hähnchenstücke zunächst nur mit Zitronensaft, Salz und der Hälfte des Chilipulvers und lasse sie 20 Minuten stehen. Die Säure lockert die Oberfläche auf, das Salz zieht in das Fleisch und die Chilifarbe verteilt sich gleichmäßig. Rühre danach Joghurt, Ingwer-Knoblauch-Paste, ein Teelöffel Garam Masala, das restliche Chilipulver und das Öl glatt und knete die Mischung gründlich in das Fleisch. Das Fleisch sollte rundum dick bedeckt sein. Stelle es abgedeckt in den Kühlschrank, mindestens 4 Stunden, ideal über Nacht, damit die Enzyme und die Milchsäure das Fleisch zart machen. Länger als 24 Stunden solltest du nicht marinieren, sonst wird es mehlig.","dauer":0,"tipp":"Das Öl in der Marinade verhindert, dass der Joghurt beim Grillen am Fleisch klebt und verbrennt."},{"titel":"Tomatenbasis einkochen","aktion":"koecheln","text":"Gib die Tomaten, die Ingwer-Knoblauch-Paste, die angedrückten Kardamomkapseln, die Cashews und eine Prise Salz mit 100 ml Wasser in einen Topf und bringe alles bei mittlerer Hitze zum Kochen. Reduziere dann die Hitze, decke den Topf halb ab und lasse es 20 bis 25 Minuten leise köcheln, bis die Tomaten völlig zerfallen sind, die Cashews weich sind und die Masse dickflüssig ist. Rühre gelegentlich um, damit nichts am Boden ansetzt. Die Sauce ist so weit, wenn sie sattrot ist, kein wässriger Saft mehr abläuft und der Duft süß-säuerlich wird. Fische die Kardamomkapseln danach heraus, sonst bleibt ein Hauch zu viel Kardamom im Püree.","dauer":25,"tipp":"Die Cashews ersetzen Mehl oder Speisestärke, die in manchen Restaurantversionen verwendet werden, und sorgen für natürliche Cremigkeit."},{"titel":"Pürieren und passieren","aktion":"puerieren","text":"Püriere die Tomatenmasse mit dem Stabmixer sehr fein, mindestens eine Minute lang, bis keine Cashewstückchen mehr sichtbar sind. Streiche sie anschließend mit einem Löffel oder einer Kelle durch ein feines Sieb in eine saubere Schüssel und drücke kräftig, damit die gesamte Flüssigkeit durchläuft. Zurück bleiben Tomatenhäute, Kerne und Fasern, die sonst eine grobe Textur verursachen würden. Das Passieren ist der Schritt, der den typischen samtigen Restaurantcharakter erzeugt und ihn von einer einfachen Tomatensauce unterscheidet. Das Ergebnis sollte leuchtend orangerot sein und wie flüssige Seide vom Löffel laufen.","dauer":10,"tipp":"Streiche das Sieb außen mit dem Löffelrücken ab – an der Unterseite hängt das beste Püree."},{"titel":"Hähnchen angrillen","aktion":"grillen","text":"Heize den Backofengrill auf höchste Stufe (Oberhitze/Grill 250 °C) vor, schiebe das Blech auf die oberste Schiene und lege einen Rost darüber. Alternativ verwendest du eine sehr heiße Grillpfanne oder den Holzkohlegrill. Streife überschüssige Marinade ab, damit sie nicht tropft, und lege die Stücke mit Abstand auf den Rost. Grille sie 8 bis 10 Minuten, wende einmal, und achte auf dunkle Röstflecken, die an den Kanten fast schwarz sein dürfen – genau diese Bitter-Röstaromen sind der Kontrast zur süßen Sauce. Das Fleisch ist innen noch nicht ganz durch, es garen später in der Sauce zu Ende. Fange Bratensaft auf, er kommt später in die Sauce.","dauer":10,"tipp":"Im Tandoor herrschen etwa 400 bis 480 °C – dein Ofengrill kommt dem nur näher, wenn Rost und Blech wirklich ganz oben stehen."},{"titel":"Rauchnote erzeugen (optional)","aktion":"raeuchern","text":"Wenn du die Rauchigkeit eines Tandoors nachahmen möchtest, halte ein Stück Holzkohle mit einer Zange direkt in die Gasflamme oder über eine Herdplatte, bis es durch und durch rot glüht. Stelle eine kleine hitzefeste Schale oder ein ausgehöhltes Zwiebelhäuschen zwischen die Hähnchenstücke in den Topf, setze die glühende Kohle hinein und träufle einen Teelöffel Ghee darüber. Es qualmt sofort kräftig; decke den Topf umgehend ab und lasse den Rauch 2 Minuten wirken. Entferne Schale und Kohle dann vorsichtig. Wer es dezent mag, überspringt diesen Schritt, die Röstflecken vom Grillen liefern bereits Raucharomen.","dauer":2,"tipp":"Nimm nur lebensmittelechte Grillkohle ohne Anzünder und öffne das Fenster – der Rauch ist dicht."},{"titel":"Sauce aufbauen","aktion":"schmoren","text":"Schmilz Butter und Ghee in einer weiten Pfanne oder einem Topf bei mittlerer Hitze. Sobald die Butter aufschäumt und nach Nuss duftet, gib das Chilipulver hinein und rühre nur 10 Sekunden, denn es verbrennt in heißem Fett sehr schnell und wird bitter. Gieße sofort das passierte Tomatenpüree dazu, rühre kräftig und lasse es 8 bis 10 Minuten bei mittlerer Hitze einkochen, bis sich die Sauce verdichtet und an den Rändern kleine Fettaugen aus Butter bilden. Streue anderthalb Teelöffel Garam Masala ein und schmecke mit Salz ab. Gieße den aufgefangenen Bratensaft vom Blech mit hinein, er bringt Röstaroma.","dauer":12,"tipp":"Das Absetzen von Fett an der Oberfläche ist das klassische Signal, dass die Sauce rund und ohne rohe Tomatensäure ist."},{"titel":"Hähnchen in der Sauce garziehen","aktion":"koecheln","text":"Gib die angegrillten Hähnchenstücke in die Sauce, schwenke alles sorgfältig um und decke die Pfanne ab. Lasse es bei kleiner Hitze 10 bis 15 Minuten sanft ziehen; die Sauce soll nur ganz leicht blubbern, nicht kochen, sonst wird das Fleisch faserig. Rühre ab und zu um. Das Fleisch ist gar, wenn ein Stück in der Mitte weiß und saftig ist (Kerntemperatur 75 bis 78 °C bei Schenkelfleisch) und sich leicht mit der Gabel teilen lässt. Falls die Sauce zu dick wird, gibst du einen Schuss warmes Wasser dazu, ist sie zu dünn, nimmst du den Deckel ab und lässt sie einkochen.","dauer":15,"tipp":"Zu hohe Hitze lässt die Sahne später flocken – bleib bei kleiner Flamme."},{"titel":"Sahne, Kasuri Methi und Finish","aktion":"abschmecken","text":"Nimm die Pfanne kurz vom Herd und rühre die Sahne und den Zucker ein, damit die Sahne nicht schockt. Reibe das Kasuri Methi zwischen den Handflächen zu feinem Pulver, röste es 10 Sekunden in einer trockenen Pfanne, bis es nach Heu und Ahornsirup duftet, und streue es über die Sauce. Erhitze alles bei kleiner Hitze noch 2 bis 3 Minuten, ohne zu kochen. Schmecke mit Salz, einer Prise Garam Masala und eventuell etwas Zitronensaft ab. Die Sauce soll buttrig, leicht süß, mild säuerlich und aromatisch sein – wenn sie flach schmeckt, fehlt meist Salz oder Säure. Schließlich rührst du die kalte Butter ein, bis sie schmilzt und der Sauce Glanz gibt.","dauer":5,"tipp":"Kasuri Methi zerreibst du erst zum Schluss: Das Aroma ist flüchtig und geht bei langem Kochen verloren."},{"titel":"Anrichten","aktion":"anrichten","text":"Fülle das Butter Chicken in eine vorgewärmte Schale und ziehe einen Faden Sahne oder einen Klecks Butter über die Oberfläche. Streue ein paar frische Korianderblätter und, wenn du magst, feine Ingwerstreifen darüber. Serviere das Gericht sofort mit frischem Naan oder duftendem Basmatireis. Lasse es vor dem Essen eine Minute ruhen, damit sich die Aromen setzen. Am nächsten Tag schmeckt es sogar noch besser, weil sich die Gewürze verbunden haben – erwärme es dann sanft mit einem Schuss Wasser und gib etwas frische Sahne dazu.","dauer":0,"tipp":"Gib die Sahne zum Anrichten erst am Tisch zu, so sieht das Gericht am schönsten aus."}],"profitipps":["Das Hähnchen vor dem Garen in der Sauce unbedingt angrillen – ohne dunkle Röstaromen schmeckt Butter Chicken flach und süßlich.","Die Sauce passieren: Erst so entsteht die seidige Konsistenz, die man aus guten Restaurants kennt.","Garam Masala frisch rösten und mahlen; fertiges Pulver aus dem Regal hat deutlich weniger Duft und schmeckt oft nur nach Pfeffer.","Sahne erst zum Schluss und nur bei sanfter Hitze zufügen, sonst bricht die Sauce.","Kasuri Methi ist das Geheimnis hinter dem typischen Duft; nicht weglassen und erst zum Schluss zerreiben.","Verwende Schenkelfleisch statt Brust: Es bleibt saftig, selbst wenn es länger in der Sauce zieht."],"varianten":["Murgh Makhani aus dem Tandoor: das Hähnchen wird bei mehr als 400 °C am Spieß gegart und noch heiß in die Sauce gelegt.","Vegetarische Variante als Paneer Makhani mit angebratenen Paneerwürfeln.","Butter-Chicken-Biryani, bei dem das Hähnchen in der Sauce mit Reis geschichtet wird.","Ohne Sahne mit mehr Cashews und etwas Milch für eine leichtere Variante."],"beilagen":["Knoblauch-Naan oder Roti","Jeera-Reis (Kreuzkümmel-Basmati)","Zwiebel-Gurken-Salat mit Zitrone","Gurken-Raita"],"getraenk":"Mango Lassi, kühles Lagerbier oder ein halbtrockener Riesling.","koeche":[{"name":"Sanjeev Kapoor","bezug":"Sein Butter-Chicken-Rezept aus der Reihe SK Khazana arbeitet mit einer Joghurt-Marinade, gegrilltem Hähnchen und einer passierten Tomatenbasis; zum Schluss gibt er ein Holzkohle-Rauchbad und Kasuri Methi dazu – also dieselbe Kombination aus Röstaroma und Sauce, die hier beschrieben ist.","quelle":"https://sanjeevkapoor.com/Recipe/Butter-Chicken-(murgh-makhni)---SK-Khazana.html"}],"quellen":[{"titel":"Butter Chicken (murgh makhni) – SK Khazana","url":"https://sanjeevkapoor.com/Recipe/Butter-Chicken-(murgh-makhni)---SK-Khazana.html"},{"titel":"Butter chicken – Wikipedia","url":"https://en.wikipedia.org/wiki/Butter_chicken"},{"titel":"Garam masala – Wikipedia","url":"https://en.wikipedia.org/wiki/Garam_masala"},{"titel":"Butter chicken, garlic naan, mango lassi ranked best Indian dishes – Gulf News","url":"https://gulfnews.com/food/butter-chicken-garlic-naan-mango-lassi-ranked-best-indian-dishes-malpua-in-worst-list-sparks-debate-1.1720097717429"}],"bild":"curry","farben":["#c8501e","#e8903a","#f4dcb0"],"schlagworte":["Klassiker","Weltbekannt","Tandoor","Garam Masala","Murgh Makhani"],"vegetarisch_moeglich":false},{"id":"indien-chicken-tikka-masala","name":"Chicken Tikka Masala","originalname":"","kueche":"indien","region":"Nordindien (Punjab-Einfluss, britisch-indische Küche – Glasgow)","beliebtheit":96,"hauptkategorie":"fleisch","fleischsorte":"huhn","gang":"hauptgericht","kurz":"Joghurtmariniertes, im Ofen angekohltes Hähnchen in kräftiger, orangeroter Zwiebel-Tomaten-Sahne-Sauce – der britische Nationalklassiker mit indischen Wurzeln.","hintergrund":"Chicken Tikka Masala gilt als Gericht der britisch-indischen Restaurantküche und wird mit Glasgow verbunden, wo Ali Ahmed Aslam vom Shish Mahal die Sauce in den 1970ern erfunden haben soll – weitere Restaurants und Köche beanspruchen die Idee ebenfalls für sich, genauso wie die Nähe zum Punjab-Gericht Butter Chicken. Unstrittig ist die Verwandtschaft mit Tandoori-Hähnchen: Hähnchen-Tikka-Stücke werden erst trocken gegrillt und dann in einer Sauce serviert. 2001 nannte der britische Außenminister Robin Cook es ein wahrhaft britisches Nationalgericht, was in Indien auch Kritik auslöste. Im Vergleich zu Butter Chicken ist die Sauce würziger, zwiebelbasiert und oft mit Paprika und Kreuzkümmel geprägt.","portionen":4,"zeit":{"vorbereitung":40,"garen":50,"ruhen":240},"schwierigkeit":2,"zutaten":[{"gruppe":"Tikka (Hähnchen und Marinade)","liste":[{"menge":800,"einheit":"g","name":"Hähnchenbrust oder -schenkel ohne Knochen","hinweis":"in 3,5 cm große Würfel schneiden; Schenkel bleiben saftiger"},{"menge":200,"einheit":"g","name":"Naturjoghurt, 3,5 % Fett","hinweis":"abgetropft, damit die Marinade nicht wässert"},{"menge":1,"einheit":"EL","name":"Zitronensaft","hinweis":""},{"menge":1,"einheit":"EL","name":"Ingwer-Knoblauch-Paste","hinweis":""},{"menge":2,"einheit":"TL","name":"Kashmiri-Chilipulver","hinweis":"für Farbe; mild"},{"menge":1,"einheit":"TL","name":"gemahlener Kreuzkümmel","hinweis":"frisch geröstet und gemahlen ist besser"},{"menge":1,"einheit":"TL","name":"gemahlener Koriander","hinweis":""},{"menge":1,"einheit":"TL","name":"Garam Masala","hinweis":"selbst gemischt, siehe Butter Chicken"},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":2,"einheit":"EL","name":"Öl","hinweis":"neutral oder Senföl"}]},{"gruppe":"Masala-Sauce","liste":[{"menge":2,"einheit":"EL","name":"Ghee oder Öl","hinweis":""},{"menge":2,"einheit":"Stück","name":"mittelgroße Zwiebeln","hinweis":"sehr fein gehackt oder püriert"},{"menge":1,"einheit":"EL","name":"Ingwer-Knoblauch-Paste","hinweis":""},{"menge":1,"einheit":"Stück","name":"grüne Chilischote","hinweis":"nach Schärfewunsch, entkernt für milder"},{"menge":1,"einheit":"TL","name":"gemahlener Kreuzkümmel","hinweis":""},{"menge":1,"einheit":"TL","name":"gemahlener Koriander","hinweis":""},{"menge":1,"einheit":"TL","name":"Paprikapulver, edelsüß","hinweis":"für die orange Farbe"},{"menge":1,"einheit":"TL","name":"Kashmiri-Chilipulver","hinweis":""},{"menge":400,"einheit":"g","name":"passierte Tomaten","hinweis":"oder 1 Dose stückige Tomaten, püriert"},{"menge":1,"einheit":"EL","name":"Tomatenmark","hinweis":""},{"menge":150,"einheit":"ml","name":"Sahne","hinweis":""},{"menge":1,"einheit":"TL","name":"Zucker","hinweis":""},{"menge":1,"einheit":"TL","name":"Garam Masala","hinweis":"zum Schluss"},{"menge":1,"einheit":"EL","name":"Kasuri Methi","hinweis":"zerrieben"},{"menge":1,"einheit":"Handvoll","name":"frischer Koriander","hinweis":"gehackt"},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]}],"ausruestung":["Backofen mit Grillfunktion und Rost","Schwere Pfanne oder Topf mit Deckel","Stabmixer","Alufolie"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide das Hähnchen in gleich große Würfel von etwa 3,5 cm und tupfe sie trocken. Hacke die Zwiebeln so fein wie möglich, sie sollen später in der Sauce nahezu zerfallen. Reibe Ingwer und Knoblauch zu einer Paste, entkerne die grüne Chili und hacke sie fein. Stelle alle Gewürze für Marinade und Sauce in getrennten Schälchen bereit, denn die Gewürze der Marinade sind nicht dieselben wie die der Sauce. Röste Kreuzkümmel- und Koriandersamen, wenn du sie ganz hast, kurz trocken an, bis sie duften, und mahle sie frisch.","dauer":0,"tipp":"Das Abtropfen des Joghurts im Sieb (30 Minuten) ist der einfachste Trick für eine Marinade, die am Fleisch haftet statt abzulaufen."},{"titel":"Tikka marinieren","aktion":"marinieren","text":"Vermische Zitronensaft, Salz, Ingwer-Knoblauch-Paste und das Chilipulver mit den Hähnchenwürfeln und lasse sie 20 Minuten ziehen; die Säure zieht in die Faser, das Salz würzt von innen. Rühre dann Joghurt, Kreuzkümmel, Koriander, Garam Masala, Kurkuma und Öl dazu und knete alles mit den Händen gründlich ein, bis jedes Stück dick mit einer rotorangen Schicht bedeckt ist. Decke die Schüssel ab und stelle sie mindestens 4 Stunden, besser über Nacht, kalt. Nach dem Ruhen sollten die Würfel leicht klebrig und tiefrot gefärbt sein.","dauer":0,"tipp":"Wenn du Hähnchenbrust verwendest, nie länger als 12 Stunden marinieren – die Säure macht sonst die Oberfläche mehlig."},{"titel":"Tikka im Ofen angrillen","aktion":"grillen","text":"Heize den Backofen auf Grillstufe oder 250 °C Ober-/Unterhitze (Umluft 230 °C) vor, mit dem Rost auf der obersten Schiene. Spieße die Würfel auf Metallspieße oder lege sie mit Abstand auf einen Rost über ein mit Alufolie ausgelegtes Blech. Grille 10 bis 14 Minuten und wende einmal, bis die Oberfläche an einigen Stellen dunkelbraun bis schwarz gefleckt ist und das Fleisch fast durch ist. Diese Röstflecken geben der Sauce später ihren typischen rauchigen Unterton, und sie sind kein Fehler. Fange den Bratensaft auf, wenn du die Folie benutzt.","dauer":14,"tipp":"Ein Haushaltsofen schafft keine 400 °C wie der Tandoor; nutze deshalb die höchste Stufe und stelle den Rost so nah an den Grill wie möglich."},{"titel":"Zwiebelbasis rösten","aktion":"anbraten","text":"Erhitze Ghee in einer weiten Pfanne bei mittlerer Hitze und gib die fein gehackten Zwiebeln hinein. Röste sie unter häufigem Rühren 12 bis 15 Minuten, bis sie weich, goldgelb und leicht karamellisiert sind und ein süßlicher Duft aufsteigt. Es darf kein Zwiebelsaft mehr zu sehen sein; wenn die Zwiebeln dunkelbraun und bitter werden, war die Hitze zu hoch. Gib dann Ingwer-Knoblauch-Paste und Chili dazu und brate eine weitere Minute, bis der rohe Knoblauchgeruch verfliegt. Das langsame Anbraten ist wichtig, weil die Zwiebeln den Körper der Sauce bilden.","dauer":15,"tipp":"Streue eine Prise Salz zu den Zwiebeln, sie geben schneller Wasser ab und bräunen gleichmäßiger."},{"titel":"Gewürze in der Pfanne erblühen lassen","aktion":"braten","text":"Gib Kreuzkümmel, Koriander, Paprika und Chilipulver zu den Zwiebeln und rühre 30 bis 40 Sekunden in dem heißen Fett. Die Gewürze brauchen die Fettwärme, damit sich ihre fettlöslichen Aromastoffe entfalten, dabei dürfen sie nicht anbrennen – sonst wird die Sauce bitter. Gib sofort das Tomatenmark dazu und rühre zwei Minuten, bis es dunkler wird und leicht nach Karamell riecht. Das kurze Rösten des Mark-Zucker-Gemischs vertieft die Farbe und nimmt die rohe Säure. Wenn etwas ansetzt, gieße einen Schuss Wasser an.","dauer":3,"tipp":"Nimm die Pfanne bei Bedarf kurz vom Herd, wenn die Gewürze zu schnell dunkeln."},{"titel":"Tomaten zufügen und einkochen","aktion":"koecheln","text":"Gieße die passierten Tomaten zu und rühre den Bratensatz vom Boden los. Lasse die Sauce 15 bis 20 Minuten bei mittlerer Hitze unter gelegentlichem Rühren einkochen, bis sie deutlich dicker ist und sich an den Rändern Öl absetzt. Das ist das klassische Zeichen, dass die Gewürze gar sind und die Tomatensäure abgebaut wurde. Püriere die Sauce anschließend mit dem Stabmixer fein, wenn du eine glatte Restaurantkonsistenz magst; wer es rustikaler mag, lässt sie stückig. Schmecke mit Salz und Zucker ab.","dauer":20,"tipp":"Je dunkler und öliger die Sauce wird, desto tiefer ist der Geschmack – ungeduldig werden lohnt sich hier nicht."},{"titel":"Hähnchen in der Sauce ziehen lassen","aktion":"schmoren","text":"Gib die angegrillten Hähnchenwürfel samt aufgefangenem Saft in die Sauce, rühre vorsichtig um und lasse sie bei kleiner Hitze 8 bis 10 Minuten zugedeckt ziehen. Die Sauce soll nur leise köcheln, nicht sprudeln. In dieser Zeit nimmt das Fleisch Sauce auf und gart durch; es ist fertig, wenn das Innere weiß und saftig ist (75 bis 78 °C Kerntemperatur). Wenn die Sauce zu dick wird, rühre ein paar Esslöffel heißes Wasser ein.","dauer":10,"tipp":"Brustfleisch gart in der Sauce schnell nach – lieber früher vom Herd nehmen als zu lange kochen."},{"titel":"Sahne, Kasuri Methi und Garam Masala","aktion":"abschmecken","text":"Rühre die Sahne ein und lasse die Sauce noch 2 bis 3 Minuten bei sanfter Hitze ziehen, ohne dass sie richtig kocht. Zerreibe das Kasuri Methi zwischen den Handflächen und streue es mit dem Garam Masala über das Curry; das Garam Masala wird bewusst spät zugegeben, weil seine flüchtigen Aromen beim langen Kochen verfliegen. Schmecke jetzt nochmals mit Salz, Zucker und einem Spritzer Zitrone ab: Die Sauce soll kräftig, leicht süß, würzig und mit milder Säure im Hintergrund sein. Wenn sie flach schmeckt, hilft meist eine Prise Salz oder ein Spritzer Zitronensaft.","dauer":4,"tipp":"Ein kleiner Löffel Butter zum Schluss macht die Sauce glänzender und weicher im Geschmack."},{"titel":"Anrichten","aktion":"garnieren","text":"Fülle das Chicken Tikka Masala in eine vorgewärmte Schüssel und zieh einen Faden Sahne über die Oberfläche. Streue frisch gehackten Koriander darüber und ein paar dünne Streifen Ingwer, wenn du magst. Serviere es sofort mit frisch gebackenem Naan oder Basmatireis. Lege Zitronenspalten dazu, mit deren Säure du bei Tisch nachwürzen kannst.","dauer":0,"tipp":"Ein klein wenig Zitronensaft zum Servieren hebt die Gewürze, ohne die Sauce sauer zu machen."}],"profitipps":["Die Tikka-Stücke unbedingt vorher angrillen – das Röstaroma unterscheidet gutes Tikka Masala von einem simplen Hähnchen in Tomatensauce.","Zwiebeln geduldig goldgelb rösten; das ist die Basis für den Körper der Sauce.","Garam Masala spät zugeben, damit seine Aromen nicht verfliegen.","Die Sauce ist reicher, wenn sie am Vortag gekocht und am nächsten Tag mit dem Fleisch aufgewärmt wird.","Wer es authentischer mag: Das Gericht wird in Indien kaum als Klassiker, sondern als britisch-indisches Restaurantgericht gesehen."],"varianten":["Paneer Tikka Masala mit gegrilltem Paneer.","Lamm-Tikka-Masala mit Lammschulter statt Hähnchen.","Mildere Variante mit mehr Sahne und Cashewpaste.","Vikas-Khanna-Stil: kräftig gewürzt und mit Röstzwiebeln für mehr Tiefe."],"beilagen":["Naan oder Roti","Basmatireis","Zwiebel-Salat mit Zitrone","Minz-Joghurt-Dip"],"getraenk":"Kühles Lagerbier, Mango Lassi oder ein Gewürztraminer.","koeche":[{"name":"Vikas Khanna","bezug":"Wird in einem Porträt als Küchenchef genannt, zu dessen Signaturgerichten das Chicken Tikka Masala zählt.","quelle":"https://www.patelbros.com/blog/3-indian-celebrity-chefs-bringing-indian-cuisine-around-the-globe"}],"quellen":[{"titel":"Chicken tikka masala – Wikipedia","url":"https://en.wikipedia.org/wiki/Chicken_tikka_masala"},{"titel":"Is Chicken Tikka Masala Indian or British? – TBS News","url":"https://www.tbsnews.net/features/food/chicken-tikka-masala-indian-or-british-681830"},{"titel":"Tandoori chicken – Wikipedia","url":"https://en.wikipedia.org/wiki/Tandoori_chicken"},{"titel":"3 Indian celebrity chefs – Patel Brothers","url":"https://www.patelbros.com/blog/3-indian-celebrity-chefs-bringing-indian-cuisine-around-the-globe"}],"bild":"curry","farben":["#d9531e","#f0a040","#f6e3c0"],"schlagworte":["Britisch-indisch","Klassiker","Tikka","Ofengrill"],"vegetarisch_moeglich":false},{"id":"indien-naan","name":"Naan (Pfanne oder Ofen)","originalname":"Naan","kueche":"indien","region":"Nordindien (Punjab/Delhi)","beliebtheit":95,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"brot","kurz":"Weiche, luftige Fladen mit Blasen und dunklen Röstflecken, mit Ghee bestrichen – in der Pfanne oder im sehr heißen Ofen gelingen sie auch zu Hause.","hintergrund":"Der Name kommt vom persischen Wort für Brot. Naan gelangte während des Delhi-Sultanats nach Indien; der Dichter Amir Khusrau beschrieb um 1300 zwei Sorten, ein dünnes und ein schweres im Tandoor gebackenes. In der Mughal-Zeit war es ein Luxus für den Adel, erst später wurde es zum Alltagsbrot. Im Tandoor klebt der Teig an der Innenwand des Tonofens bei bis zu rund 480 °C und backt in wenigen Minuten. Zuhause ersetzt man den Tandoor durch eine sehr heiße Gusseisenpfanne mit Deckel oder einen Backofen mit Pizzastein. Typisch sind Joghurt im Teig, ein Hauch Zucker und Ghee obendrauf.","portionen":6,"zeit":{"vorbereitung":25,"garen":20,"ruhen":90},"schwierigkeit":2,"zutaten":[{"gruppe":"Teig (6 Fladen)","liste":[{"menge":400,"einheit":"g","name":"Weizenmehl Type 550","hinweis":"oder Type 405; Backmehl mit höherem Eiweißgehalt macht den Teig elastischer"},{"menge":7,"einheit":"g","name":"Trockenhefe","hinweis":"oder 20 g frische Hefe"},{"menge":1,"einheit":"TL","name":"Zucker","hinweis":"füttert die Hefe und bräunt die Oberfläche"},{"menge":1.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":120,"einheit":"g","name":"Vollmilchjoghurt","hinweis":"zimmerwarm"},{"menge":120,"einheit":"ml","name":"lauwarme Milch","hinweis":"ca. 35 °C, nicht heißer"},{"menge":2,"einheit":"EL","name":"Öl oder Ghee","hinweis":"für den Teig"}]},{"gruppe":"Zum Bestreichen","liste":[{"menge":40,"einheit":"g","name":"Ghee oder zerlassene Butter","hinweis":""},{"menge":2,"einheit":"Zehe","name":"Knoblauch","hinweis":"fein gehackt, optional"},{"menge":1,"einheit":"EL","name":"Koriandergrün","hinweis":"gehackt, optional"},{"menge":1,"einheit":"TL","name":"Schwarzkümmel (Nigella)","hinweis":"optional, in den Teig drücken"}]}],"ausruestung":["Große gusseiserne Pfanne mit Deckel oder Backstein/Pizzastein","Teigschaber","Nudelholz","Küchentuch","Backpinsel"],"schritte":[{"titel":"Mise en place und Hefe aktivieren","aktion":"vorbereiten","text":"Wiege Mehl, Salz und Zucker ab und stelle Joghurt und Milch schon eine halbe Stunde vorher heraus, damit sie Zimmertemperatur haben. Rühre die Trockenhefe in der lauwarmen Milch mit dem Zucker an und warte 5 bis 8 Minuten, bis sich an der Oberfläche ein cremiger Schaum bildet und es leicht nach Hefe riecht. Bleibt der Schaum aus, ist die Hefe tot oder die Milch zu heiß gewesen – dann beginne mit frischer Hefe neu. Zerlasse das Ghee für später in einem kleinen Topf.","dauer":8,"tipp":"Prüfe die Milch mit dem Handgelenk: Sie soll sich angenehm warm anfühlen, nicht heiß."},{"titel":"Teig kneten","aktion":"kneten","text":"Vermische das Mehl mit dem Salz in einer großen Schüssel, mache eine Mulde und gieße Hefemilch, Joghurt und Öl hinein. Rühre mit der Hand oder einem Teigschaber, bis sich ein zottiger Teig bildet, und knete ihn dann auf der Arbeitsfläche 8 bis 10 Minuten kräftig durch. Der Teig ist fertig, wenn er glatt, weich und leicht klebrig ist und beim Eindrücken mit dem Finger langsam zurückfedert. Wenn er zu fest ist, knete einen Esslöffel Wasser ein; klebt er zu stark, bestäube die Hände statt den Teig mit Mehl.","dauer":10,"tipp":"Der Fenstertest: Ziehe ein Stück Teig dünn auseinander; reißt es nicht sofort, ist das Gluten entwickelt."},{"titel":"Teig gehen lassen","aktion":"gehen","text":"Forme den Teig zu einer Kugel, gib ihn in eine leicht geölte Schüssel und decke ihn mit einem feuchten Küchentuch oder Folie ab. Lasse ihn an einem warmen Ort ohne Zugluft etwa 60 bis 90 Minuten gehen, bis er sein Volumen etwa verdoppelt hat. Zum Test drückst du eine Fingerkuppe hinein: Die Delle muss langsam zurückkommen. Wenn sie sofort verschwindet, ist der Teig noch nicht so weit; bleibt sie ganz bestehen, ist er überreif. Ein warmer Ofen mit nur der Lampe angeschaltet ist ein guter Gärplatz.","dauer":75,"tipp":"Über Nacht im Kühlschrank gegangener Teig hat mehr Geschmack – 1 Stunde vor dem Backen herausnehmen."},{"titel":"Portionieren und ausrollen","aktion":"ausrollen","text":"Drücke die Luft aus dem Teig und teile ihn in 6 gleich große Stücke von je etwa 110 g. Forme sie zu Kugeln und lasse sie abgedeckt noch 10 Minuten ruhen, damit sich das Gluten entspannt und der Teig sich leichter ausrollen lässt. Rolle jede Kugel dann tropfenförmig zu einem etwa 5 mm dicken Fladen von ca. 20 cm Länge aus, nicht dünner, sonst wird das Naan trocken. Bestäube die Arbeitsfläche nur minimal mit Mehl; wer zu viel verwendet, bekommt später verbrannte Mehlflecken. Bestreiche eine Seite mit etwas Wasser und drücke, falls du magst, Schwarzkümmel hinein.","dauer":15,"tipp":"Das Wasser auf einer Seite sorgt dafür, dass der Fladen in der Pfanne an der Kontaktfläche leicht klebt und Blasen wirft."},{"titel":"In der Pfanne backen","aktion":"braten","text":"Heize eine große, schwere Pfanne (am besten Gusseisen) ohne Fett bei hoher Hitze 3 bis 4 Minuten stark vor, sie soll richtig heiß sein. Lege einen Fladen mit der feuchten Seite nach unten hinein, setze den Deckel auf und backe ihn etwa 1 bis 2 Minuten, bis an der Oberseite große Blasen entstehen. Wende den Fladen und brate die zweite Seite 1 Minute mit Deckel, bis dunkle Röstflecken entstehen. Er ist fertig, wenn er sich aufbläht, goldbraune Flecken hat und weich bleibt. Backe ihn bei Bedarf kurz mit der oberen Seite direkt über der Gasflamme, wie es in Indien oft gemacht wird, um die typischen Brandflecken zu erzeugen.","dauer":15,"tipp":"Ohne Deckel trocknet das Naan aus, bevor es innen gar ist – der Deckel erzeugt den Dampf, der den Fladen aufgehen lässt."},{"titel":"Alternativ im Ofen backen","aktion":"backen","text":"Heize den Backofen mit Backstein, Pizzastein oder einem umgedrehten Backblech auf die höchste Stufe vor (250 bis 275 °C Ober-/Unterhitze, Umluft nicht empfohlen), mindestens 30 Minuten lang. Lege 2 Fladen auf den heißen Stein und backe sie 4 bis 5 Minuten, bis sie aufgebläht und an den Rändern gebräunt sind. Für Röstflecken stellst du das Blech die letzten 30 Sekunden unter den Grill. Entnimm sie, sobald sich Blasen dunkel färben, denn Naan wird bei zu langem Backen hart wie ein Cracker.","dauer":12,"tipp":"Je heißer der Stein, desto weicher bleibt das Naan innen."},{"titel":"Mit Ghee bestreichen","aktion":"garnieren","text":"Bestreiche die fertigen, heißen Fladen sofort mit zerlassenem Ghee. Die Wärme lässt das Fett einziehen, und die Oberfläche glänzt und duftet nach Nuss. Wer Knoblauch-Naan möchte, erhitzt das Ghee mit dem fein gehackten Knoblauch kurz, ohne dass er Farbe nimmt, und gibt den Koriander dazu. Halte die fertigen Naan in einem Küchentuch eingeschlagen warm, damit sie weich bleiben, bis alle fertig sind. Serviere sie frisch aus dem Tuch.","dauer":3,"tipp":"Knoblauch im heißen Fett nie braun werden lassen, sonst wird er bitter."}],"profitipps":["Die Pfanne muss sehr heiß sein – lauwarme Pfannen ergeben blasse, zähe Fladen.","Joghurt im Teig macht Naan weich und leicht säuerlich im Geschmack.","Den Teig nicht dünner als 5 mm ausrollen, sonst fehlt die Weichheit.","Frisch gebackene Naan sofort einschlagen und warm halten, damit sie nicht austrocknen.","Teig ruhig über Nacht im Kühlschrank gehen lassen, das gibt mehr Aroma."],"varianten":["Butter Naan mit reichlich Ghee oder Butter.","Peshawari Naan mit süßer Füllung aus Kokos, Rosinen und Mandeln.","Keema Naan mit gewürztem Hackfleisch gefüllt.","Käse-Naan mit Paneer oder Mozzarella."],"beilagen":["Butter Chicken","Dal Makhani","Palak Paneer","Raita"],"getraenk":"Salziges oder süßes Lassi, Chai oder ein kühles Lagerbier.","koeche":[],"quellen":[{"titel":"Naan – Wikipedia","url":"https://en.wikipedia.org/wiki/Naan"},{"titel":"Tandoor – Wikipedia","url":"https://en.wikipedia.org/wiki/Tandoor"},{"titel":"Top 10 Indian dishes TasteAtlas – Deccan Herald","url":"https://deccanherald.com/lifestyle/food-and-drink/from-chole-bhature-to-butter-chicken-tasteatlas-top-10-indian-dishes-3090780"}],"bild":"brot","farben":["#d8a25a","#f1d7a1","#8a5a2b"],"schlagworte":["Brot","Tandoor","Pfannenbrot","Beilage"],"vegetarisch_moeglich":true},{"id":"indien-hyderabadi-biryani","name":"Hyderabadi Biryani","originalname":"Hyderabadi Kachchi Gosht Biryani","kueche":"indien","region":"Südindien (Hyderabad, Telangana)","beliebtheit":94,"hauptkategorie":"fleisch","fleischsorte":"lamm","gang":"hauptgericht","kurz":"Marinierte Lammstücke und halb gegarter Basmatireis werden im versiegelten Topf auf kleinster Flamme gemeinsam fertig gedämpft – ein duftendes Festessen mit Safran und knusprigen Zwiebeln.","hintergrund":"Hyderabadi Biryani stammt aus der Küche der Nizame von Hyderabad und verbindet Mughlai-Tradition mit lokalen Gewürzen. Der Legende nach hat der Koch des ersten Nizam das Gericht im 18. Jahrhundert auf einer Jagd erfunden; gesichert ist das nicht. Die Königsvariante heißt kachchi (roh): Das rohe Fleisch liegt in Joghurt und Gewürzen und wird unter halb gekochtem Reis in einem mit Teig verschlossenen Topf dum-gegart, also im eigenen Dampf. Dazu gibt es Raita und Mirchi ka Salan. In Rankings wie TasteAtlas gehört Hyderabadi Biryani zu den bestplatzierten indischen Gerichten.","portionen":6,"zeit":{"vorbereitung":60,"garen":100,"ruhen":480},"schwierigkeit":3,"zutaten":[{"gruppe":"Fleisch und Marinade","liste":[{"menge":1,"einheit":"kg","name":"Lammschulter oder -keule, in 4 cm Stücken, mit Knochen","hinweis":"Knochen geben Geschmack; Ziege ist authentisch; Hähnchenschenkel gehen auch (dann weniger Garzeit)"},{"menge":250,"einheit":"g","name":"Vollmilchjoghurt","hinweis":""},{"menge":2,"einheit":"EL","name":"Ingwer-Knoblauch-Paste","hinweis":""},{"menge":1,"einheit":"EL","name":"Rohe-Papaya-Paste (optional)","hinweis":"Fleischzartmacher; ersatzweise 1 EL Zitronensaft"},{"menge":2,"einheit":"TL","name":"Kashmiri-Chilipulver","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":1,"einheit":"TL","name":"selbst gemörsertes Biryani-Masala","hinweis":"siehe Gewürzmischung unten"},{"menge":1,"einheit":"Handvoll","name":"frische Minze","hinweis":"gehackt"},{"menge":1,"einheit":"Handvoll","name":"frischer Koriander","hinweis":"gehackt"},{"menge":3,"einheit":"Stück","name":"grüne Chilischoten","hinweis":"längs aufgeschlitzt"},{"menge":2,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Biryani-Masala (selbst gemischt)","liste":[{"menge":1,"einheit":"TL","name":"Schwarzer Kreuzkümmel (Shahi Jeera) oder Kreuzkümmel","hinweis":""},{"menge":6,"einheit":"Stück","name":"grüne Kardamomkapseln","hinweis":""},{"menge":4,"einheit":"Stück","name":"Gewürznelken","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zimtstange, 4 cm","hinweis":""},{"menge":1,"einheit":"Stück","name":"Blüte Macis","hinweis":""},{"menge":0.25,"einheit":"TL","name":"frisch geriebene Muskatnuss","hinweis":""},{"menge":1,"einheit":"TL","name":"schwarze Pfefferkörner","hinweis":""}]},{"gruppe":"Reis","liste":[{"menge":500,"einheit":"g","name":"Basmatireis, gut gealtert","hinweis":"mindestens 1 Jahr gelagert, sonst klebt er"},{"menge":3,"einheit":"Stück","name":"grüne Kardamomkapseln","hinweis":""},{"menge":3,"einheit":"Stück","name":"Gewürznelken","hinweis":""},{"menge":1,"einheit":"Stück","name":"Lorbeerblatt","hinweis":""},{"menge":1,"einheit":"EL","name":"Salz","hinweis":"fürs Kochwasser"}]},{"gruppe":"Zwiebeln, Safran, Schichten","liste":[{"menge":4,"einheit":"Stück","name":"große Zwiebeln, in dünne Halbringe geschnitten","hinweis":"für Birista (Röstzwiebeln)"},{"menge":200,"einheit":"ml","name":"Öl oder Ghee zum Frittieren","hinweis":""},{"menge":1,"einheit":"Prise","name":"Safranfäden","hinweis":"in 100 ml warmer Milch eingeweicht"},{"menge":100,"einheit":"ml","name":"Milch","hinweis":"warm"},{"menge":3,"einheit":"EL","name":"Ghee","hinweis":""},{"menge":1,"einheit":"EL","name":"Rosenwasser oder Kewra-Wasser","hinweis":"optional"},{"menge":200,"einheit":"g","name":"Mehl und Wasser für den Teigverschluss","hinweis":"zu einem Strang geknetet"}]}],"ausruestung":["Schwerer Topf oder Bräter mit dicht schließendem Deckel","Großer Topf für den Reis","Tawa, Bratpfanne oder Flammenverteiler","Feines Sieb","Mörser"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege alle Zutaten ab und halte die vier Gruppen getrennt bereit: Fleisch, Reis, Zwiebeln und die Teigmischung zum Versiegeln. Schneide das Lamm in gleichmäßige Stücke von etwa 4 cm und lasse die Knochen dran. Wasche den Basmatireis in einer Schüssel in mehreren Wassern, bis es klar bleibt – so lösen sich Stärke und Staub, die zu Klumpen führen. Weiche ihn anschließend 30 Minuten in kaltem Wasser ein. Schneide die Zwiebeln in feine Halbringe, damit sie gleichmäßig bräunen.","dauer":0,"tipp":"Alterte Basmati-Sorte verwenden; Frischer Reis wird beim Dämpfen schnell matschig."},{"titel":"Biryani-Masala rösten und mörsern","aktion":"braten","text":"Erhitze eine kleine, trockene Pfanne bei niedriger bis mittlerer Hitze und röste Kreuzkümmel, Kardamom, Nelken, Zimt, Macis und Pfefferkörner 60 bis 90 Sekunden unter ständigem Schwenken, bis es intensiv nach Wärme, Blüten und Holz duftet. Die ersten Gewürze dunkeln leicht, Kardamomhülsen knistern kaum hörbar. Schütte alles sofort auf einen kalten Teller, lasse es auskühlen und zerstoße es im Mörser zu einem feinen Pulver. Röstest du zu lange, wird die Mischung bitter und rauchig, also lieber früher abbrechen. Füge zum Schluss die Muskatnuss hinzu, deren Öle sich erst frisch gerieben voll entfalten.","dauer":5,"tipp":"Die Mischung ergibt eine sanfte, süß-würzige Note – im Unterschied zu einem Pfeffer-lastigen Garam Masala."},{"titel":"Fleisch marinieren","aktion":"marinieren","text":"Rühre den Joghurt glatt und vermenge ihn mit Ingwer-Knoblauch-Paste, Papayapaste, Chilipulver, Kurkuma, dem selbst gemörserten Masala, Salz, den gehackten Kräutern und den aufgeschlitzten grünen Chilis. Gib das Lammfleisch dazu und knete alles gründlich ein, bis jedes Stück bedeckt ist. Decke die Schüssel ab und lasse sie mindestens 6 Stunden, besser über Nacht, im Kühlschrank durchziehen. Der Joghurt bricht mit seiner Milchsäure die Fasern auf und macht das Fleisch butterweich, weil es später nicht vorgegart wird.","dauer":0,"tipp":"Nimm das Fleisch 45 Minuten vor dem Schichten aus dem Kühlschrank, damit es nicht zu kalt in den Topf kommt."},{"titel":"Birista – Röstzwiebeln braten","aktion":"frittieren","text":"Erhitze Öl in einer tiefen Pfanne auf mittlere Hitze (etwa 150 bis 160 °C) und frittiere die Zwiebelringe in zwei oder drei Portionen. Rühre häufig und achte auf die Farbe: Sie wechseln von glasig zu goldgelb, dann zu tiefbraun. Nimm die Zwiebeln heraus, sobald sie hellbraun-goldfarben sind, denn sie dunkeln noch nach. Lasse sie auf Küchenpapier abtropfen, sie werden beim Abkühlen knusprig. Verwende einen Teil der Zwiebeln später für die Schichten, einen Teil als Garnitur. Das übrige aromatische Öl ist wertvoll und wird beim Schichten genutzt.","dauer":25,"tipp":"Zu dunkle Zwiebeln machen die gesamte Biryani bitter; lieber eine Spur zu hell als zu dunkel."},{"titel":"Reis zu 70 Prozent vorgaren","aktion":"kochen","text":"Bringe in einem großen Topf reichlich Wasser mit Salz, Kardamom, Nelken und Lorbeer zum Kochen; das Wasser soll so salzig wie Meerwasser schmecken, weil der Reis nicht nachgesalzen wird. Gib den abgetropften Reis hinein und koche ihn 5 bis 6 Minuten, bis ein Korn beim Zerdrücken zwischen den Fingern außen weich, innen aber noch einen weißen Kern hat. Das entspricht etwa 70 Prozent Garstufe. Schütte den Reis sofort in ein Sieb und lasse ihn abtropfen, ohne abzuschrecken. Der Rest der Garung geschieht im Dampf des Topfes.","dauer":6,"tipp":"Probiere ein Korn: Wenn es innen noch knirscht, aber nicht mehr hart ist, ist der Moment richtig."},{"titel":"Schichten","aktion":"schichten","text":"Verteile die marinierte Lammmischung samt aller Marinade gleichmäßig auf dem Boden eines schweren Topfes. Gib die Hälfte des Reises darüber, streue Röstzwiebeln, Minze, Koriander und etwas Ghee darauf, dann den restlichen Reis und noch einmal Zwiebeln und Kräuter. Beträufle die Oberfläche in Streifen mit der Safranmilch und dem Rosenwasser, damit sich später gelbe und weiße Reiskörner abwechseln. Streiche das übrige Ghee oben darüber. Der Reis soll das Fleisch vollständig abdecken, ohne dass du ihn andrückst.","dauer":10,"tipp":"Nicht umrühren! Die Schichtung ist wichtig, damit Dampf und Aromen von unten nach oben ziehen."},{"titel":"Versiegeln und Dum-Garen","aktion":"daempfen","text":"Rolle den Mehlteig zu einem Strang und drücke ihn rundum auf den Topfrand, setze den Deckel fest darauf und presse den Teig an, bis der Topf luftdicht verschlossen ist. Stelle den Topf 5 Minuten auf mittlere bis hohe Hitze, bis du ein leises Zischen hörst und Dampf am Teigrand zu sehen ist. Reduziere dann auf die kleinstmögliche Flamme, am besten mit einer Pfanne oder einem Flammenverteiler darunter, und lasse alles 45 bis 55 Minuten dum-garen. Wenn der Teig an einigen Stellen etwas bräunt, ist alles in Ordnung; kommt Dampf heraus, drücke den Teig nach.","dauer":55,"tipp":"Ein beschwerter Deckel (z. B. mit einem Topf Wasser) hilft, wenn der Deckel nicht dicht schließt."},{"titel":"Ruhen lassen","aktion":"ruhen","text":"Nimm den Topf vom Herd und lasse ihn ungeöffnet 15 bis 20 Minuten stehen. In dieser Ruhezeit setzt sich der Dampf, der Reis entspannt, und das Fleisch zieht nach. Breche den Teigrand erst jetzt auf und öffne den Deckel. Der Duft von Safran, Kardamom und Ghee sollte dir entgegenschlagen. Prüfe mit einer Gabel, ob der Reis locker, die Körner lang und trocken und das Lamm zart ist – es darf sich mühelos vom Knochen lösen.","dauer":20,"tipp":"Wenn das Fleisch noch fest ist, verschließe den Topf erneut und gare weitere 15 Minuten."},{"titel":"Mischen und Anrichten","aktion":"anrichten","text":"Lockere den Reis vorsichtig von oben nach unten mit einer Gabel auf, damit Fleisch, Safranreis und weißer Reis sich gemischt auf dem Teller zeigen, ohne dass die Körner brechen. Gib das Gericht auf eine Platte und streue die restlichen Röstzwiebeln, frische Minze und Koriander darüber. Serviere dazu Raita und – wer es authentisch will – Mirchi ka Salan. Löffle immer von unten nach oben, damit jeder Fleisch und Reis bekommt.","dauer":0,"tipp":"Am besten schmeckt Biryani lauwarm, nicht kochend heiß, weil sich dann das Aroma am besten entfaltet."}],"profitipps":["Der Teigverschluss ist der Schlüssel: Ohne Dampfstau bekommt man Eintopf mit Reis, keine Biryani.","Reis nur zu 70 Prozent vorkochen, den Rest erledigt der Dampf.","Birista ist das Herz des Gerichts – geduldig goldbraun frittieren, nicht dunkel.","Safran in warmer Milch ziehen lassen; kalte Safranfäden geben kaum Farbe ab.","Ranveer Brar nennt als Prinzipien für Biryani Temperatur, Technik und Vertrauen und betont die Geduld, damit die Fleischsäfte den Reis durchziehen."],"varianten":["Pakki Biryani: das Fleisch wird vor dem Schichten vorgegart.","Hähnchen-Biryani mit kürzerer Garzeit von etwa 30 Minuten Dum.","Vegetarische Biryani mit Gemüse, etwa nach Vivek Singh im ausgehöhlten Kürbis.","Ziegen-Biryani, die klassische Variante mit Ziegenfleisch."],"beilagen":["Raita (Joghurt-Dip)","Mirchi ka Salan (Chili-Erdnuss-Sauce)","Zwiebel-Gurken-Salat","Zitronenspalten"],"getraenk":"Salziges Lassi oder ein trockener Riesling.","koeche":[{"name":"Ranveer Brar","bezug":"Beschrieb in einem Interview drei Grundprinzipien für gelungenes Biryani (Temperatur, Technik, Vertrauen) und betonte, dass Geduld nötig ist, damit die Fleischsäfte den Reis durchdringen.","quelle":"https://www.thestatesman.com/entertainment/3ts-ranveer-brars-secret-for-cooking-perfect-biryani-1503165384.html"},{"name":"Vivek Singh","bezug":"Ein Rezept von ihm für Hyderabadi-Biryani mit Gemüse im Kürbis ist bei Great British Chefs verlinkt.","quelle":"https://www.greatbritishchefs.com/recipes/vegetarian-biryani-recipe"}],"quellen":[{"titel":"Hyderabadi biryani – Wikipedia","url":"https://en.wikipedia.org/wiki/Hyderabadi_biryani"},{"titel":"Ranveer Brar's secret for cooking perfect biryani – The Statesman","url":"https://www.thestatesman.com/entertainment/3ts-ranveer-brars-secret-for-cooking-perfect-biryani-1503165384.html"},{"titel":"Vivek Singh – Great British Chefs","url":"https://www.greatbritishchefs.com/chefs/vivek-singh"},{"titel":"TasteAtlas Top 10 Indian dishes – Deccan Herald","url":"https://deccanherald.com/lifestyle/food-and-drink/from-chole-bhature-to-butter-chicken-tasteatlas-top-10-indian-dishes-3090780"}],"bild":"reis","farben":["#d9a441","#f3dc9a","#8c4a1c"],"schlagworte":["Festessen","Dum","Safran","Hyderabad","Reisgericht"],"vegetarisch_moeglich":true},{"id":"indien-tandoori-chicken","name":"Tandoori Chicken (Backofen/Grill)","originalname":"Tandoori Murgh","kueche":"indien","region":"Nordindien (Punjab/Delhi)","beliebtheit":92,"hauptkategorie":"fleisch","fleischsorte":"huhn","gang":"hauptgericht","kurz":"Rot marinierte, saftige Hähnchenstücke mit rauchigen Röstflecken – im Backofen mit Grill-Technik nachgebaut.","hintergrund":"Tandoori Chicken wird mit Peshawar und später Delhi verbunden: Kundan Lal Gujral soll es im Restaurant Moti Mahal bekannt gemacht haben, die Herkunft ist jedoch eine Zuschreibung. Charakteristisch ist die Marinade aus Joghurt und Zitrusfrucht, rot gefärbt mit Kashmiri-Chili, die das Fleisch zart macht und im Tandoor-Lehmofen bei hohen Temperaturen gart. Daheim ersetzt man den Tandoor durch Grill und Backofen. Das Gericht steht auch hinter Butter Chicken und Chicken Tikka Masala. Im TasteAtlas-Ranking indischer Gerichte erscheint es unter den ersten zehn.","portionen":4,"zeit":{"vorbereitung":25,"garen":35,"ruhen":480},"schwierigkeit":2,"zutaten":[{"gruppe":"Hähnchen","liste":[{"menge":1.2,"einheit":"kg","name":"Hähnchenschenkel (Keulen, Ober- und Unterschenkel getrennt)","hinweis":"mit Knochen, Haut abziehen; Keulen am Gelenk trennen"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":2,"einheit":"EL","name":"Zitronensaft","hinweis":""},{"menge":2,"einheit":"TL","name":"Kashmiri-Chilipulver","hinweis":""}]},{"gruppe":"Joghurt-Marinade","liste":[{"menge":250,"einheit":"g","name":"Joghurt, 3,5 % Fett","hinweis":"abgetropft"},{"menge":2,"einheit":"EL","name":"Ingwer-Knoblauch-Paste","hinweis":""},{"menge":1,"einheit":"TL","name":"gemahlener Kreuzkümmel","hinweis":""},{"menge":1,"einheit":"TL","name":"gemahlener Koriander","hinweis":""},{"menge":2,"einheit":"TL","name":"Garam Masala","hinweis":"selbst gemischt"},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":1,"einheit":"TL","name":"Kasuri Methi","hinweis":"zerrieben"},{"menge":2,"einheit":"EL","name":"Senföl oder Öl","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Zum Bestreichen und Servieren","liste":[{"menge":2,"einheit":"EL","name":"Butter oder Ghee, zerlassen","hinweis":""},{"menge":1,"einheit":"TL","name":"Chaat Masala","hinweis":"zum Bestreuen"},{"menge":1,"einheit":"Stück","name":"Zitrone in Spalten","hinweis":""},{"menge":1,"einheit":"Stück","name":"rote Zwiebel in feinen Ringen","hinweis":""}]}],"ausruestung":["Backofen mit Grillfunktion","Gitterrost und Blech","Metallspieße (optional)","Backpinsel","Fleischthermometer"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Löse die Haut von den Hähnchenschenkeln ab, indem du sie mit einem trockenen Küchentuch greifst und abziehst – so dringt die Marinade ins Fleisch ein und es verbrennt nicht. Trenne Ober- und Unterschenkel am Gelenk. Ritze das Fleisch auf der Oberseite jedes Stücks mit einem scharfen Messer 2 bis 3 Mal bis zum Knochen ein, damit die Marinade tief eindringen kann und das Fleisch gleichmäßig gart. Stelle alle Gewürze in Schälchen bereit und lasse den Joghurt im Sieb abtropfen.","dauer":0,"tipp":"Je tiefer du einschneidest, desto gleichmäßiger gart das Fleisch am Knochen."},{"titel":"Erste Marinade","aktion":"marinieren","text":"Reibe die eingeschnittenen Schenkel mit Salz, Zitronensaft und Kashmiri-Chilipulver ein und massiere die Mischung in die Schnitte. Lasse es 20 bis 30 Minuten ruhen. Das Salz würzt das Fleisch, die Säure öffnet die Oberfläche, und die Chilifarbe haftet besser. Die Stücke sollen leicht rot und feucht aussehen. Wenn sie triefen, tupfe überschüssige Flüssigkeit ab, bevor die zweite Marinade folgt.","dauer":30,"tipp":"Nicht länger als 30 Minuten in reiner Zitronensäure marinieren, sonst wird das Fleisch mürbe-mehlig."},{"titel":"Joghurt-Marinade ansetzen","aktion":"mischen","text":"Verrühre abgetropften Joghurt mit Ingwer-Knoblauch-Paste, Kreuzkümmel, Koriander, Garam Masala, Kurkuma, Kasuri Methi, Salz und Öl zu einer dicken, glatten Paste. Sie sollte dick genug sein, um an einem Löffel zu haften, ohne abzutropfen. Gib das Fleisch hinein und knete es 2 Minuten kräftig ein, bis jede Ritze und jeder Winkel gefüllt ist. Decke es ab und lege es mindestens 8 Stunden, idealerweise über Nacht, in den Kühlschrank. Die Milchsäure zerlegt Eiweiß und macht das Fleisch zart, das Öl schützt vor Austrocknung.","dauer":0,"tipp":"Nimm das Fleisch 30 Minuten vor dem Garen aus dem Kühlschrank, damit es nicht eiskalt in den Ofen kommt."},{"titel":"Ofen vorheizen","aktion":"vorbereiten","text":"Heize den Backofen auf 250 °C Ober-/Unterhitze (Umluft 230 °C) vor, mit dem Rost auf der oberen Schiene und einem mit Alufolie ausgelegten Blech darunter, das den Saft auffängt. Je heißer der Ofen, desto näher kommst du dem Tandoor-Ergebnis mit schneller Bräunung und saftigem Inneren. Streife überschüssige Marinade vom Fleisch, damit sie nicht verbrennt, und lege es mit Abstand auf den Rost. Die Haut ist abgezogen, also bräunt die Marinade selbst.","dauer":15,"tipp":"Wenn dein Ofen auch eine Pizza-Stufe hat, nutze sie."},{"titel":"Backen","aktion":"backen","text":"Schiebe das Fleisch auf den Rost in den vorgeheizten Ofen und backe es 15 Minuten, bis die Marinade antrocknet und sich erste rote Krusten bilden. Wende die Stücke und backe weitere 10 Minuten, dann bestreiche sie mit etwas Butter und backe 5 Minuten weiter. Das Fleisch ist fertig, wenn die Kerntemperatur 78 bis 80 °C erreicht (Schenkel dürfen etwas heißer werden) und der austretende Saft klar ist. Die Oberfläche soll dunkelrot mit schwarzen Flecken sein.","dauer":30,"tipp":"Halte das Blech sauber, damit der Bratensaft nicht verbrennt und Rauch erzeugt."},{"titel":"Grillen für Röstaromen","aktion":"grillen","text":"Schalte den Ofen für die letzten 4 bis 6 Minuten auf Grillstufe, so sammeln sich dunkle Röstpunkte an der Oberfläche, wie sie im Tandoor entstehen. Behalte das Fleisch im Auge, denn die Marinade verbrennt in Sekunden. Wende die Stücke einmal und achte auf eine tiefe Rotfärbung mit kleinen, fast schwarzen Flecken – das sind kein Fehler, sondern das Aroma. Nimm das Fleisch heraus, sobald diese Flecken erscheinen.","dauer":6,"tipp":"Ein dunkler, nicht verbrannter Fleck ist das Ziel; ein schwarzer, bitter riechender Rand bedeutet, dass es zu lang war."},{"titel":"Ruhen und glasieren","aktion":"ruhen","text":"Lasse das Fleisch 5 Minuten ruhen, damit sich der Saft im Inneren verteilt. Bestreiche es dann mit zerlassener Butter oder Ghee und streue Chaat Masala sowie einen Spritzer Zitronensaft darüber. Die Butter macht die Oberfläche glänzend, das Chaat Masala bringt Säure und Schwarzsalz-Aroma. Probiere ein Stück: Das Fleisch soll sich leicht vom Knochen lösen, saftig sein und nach Rauch, Joghurt und Gewürzen schmecken.","dauer":5,"tipp":"Chaat Masala enthält Schwarzsalz mit leicht schwefligem Aroma – gib es sparsam zu."},{"titel":"Anrichten","aktion":"anrichten","text":"Lege die Hähnchenstücke auf eine Platte, garniere sie mit roten Zwiebelringen, Zitronenspalten und frischem Koriander. Serviere sie sofort mit Minz-Chutney, Raita und frischem Naan. Reiche frische Zwiebelringe zum Essen, deren Schärfe das fettige Fleisch ausgleicht. Wer die Rauchnote vertiefen will, legt ein glühendes Stück Holzkohle in eine Schale zwischen das Fleisch, träufelt etwas Ghee darauf und deckt das Ganze kurz ab.","dauer":0,"tipp":"Reste kannst du für Butter Chicken oder Chicken Tikka Masala verwenden."}],"profitipps":["Haut abziehen und tief einschneiden – nur so zieht die Marinade durch.","Joghurt abtropfen lassen, damit die Marinade an den Stücken haftet.","Möglichst heiß garen und kurz grillen, um die Tandoor-Röstflecken zu bekommen.","Das Fleisch nach dem Garen ruhen lassen, damit es saftig bleibt.","Reste in Butter Chicken oder Wraps verwenden."],"varianten":["Murgh Malai Kebab: mild mit Sahne, Cashew und Käse mariniert.","Hariyali Chicken mit grüner Marinade aus Minze, Koriander und Spinat.","Tandoori Fisch mit Joghurt-Marinade, z. B. Lachs.","Auf dem Holzkohlegrill über Indirekthitze für mehr Rauch."],"beilagen":["Naan oder Roti","Minz-Chutney","Gurken-Raita","Zwiebel-Zitronen-Salat"],"getraenk":"Kühles Lagerbier, Lassi oder ein trockener Rosé.","koeche":[],"quellen":[{"titel":"Tandoori chicken – Wikipedia","url":"https://en.wikipedia.org/wiki/Tandoori_chicken"},{"titel":"Tandoor – Wikipedia","url":"https://en.wikipedia.org/wiki/Tandoor"},{"titel":"TasteAtlas Top 10 Indian dishes – Deccan Herald","url":"https://deccanherald.com/lifestyle/food-and-drink/from-chole-bhature-to-butter-chicken-tasteatlas-top-10-indian-dishes-3090780"}],"bild":"haehnchen","farben":["#b8311a","#e2662a","#f0d49a"],"schlagworte":["Tandoori","Grill","Klassiker","Joghurt-Marinade"],"vegetarisch_moeglich":false},{"id":"indien-samosa","name":"Samosa mit Kartoffel-Erbsen-Füllung","originalname":"Samosa","kueche":"indien","region":"Nordindien (Punjab/Uttar Pradesh)","beliebtheit":91,"hauptkategorie":"vegan","fleischsorte":"","gang":"snack","kurz":"Knusprig-blasige Teigtaschen aus mürbem Ajwain-Teig, gefüllt mit würzigen Kartoffeln und Erbsen – das beliebteste Streetfood-Gebäck Indiens.","hintergrund":"Der Name stammt vom mittelpersischen Wort sanbosag für ein dreieckiges Gebäck. Frühe Formen sind bereits aus abbasidischer Zeit überliefert; im 13. oder 14. Jahrhundert kam die zentralasiatische Samsa mit Köchen an die Höfe des Delhi-Sultanats nach Indien. Amir Khusrau beschrieb um 1300 Samosas mit Fleisch, Ghee und Zwiebeln. In Nordindien gibt es heute vor allem die vegetarische Variante mit Kartoffeln und Erbsen, serviert mit Minz- und Tamarindenchutney oder als Chaat zerdrückt unter Kichererbsen-Curry. Der Teig wird mit viel Fett (Moyan) geknetet, damit er beim Frittieren Blasen wirft und kross wird.","portionen":6,"zeit":{"vorbereitung":60,"garen":45,"ruhen":45},"schwierigkeit":2,"zutaten":[{"gruppe":"Teig (12 Samosas)","liste":[{"menge":300,"einheit":"g","name":"Weizenmehl Type 405","hinweis":"in Indien Maida"},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"TL","name":"Ajwain (Königskümmel)","hinweis":"im Asialaden; ersatzweise Thymian-Samen oder Kreuzkümmel"},{"menge":5,"einheit":"EL","name":"Öl oder Ghee (Moyan)","hinweis":"erhitzt und etwas abgekühlt unterkneten"},{"menge":120,"einheit":"ml","name":"kaltes Wasser","hinweis":"nach Bedarf"}]},{"gruppe":"Füllung","liste":[{"menge":600,"einheit":"g","name":"mehligkochende Kartoffeln","hinweis":"in der Schale gekocht"},{"menge":100,"einheit":"g","name":"Erbsen","hinweis":"tiefgekühlt, aufgetaut"},{"menge":2,"einheit":"EL","name":"Öl","hinweis":""},{"menge":1,"einheit":"TL","name":"Kreuzkümmelsamen","hinweis":""},{"menge":1,"einheit":"EL","name":"Koriandersamen","hinweis":"grob im Mörser zerdrückt"},{"menge":1,"einheit":"TL","name":"Fenchelsamen","hinweis":""},{"menge":1,"einheit":"EL","name":"frischer Ingwer","hinweis":"fein gerieben"},{"menge":2,"einheit":"Stück","name":"grüne Chilischoten","hinweis":"fein gehackt"},{"menge":1,"einheit":"TL","name":"Amchur (Mangopulver)","hinweis":"ersatzweise Saft einer halben Zitrone"},{"menge":1,"einheit":"TL","name":"Garam Masala","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Kashmiri-Chilipulver","hinweis":""},{"menge":1,"einheit":"Handvoll","name":"frischer Koriander","hinweis":"gehackt"},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]},{"gruppe":"Zum Frittieren","liste":[{"menge":1,"einheit":"l","name":"Frittieröl (Sonnenblumen- oder Rapsöl)","hinweis":""},{"menge":2,"einheit":"EL","name":"Mehl-Wasser-Paste zum Kleben","hinweis":"1 EL Mehl mit etwas Wasser verrührt"}]}],"ausruestung":["Schwerer, hoher Topf oder Wok zum Frittieren","Fritierthermometer","Nudelholz","Schaumlöffel","Küchenpapier"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Stelle Mehl, Gewürze und Öl bereit und wiege alles ab. Koche die Kartoffeln mit Schale in Salzwasser 20 bis 25 Minuten, bis sie weich sind, und lasse sie abkühlen; mit Schale gekocht ziehen sie weniger Wasser. Schäle sie danach und zerdrücke sie grob mit der Gabel, damit noch Stücke bleiben. Taue die Erbsen auf. Hacke Chili und Ingwer fein und zerdrücke Koriandersamen grob im Mörser. Bereite ein kleines Schälchen Mehl-Wasser-Paste als Kleber vor.","dauer":25,"tipp":"Warme Kartoffeln sind klebrig; lass sie wirklich abkühlen, sonst wird die Füllung zu matschig und die Samosa weicht auf."},{"titel":"Teig kneten","aktion":"kneten","text":"Vermische Mehl, Salz und Ajwain in einer Schüssel. Erhitze das Öl kurz und gib es heiß zum Mehl; verreibe alles mit den Fingerspitzen, bis die Mischung wie feine Krümel aussieht und sich zusammenpressen lässt, ohne zu zerfallen. Dieses Fett (Moyan) macht die Blasen und die Mürbheit. Gib nach und nach kaltes Wasser dazu und knete 5 Minuten, bis ein fester, glatter Teig entsteht, der fester ist als Brotteig. Ist er zu weich, werden die Samosas ölig, ist er zu trocken, reißt er.","dauer":8,"tipp":"Der Teig ist richtig, wenn er sich beim Kneten wie knetfester Ton anfühlt."},{"titel":"Teig ruhen lassen","aktion":"ruhen","text":"Bedecke den Teig mit einem feuchten Tuch oder lege ihn in eine Schüssel mit Deckel und lasse ihn mindestens 30 Minuten bei Raumtemperatur ruhen. In dieser Zeit entspannt sich das Gluten und der Teig lässt sich später dünn und gleichmäßig ausrollen, ohne zurückzuschnappen. Trockne ihn nicht an der Luft aus, sonst bilden sich Krusten, die beim Frittieren Risse und Fettaufnahme verursachen. Währenddessen kannst du die Füllung zubereiten.","dauer":30,"tipp":"Wenn er über Nacht kühl ruht, wird er noch geschmeidiger – vor dem Ausrollen 30 Minuten temperieren."},{"titel":"Füllung würzen","aktion":"anbraten","text":"Erhitze das Öl in einer Pfanne bei mittlerer Hitze. Gib Kreuzkümmel, Koriander und Fenchel hinein und warte, bis sie leise knistern und nach 20 bis 30 Sekunden duften – das ist der Moment, in dem sich ihre fettlöslichen Aromen lösen. Füge Ingwer und Chili hinzu und rühre 30 Sekunden. Gib Erbsen, Kartoffeln, Chilipulver, Amchur, Garam Masala und Salz dazu und rühre 3 bis 4 Minuten, bis die Mischung trocken und gut gewürzt ist. Schmecke kräftig ab, weil der Teig neutral ist, und gib zum Schluss Koriander dazu.","dauer":8,"tipp":"Die Füllung soll eher trocken und krümelig sein – nasse Füllung macht die Teigtasche weich."},{"titel":"Füllung abkühlen lassen","aktion":"kuehlen","text":"Verteile die Füllung auf einem Teller und lasse sie 15 bis 20 Minuten vollständig abkühlen. Warme Füllung erzeugt Dampf, der den Teig von innen aufweicht und beim Frittieren zu Rissen führt. Kosten darfst du jetzt: Die Füllung sollte kräftig salzig, leicht sauer von Amchur und mit einer fruchtigen Schärfe schmecken. Falls sie fad ist, gib noch Salz oder Amchur dazu.","dauer":20,"tipp":"Salz wirkt in der Füllung gedämpft, würze deshalb etwas mutiger."},{"titel":"Ausrollen und Formen","aktion":"formen","text":"Teile den Teig in 6 Kugeln, rolle jede zu einem Oval von etwa 18 cm Länge und 2 mm Dicke aus und schneide es in der Mitte durch. Bestreiche die gerade Schnittkante mit Wasser, forme aus jeder Hälfte einen Kegel, indem du die Ecken überlappst und festdrückst. Halte den Kegel in der Hand wie eine Tüte, die Naht liegt als Nahtstelle an einer Seite. Die Verschlussnaht muss fest anliegen, damit nichts austritt.","dauer":15,"tipp":"Eine saubere Nahtstelle ohne Luftblasen verhindert das Aufplatzen im Fett."},{"titel":"Füllen und verschließen","aktion":"fuellen","text":"Fülle jeden Kegel zu zwei Dritteln mit einem gehäuften Esslöffel Füllung und drücke sie leicht an. Fülle nicht bis zum Rand, sonst platzt die Samosa beim Frittieren. Bestreiche den oberen Rand mit Mehl-Wasser-Paste, drücke ihn zusammen und falte ihn zu einem Dreieck, sodass er luftdicht verschlossen ist. Drücke die Naht mit einer Gabel oder dem Daumen fest. Lege die fertigen Samosas auf ein Blech und decke sie mit einem Tuch ab.","dauer":15,"tipp":"Drücke vor dem Verschließen die Luft aus der Tasche, sonst bläht sie sich auf und reißt."},{"titel":"Langsam frittieren","aktion":"frittieren","text":"Erhitze das Öl auf nur 150 bis 160 °C – das ist niedriger als bei den meisten Frittiergerichten. Gib 4 bis 5 Samosas hinein; sie sinken ab, steigen auf und blasen kleine Bläschen auf. Frittiere sie 12 bis 15 Minuten unter gelegentlichem Wenden, bis sie gleichmäßig goldbraun und knusprig sind. Bei zu hoher Hitze wird der Teig außen dunkel und innen roh, bei zu niedriger saugt er Öl auf. Hole sie mit dem Schaumlöffel heraus und lasse sie auf Küchenpapier abtropfen.","dauer":15,"tipp":"Ein Teststück: Wenn ein Stück Teig nach etwa 10 Sekunden langsam aufsteigt, ist die Temperatur richtig."},{"titel":"Anrichten","aktion":"anrichten","text":"Serviere die Samosas sofort heiß mit Minz-Koriander-Chutney und süß-saurem Tamarindenchutney. Wer es als Chaat möchte, bricht eine Samosa auf einem Teller auf, übergießt sie mit warmem Kichererbsen-Curry, Joghurt und beiden Chutneys und streut Granatapfelkerne, rote Zwiebeln und Sev darüber. Samosas lassen sich einfrieren: roh einfrieren und gefroren frittieren (bei niedriger Temperatur etwas länger).","dauer":0,"tipp":"Frisch frittiert sind sie am besten; wiedererwärmt im Ofen bei 180 °C Umluft für 8 Minuten werden sie wieder knusprig."}],"profitipps":["Heißes Fett in den Teig einarbeiten (Moyan) – das macht die Samosa blasig und knusprig.","Teig fest halten, nicht weich – sonst saugt er Öl.","Füllung vollständig abkühlen lassen, damit der Teig nicht weich wird.","Bei 150 bis 160 °C langsam frittieren, so bräunt der Teig und wird durchgängig kross.","Amchur gibt die typische Säure; ohne ihn Zitronensaft verwenden."],"varianten":["Keema Samosa mit gewürztem Hackfleisch.","Punjabi Samosa mit größerem Teig und Kartoffeln-Erbsen-Füllung.","Bengalische Singara, kleiner, mit Kartoffeln, Erdnüssen und Rosinen.","Gebacken statt frittiert bei 200 °C Ober-/Unterhitze für 25 bis 30 Minuten."],"beilagen":["Minz-Koriander-Chutney","Tamarindenchutney","Masala Chai","Chana Masala als Samosa Chaat"],"getraenk":"Masala Chai oder ein kühles Lassi.","koeche":[],"quellen":[{"titel":"Samosa – Wikipedia","url":"https://en.wikipedia.org/wiki/Samosa"},{"titel":"Tadka: the simple Indian cooking technique – SBS Food","url":"https://www.sbs.com.au/food/article/tadka-the-simple-indian-cooking-technique-you-should-know/8nucpkdcu"}],"bild":"gebaeck","farben":["#c98a3a","#e8c070","#7a4a1c"],"schlagworte":["Streetfood","Frittiert","Vegan","Teigtasche"],"vegetarisch_moeglich":true},{"id":"indien-palak-paneer","name":"Palak Paneer","originalname":"","kueche":"indien","region":"Nordindien (Punjab)","beliebtheit":90,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"hauptgericht","kurz":"Sattgrüne Spinatsauce mit goldbraun gebratenem Frischkäse – ein vegetarischer Klassiker, der sich in einer halben Stunde zubereiten lässt.","hintergrund":"Palak Paneer stammt aus Nordindien und wird besonders mit dem Punjab verbunden. Palak heißt Spinat, Paneer ist ein frischer, nicht schmelzender Käse aus Milch. Das Gericht gilt in Restaurants weltweit als beliebtestes vegetarisches Curry und wird mit Roti, Naan, Paratha oder Reis serviert. Traditionell wird der Spinat kurz gekocht und püriert, dann mit Zwiebel-Tomaten-Basis und Gewürzen verbunden; das Paneer wird separat angebraten, damit es seine Form behält. Eine mit Knoblauch und Chili aufgeschäumte Tadka obendrauf gibt Aroma und Glanz.","portionen":4,"zeit":{"vorbereitung":20,"garen":30,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Paneer","liste":[{"menge":250,"einheit":"g","name":"Paneer","hinweis":"in 2 cm Würfel; gibt es im Asialaden oder gut sortierten Supermarkt"},{"menge":1,"einheit":"EL","name":"Ghee oder Öl","hinweis":"zum Anbraten"},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Spinat","liste":[{"menge":500,"einheit":"g","name":"frischer Blattspinat","hinweis":"oder 400 g Tiefkühl-Blattspinat, aufgetaut und ausgedrückt"},{"menge":2,"einheit":"Stück","name":"grüne Chilischoten","hinweis":""},{"menge":1,"einheit":"Stück","name":"Stück Ingwer, 2 cm","hinweis":""}]},{"gruppe":"Sauce","liste":[{"menge":2,"einheit":"EL","name":"Ghee","hinweis":""},{"menge":1,"einheit":"TL","name":"Kreuzkümmelsamen","hinweis":""},{"menge":1,"einheit":"Stück","name":"große Zwiebel","hinweis":"fein gehackt"},{"menge":1,"einheit":"EL","name":"Ingwer-Knoblauch-Paste","hinweis":""},{"menge":2,"einheit":"Stück","name":"Tomaten","hinweis":"fein gewürfelt oder püriert"},{"menge":1,"einheit":"TL","name":"gemahlener Koriander","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Garam Masala","hinweis":""},{"menge":60,"einheit":"ml","name":"Sahne","hinweis":""},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]},{"gruppe":"Tadka zum Schluss","liste":[{"menge":1,"einheit":"EL","name":"Ghee","hinweis":""},{"menge":3,"einheit":"Zehe","name":"Knoblauch","hinweis":"in feinen Scheiben"},{"menge":1,"einheit":"Stück","name":"getrocknete rote Chilischote","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Kashmiri-Chilipulver","hinweis":""}]}],"ausruestung":["Großer Topf für Spinat","Eiswasser-Schüssel","Stabmixer","Beschichtete Pfanne","Kleine Pfanne für Tadka"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wasche den Spinat gründlich in mehreren Wassern, damit kein Sand zurückbleibt, und entferne dicke Stiele. Schneide den Paneer in 2 cm große Würfel und tupfe ihn mit Küchenpapier trocken, weil Feuchtigkeit beim Braten spritzt. Hacke die Zwiebel fein, reibe Ingwer und Knoblauch zu Paste und würfele die Tomaten. Bereite eine große Schüssel mit Eiswasser vor – sie ist der Schlüssel zu leuchtend grünem Spinat.","dauer":0,"tipp":"Falls du Tiefkühlspinat verwendest, taue ihn auf und drücke ihn kräftig aus, sonst wird die Sauce wässrig."},{"titel":"Paneer anbraten","aktion":"anbraten","text":"Erhitze Ghee in einer beschichteten Pfanne bei mittlerer Hitze, gib die Paneerwürfel hinein und brate sie 4 bis 6 Minuten, bis sie auf mindestens zwei Seiten goldbraun sind. Wende sie vorsichtig und lasse sie nicht gleich kleben bleiben. Sie sollen außen eine leichte Kruste haben und innen weich bleiben. Gib sie dann in eine Schüssel mit warmem, gesalzenem Wasser; so bleiben sie schön weich und saugen sich mit Salz voll. Das Anbraten gibt Röstaroma und verhindert, dass der Käse in der Sauce zerfällt.","dauer":6,"tipp":"Paneer nicht zu lange braten, sonst wird er gummiartig."},{"titel":"Spinat blanchieren und abschrecken","aktion":"blanchieren","text":"Bringe einen großen Topf Wasser zum Kochen und gib den Spinat hinein. Koche ihn nur 1 bis 2 Minuten, bis er zusammenfällt und leuchtend grün ist. Hebe ihn mit einem Sieb heraus und tauche ihn sofort in das Eiswasser. Das stoppt den Garprozess und fixiert das Chlorophyll, sodass die Farbe grün bleibt statt olivgrau zu werden. Drücke den Spinat gut aus und püriere ihn mit Chili, Ingwer und etwas Wasser zu einer feinen Paste.","dauer":5,"tipp":"Länger gekochter Spinat wird braungrün und schmeckt bitter."},{"titel":"Gewürze und Zwiebeln anbraten","aktion":"braten","text":"Erhitze Ghee in einem Topf bei mittlerer Hitze, gib die Kreuzkümmelsamen hinein und warte etwa 20 Sekunden, bis sie zischen und nussig duften. Gib dann die Zwiebel dazu und brate sie 8 bis 10 Minuten, bis sie weich und goldgelb ist. Füge Ingwer-Knoblauch-Paste hinzu und rühre eine weitere Minute, bis der rohe Geruch verfliegt. Das Anbraten der Zwiebel bis zur goldgelben Farbe gibt der Sauce die Tiefe, die sonst fehlt.","dauer":12,"tipp":"Salze die Zwiebeln leicht, sie bräunen schneller und gleichmäßiger."},{"titel":"Tomaten und Gewürze","aktion":"koecheln","text":"Gib die Tomaten, Koriander, Kurkuma und Salz zu den Zwiebeln und koche alles 6 bis 8 Minuten bei mittlerer Hitze, bis die Tomaten zerfallen sind und sich Öl am Rand der Masse absetzt. Das ist das klassische Zeichen, dass die Masala gar ist und ihre rohe Säure verloren hat. Rühre dabei häufig, damit nichts ansetzt. Wenn es zu trocken wird, gib einen Schluck Wasser dazu.","dauer":8,"tipp":"Nimm keine zu wässrigen Tomaten; sonst muss die Masala länger einkochen."},{"titel":"Spinat einrühren und köcheln","aktion":"koecheln","text":"Gib das Spinatpüree in die Masala und rühre gut um. Lasse es bei kleiner bis mittlerer Hitze 5 bis 8 Minuten leise köcheln, nicht zu heftig, damit die Farbe erhalten bleibt. Verdünne die Sauce bei Bedarf mit ein paar Esslöffeln heißem Wasser; sie soll sämig wie Cremesuppe sein. Schmecke mit Salz ab. Der Duft sollte frisch, grün und leicht süßlich sein; riecht er nach Eisen oder Bitterem, wurde der Spinat zu lange gekocht.","dauer":8,"tipp":"Deckel offen lassen, das hilft, die grüne Farbe zu erhalten."},{"titel":"Paneer und Sahne zufügen","aktion":"binden","text":"Nimm den Paneer aus dem Salzwasser und lasse ihn abtropfen. Gib ihn in die Sauce und lasse alles bei kleiner Hitze 3 bis 4 Minuten ziehen, damit er Aroma aufnimmt. Rühre dann die Sahne und Garam Masala ein und erwärme alles, ohne es zu kochen. Die Sahne rundet die leichte Bitterkeit des Spinats ab. Probiere und füge bei Bedarf Salz oder einen Spritzer Zitronensaft hinzu.","dauer":5,"tipp":"Wenn du keine Sahne nutzen möchtest, ersetze sie durch einen Löffel Cashewmus."},{"titel":"Knoblauch-Tadka zum Schluss","aktion":"braten","text":"Erhitze Ghee in einer kleinen Pfanne bei mittlerer Hitze, gib die Knoblauchscheiben hinein und brate sie, bis sie hellgolden sind und intensiv duften (etwa 30 bis 45 Sekunden). Füge die getrocknete Chili hinzu, nimm die Pfanne vom Herd und gib das Chilipulver in das heiße Fett. Rühre kurz und gieße die Mischung sofort über das Curry. Du hörst ein Zischen, die Aromen steigen auf. Decke den Topf für 1 bis 2 Minuten zu, damit sie einziehen.","dauer":3,"tipp":"Knoblauch wird schnell bitter – nimm ihn aus dem Fett, sobald er goldgelb ist."},{"titel":"Anrichten","aktion":"anrichten","text":"Rühre das Tadka leicht unter oder lasse es als Marmorierung auf der Oberfläche. Serviere das Palak Paneer heiß mit frischem Naan, Roti oder Jeera-Reis. Ein Tupfer Sahne oder ein Stück Butter oben drauf sieht schön aus. Gib Zwiebelringe und Zitronenspalten dazu, die Säure und Schärfe passen perfekt zu der cremigen Sauce.","dauer":0,"tipp":"Beim Aufwärmen nur ganz sanft erhitzen, damit die Farbe grün bleibt."}],"profitipps":["Spinat nur kurz blanchieren und im Eiswasser abschrecken – so bleibt die Sauce leuchtend grün.","Paneer vorher anbraten, damit er in der Sauce nicht zerfällt.","Zwiebeln richtig goldgelb braten für Tiefe und Süße.","Tadka mit Knoblauch zum Schluss gibt Aroma und Glanz – nie weglassen.","Nicht zu stark köcheln, sonst wird die Sauce braun."],"varianten":["Palak Chicken mit Hähnchen statt Paneer.","Saag Paneer mit Mischung aus Senfblättern und Spinat.","Palak Tofu für eine vegane Variante mit Kokosmilch.","Kürzere Variante ohne Zwiebeln, nur mit Knoblauch und Tomaten."],"beilagen":["Naan, Roti oder Paratha","Jeera-Reis","Zwiebel-Salat","Raita"],"getraenk":"Lassi, Chai oder ein trockener Weißwein wie Grüner Veltliner.","koeche":[],"quellen":[{"titel":"Palak paneer – Wikipedia","url":"https://en.wikipedia.org/wiki/Palak_paneer"},{"titel":"The Crackling Spices Of Indian Tempering – NPR","url":"https://www.npr.org/2011/12/07/143251451/the-crackling-spices-of-indian-tempering"}],"bild":"curry","farben":["#3f7a32","#8ab05a","#f2e2b8"],"schlagworte":["Vegetarisch","Spinat","Paneer","Punjab"],"vegetarisch_moeglich":true},{"id":"indien-dal-makhani","name":"Dal Makhani","originalname":"","kueche":"indien","region":"Nordindien (Punjab/Delhi)","beliebtheit":89,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"hauptgericht","kurz":"Schwarze Linsen und Kidneybohnen, stundenlang auf kleiner Flamme gegart und mit Butter und Sahne vollendet – cremig, rauchig, tiefgründig.","hintergrund":"Dal Makhani wird mit dem Punjab und den Restaurants von Delhi verbunden; auch hier fallen die Namen Kundan Lal Gujral und Kundan Lal Jaggi aus dem Moti Mahal in den frühen 1950er-Jahren. Eine andere Erzählung sagt, dass Punjabis aus Peshawar ein Gericht mit ganzen schwarzen Linsen (Urad) mitbrachten und später in Restaurants verfeinerten. Das Gericht lebt von Zeit: Urad-Dal und Rajma garen lange und werden teilweise zerdrückt, damit sie cremig werden. Butter und Sahne am Ende geben dem Gericht seinen Namen (makhani = buttrig).","portionen":4,"zeit":{"vorbereitung":20,"garen":150,"ruhen":600},"schwierigkeit":2,"zutaten":[{"gruppe":"Linsen","liste":[{"menge":200,"einheit":"g","name":"ganze schwarze Urad-Linsen (Urad Sabut)","hinweis":"im Asialaden; nicht die geschälten weißen"},{"menge":40,"einheit":"g","name":"rote Kidneybohnen (Rajma), getrocknet","hinweis":"über Nacht eingeweicht"},{"menge":1,"einheit":"Stück","name":"Lorbeerblatt","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Frisch gerösteter Garam-Masala-Mix (kleine Menge)","liste":[{"menge":4,"einheit":"Stück","name":"grüne Kardamomkapseln","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zimtstange, 3 cm","hinweis":""},{"menge":4,"einheit":"Stück","name":"Gewürznelken","hinweis":""},{"menge":1,"einheit":"TL","name":"Kreuzkümmelsamen","hinweis":""},{"menge":0.5,"einheit":"TL","name":"schwarze Pfefferkörner","hinweis":""},{"menge":1,"einheit":"Prise","name":"frisch geriebene Muskatnuss","hinweis":""}]},{"gruppe":"Masala","liste":[{"menge":2,"einheit":"EL","name":"Ghee","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zwiebel","hinweis":"fein gehackt"},{"menge":1,"einheit":"EL","name":"Ingwer-Knoblauch-Paste","hinweis":""},{"menge":300,"einheit":"g","name":"passierte Tomaten","hinweis":""},{"menge":1,"einheit":"TL","name":"Kashmiri-Chilipulver","hinweis":""},{"menge":50,"einheit":"g","name":"Butter","hinweis":""},{"menge":100,"einheit":"ml","name":"Sahne","hinweis":""},{"menge":1,"einheit":"EL","name":"Kasuri Methi","hinweis":""},{"menge":1,"einheit":"TL","name":"Zucker","hinweis":""},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]},{"gruppe":"Dhungar (Räuchern, optional)","liste":[{"menge":1,"einheit":"Stück","name":"Stück Holzkohle","hinweis":""},{"menge":1,"einheit":"TL","name":"Ghee","hinweis":""}]}],"ausruestung":["Schwerer Topf mit Deckel oder Schnellkochtopf","Kartoffelstampfer","Mörser oder Gewürzmühle","Kleine Pfanne zum Rösten"],"schritte":[{"titel":"Mise en place und Einweichen","aktion":"vorbereiten","text":"Spüle die Urad-Linsen und die Kidneybohnen in mehreren Wassern, bis das Wasser klar bleibt. Weiche sie in reichlich kaltem Wasser mindestens 8 Stunden, am besten über Nacht, ein; sie nehmen ihr Volumen auf mehr als das Doppelte zu. Das Einweichen verkürzt die Garzeit und macht die Linsen leichter verdaulich. Gieße das Einweichwasser danach ab. Hacke Zwiebel, Ingwer und Knoblauch fein.","dauer":0,"tipp":"Wechsle bei warmer Raumtemperatur das Wasser einmal, damit nichts anfängt zu gären."},{"titel":"Linsen weich kochen","aktion":"kochen","text":"Gib Linsen und Bohnen mit Lorbeer und 1,2 Litern frischem Wasser in einen schweren Topf und bringe sie zum Kochen. Schöpfe den grauen Schaum ab, der sich oben sammelt. Reduziere die Hitze, decke den Topf halb ab und lasse alles 60 bis 75 Minuten sanft köcheln, im Schnellkochtopf 25 bis 30 Minuten. Die Linsen sind fertig, wenn sie sich mühelos zwischen den Fingern zerdrücken lassen und innen völlig weich sind. Erst jetzt salzen, damit die Haut nicht hart bleibt.","dauer":70,"tipp":"Kidneybohnen enthalten Phasin und müssen mindestens 10 Minuten sprudelnd kochen."},{"titel":"Garam Masala frisch rösten","aktion":"braten","text":"Röste Kardamom, Zimt, Nelken, Kreuzkümmel und Pfefferkörner in einer trockenen Pfanne bei kleiner bis mittlerer Hitze 60 bis 90 Sekunden. Schwenke ständig. Die Gewürze sind fertig, wenn sie intensiv duften, der Kreuzkümmel leicht dunkelt und die Nelken aufquellen. Gib sie auf einen Teller und lasse sie vollständig abkühlen, bevor du sie im Mörser fein zerstößt. Gib zum Schluss die frische Muskatnuss dazu. Das Rösten erzeugt Röstaromen und verleiht der Mischung Tiefe; zu lange geröstet wird sie bitter.","dauer":5,"tipp":"Röstest du die Gewürze am Anfang, behalten sie bis zum Servieren mehr Duft als bei langer Kochzeit."},{"titel":"Tomatenmasala kochen","aktion":"anbraten","text":"Erhitze Ghee in einer weiten Pfanne bei mittlerer Hitze und brate die Zwiebel 8 bis 10 Minuten, bis sie goldgelb ist. Gib Ingwer-Knoblauch-Paste dazu und brate sie 1 Minute, bis der Knoblauch nicht mehr roh riecht. Füge Tomaten und Chilipulver hinzu und koche alles 10 bis 12 Minuten bei mittlerer Hitze, bis sich Öl vom Püree abgesetzt hat und die Masse dunkelrot und dick geworden ist. Rühre häufig. Die tiefe Farbe und das abgesetzte Öl zeigen, dass die Masala gar ist.","dauer":22,"tipp":"Wenn die Masala spritzt, setze einen Spritzschutz auf oder verringere die Hitze."},{"titel":"Zusammenführen und langsam garen","aktion":"schmoren","text":"Gib die Masala zu den gekochten Linsen und rühre gut um. Füge ein bis zwei Tassen Wasser hinzu und lasse die Mischung bei kleinster Hitze mindestens 45 Minuten, ideal 90 Minuten, ohne Deckel köcheln. Rühre häufig vom Boden her, damit nichts anbrennt. Die Linsen sollen dabei zerfallen und das Gericht dickflüssig und cremig werden. Wenn es zu dick wird, gib heißes Wasser dazu. Dieser lange Garprozess ist der eigentliche Unterschied zu einem einfachen Linsengericht.","dauer":60,"tipp":"Ein Diffusor oder eine Pfanne unter dem Topf verhindert Anbrennen."},{"titel":"Stampfen und Binden","aktion":"puerieren","text":"Zerdrücke etwa ein Drittel der Linsen mit einem Kartoffelstampfer direkt im Topf, damit die Masse cremig bindet, aber noch Struktur hat. Schmecke mit Salz, Zucker und dem gemahlenen Garam Masala ab. Das Gericht sollte jetzt dick wie ein Brei sein, glänzend und dunkelbraun, ohne dass Wasser abläuft. Falls nicht, lasse es weiter einkochen.","dauer":5,"tipp":"Je länger es köchelt, desto weniger Sahne brauchst du."},{"titel":"Butter, Sahne und Kasuri Methi","aktion":"abschmecken","text":"Rühre die Butter in kleinen Stücken ein und lasse sie schmelzen, dann gib die Sahne dazu. Erwärme es 3 bis 5 Minuten bei kleiner Hitze, ohne zu kochen. Zerreibe das Kasuri Methi zwischen den Handflächen, röste es 10 Sekunden in einer trockenen Pfanne und streue es darüber. Das Aroma erinnert an Ahornsirup und Heu. Schmecke noch einmal ab: Das Gericht soll buttrig, mild säuerlich, leicht süß und tief würzig sein.","dauer":5,"tipp":"Kasuri Methi nie mitkochen, es wird sonst bitter."},{"titel":"Dhungar-Rauch (optional)","aktion":"raeuchern","text":"Halte ein Stück Holzkohle mit einer Zange in die Flamme, bis es durch und durch glüht. Lege eine kleine Schale in den Topf, setze die Kohle hinein und träufle einen Teelöffel Ghee darüber. Decke sofort ab und lasse den Rauch 1 bis 2 Minuten wirken. Entferne Schale und Kohle. Der Rauch gibt dem Gericht das Aroma eines Tandoors oder Holzfeuers.","dauer":2,"tipp":"Zu lange Räucherung wird bitter – bei 2 Minuten stoppen."},{"titel":"Anrichten","aktion":"anrichten","text":"Fülle das Dal Makhani in eine vorgewärmte Schüssel und ziehe einen Wirbel Sahne über die Oberfläche. Setze einen kleinen Klecks Butter in die Mitte und streue ein paar dünne Ingwerstreifen und frischen Koriander darauf. Serviere es sofort mit frischem Naan, Roti oder Jeera-Reis, dazu rohe Zwiebelringe mit Zitrone, deren Frische die Reichhaltigkeit ausgleicht. Am nächsten Tag schmeckt es noch besser, weil die Linsen weiter Aroma aufnehmen; erwärme es dann bei kleiner Hitze mit einem Schuss Wasser.","dauer":0,"tipp":"Dal Makhani lässt sich gut einfrieren."}],"profitipps":["Lange und langsam köcheln – so wird es cremig statt nur breiig.","Linsen erst nach dem Weichkochen salzen.","Butter und Sahne erst zum Schluss zugeben.","Kasuri Methi zerrieben und kurz geröstet verwenden.","Dhungar (Räuchern mit Holzkohle) gibt Dhaba-Aroma."],"varianten":["Ohne Rajma nur mit Urad-Linsen.","Vegane Version mit Kokosmilch und Öl.","Schnelle Version im Schnellkochtopf in rund 60 Minuten.","Dhaba-Stil mit mehr Röstzwiebeln und Rauch."],"beilagen":["Naan oder Roti","Jeera-Reis","Zwiebel-Salat","Raita"],"getraenk":"Lassi, Chai oder ein kräftiger Rotwein.","koeche":[],"quellen":[{"titel":"Dal makhani – Wikipedia","url":"https://en.wikipedia.org/wiki/Dal_makhani"},{"titel":"Dal Makhani Recipe (Authentic Punjabi Style) – Veg Recipes of India","url":"https://www.vegrecipesofindia.com/dal-makhani-recipe-dhaba-style/"},{"titel":"Garam masala – Wikipedia","url":"https://en.wikipedia.org/wiki/Garam_masala"}],"bild":"eintopf","farben":["#5a2e1a","#a0522d","#e8c39e"],"schlagworte":["Linsen","Punjab","Slow Cooking","Garam Masala"],"vegetarisch_moeglich":true},{"id":"indien-chana-masala","name":"Chana Masala","originalname":"Chole Masala","kueche":"indien","region":"Nordindien (Punjab/Delhi)","beliebtheit":88,"hauptkategorie":"vegan","fleischsorte":"","gang":"hauptgericht","kurz":"Kichererbsen in einer dunklen, säuerlich-würzigen Tomaten-Zwiebel-Sauce – herzhaft, satt und vollständig vegan.","hintergrund":"Chana Masala, auch Chole genannt, ist ein Kichererbsen-Curry aus Nordindien und wird besonders mit Punjab und Delhi verbunden. Es steht auf Imbiss- und Restaurantkarten, am bekanntesten zusammen mit frittierten Bhatura als Chole Bhature, das im TasteAtlas-Ranking indischer Gerichte vorne mitspielt. Typisch sind Amchur (Mangopulver) und Anardana (getrocknete Granatapfelkerne) für Säure, eine kräftig gebräunte Zwiebel-Basis und eine dunkle Farbe, für die in vielen Küchen ein Teebeutel mitgekocht wird.","portionen":4,"zeit":{"vorbereitung":20,"garen":70,"ruhen":600},"schwierigkeit":1,"zutaten":[{"gruppe":"Kichererbsen","liste":[{"menge":250,"einheit":"g","name":"getrocknete Kichererbsen","hinweis":"über Nacht eingeweicht; alternativ 2 Dosen à 400 g"},{"menge":1,"einheit":"Stück","name":"schwarzer Teebeutel","hinweis":"färbt die Kichererbsen dunkel"},{"menge":1,"einheit":"Stück","name":"Lorbeerblatt","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Masala","liste":[{"menge":3,"einheit":"EL","name":"Öl oder Ghee","hinweis":""},{"menge":1,"einheit":"TL","name":"Kreuzkümmelsamen","hinweis":""},{"menge":2,"einheit":"Stück","name":"große Zwiebeln","hinweis":"fein gehackt"},{"menge":1,"einheit":"EL","name":"Ingwer-Knoblauch-Paste","hinweis":""},{"menge":2,"einheit":"Stück","name":"grüne Chilischoten","hinweis":""},{"menge":3,"einheit":"Stück","name":"reife Tomaten","hinweis":"püriert"},{"menge":1,"einheit":"EL","name":"Koriandersamen, geröstet und gemahlen","hinweis":""},{"menge":1,"einheit":"TL","name":"Kreuzkümmel, geröstet und gemahlen","hinweis":""},{"menge":1,"einheit":"TL","name":"Anardana (Granatapfelkerne), gemahlen","hinweis":"optional"},{"menge":1,"einheit":"TL","name":"Kashmiri-Chilipulver","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":1,"einheit":"TL","name":"Amchur (Mangopulver)","hinweis":"ersatzweise Zitronensaft"},{"menge":1,"einheit":"TL","name":"Garam Masala","hinweis":"selbst gemischt"},{"menge":1,"einheit":"Handvoll","name":"frischer Koriander","hinweis":""},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]}],"ausruestung":["Schwerer Topf mit Deckel","Kleine Pfanne zum Rösten","Mörser","Kartoffelstampfer"],"schritte":[{"titel":"Mise en place und Einweichen","aktion":"vorbereiten","text":"Spüle die Kichererbsen ab und weiche sie in reichlich kaltem Wasser mindestens 8 Stunden ein. Sie nehmen das Doppelte ihres Volumens auf. Das Einweichen verkürzt die Garzeit und lässt sie gleichmäßig weich werden. Gieße das Wasser ab und spüle sie noch einmal. Hacke Zwiebeln, Ingwer, Knoblauch und Chilis fein und püriere die Tomaten. Stelle alle Gewürze bereit.","dauer":0,"tipp":"Eine Prise Natron im Einweichwasser macht sie besonders zart."},{"titel":"Kichererbsen mit Tee kochen","aktion":"kochen","text":"Gib die eingeweichten Kichererbsen mit frischem Wasser, Teebeutel, Lorbeer und Salz in einen Topf und bringe sie zum Kochen. Schöpfe den Schaum ab, reduziere die Hitze und lasse sie 45 bis 60 Minuten halb abgedeckt köcheln, im Schnellkochtopf 20 Minuten. Der Tee färbt die Kichererbsen leicht braun und gibt eine dezente Herbe. Sie sind fertig, wenn sie sich zwischen den Fingern leicht zerdrücken lassen. Entferne den Teebeutel und bewahre das Kochwasser auf, du brauchst es später.","dauer":55,"tipp":"Das Kochwasser ist aromatisch und besser als frisches Wasser für die Sauce."},{"titel":"Gewürze rösten und mahlen","aktion":"braten","text":"Röste Koriandersamen und Kreuzkümmel in einer trockenen Pfanne bei kleiner Hitze 60 bis 90 Sekunden, bis sie nussig duften und leicht dunkler werden. Gib sie auf einen Teller und lasse sie abkühlen, bevor du sie im Mörser fein zerstößt. Das Rösten verstärkt das Aroma und nimmt die Rohheit. Brennen sie an, riechen sie bitter und beißend; dann beginne neu.","dauer":5,"tipp":"Gemahlene Gewürze verlieren schnell Aroma – röste nur die Menge, die du brauchst."},{"titel":"Zwiebeln dunkel braten","aktion":"anbraten","text":"Erhitze das Öl in einem schweren Topf bei mittlerer Hitze, gib den Kreuzkümmel hinein und warte 20 Sekunden bis er zischt. Füge die Zwiebeln hinzu und brate sie unter häufigem Rühren 15 bis 20 Minuten, bis sie tief goldbraun und weich sind. Das ist der Grundton des Gerichts. Wenn sie ansetzen, gib einen Esslöffel Wasser dazu. Gib Ingwer, Knoblauch und Chili dazu und brate 1 bis 2 Minuten, bis der rohe Geruch verfliegt.","dauer":20,"tipp":"Geduld lohnt sich: Je dunkler die Zwiebeln, desto tiefer die Sauce, aber nicht schwarz."},{"titel":"Tomaten und Gewürze einkochen","aktion":"koecheln","text":"Gib die pürierten Tomaten, Kurkuma, Chilipulver und die gemahlenen Gewürze zu den Zwiebeln und koche 10 bis 12 Minuten bei mittlerer Hitze, bis sich Öl am Rand abgesetzt hat und die Masse dunkel und dick ist. Rühre häufig. Das abgesetzte Öl ist das Zeichen, dass die Gewürze gar sind. Probiere: Es sollte keine rohe Tomatensäure mehr schmecken.","dauer":12,"tipp":"Ein kleiner Spritzer Wasser verhindert Anbrennen, wenn die Masse zu trocken wird."},{"titel":"Kichererbsen zugeben","aktion":"schmoren","text":"Gib die abgetropften Kichererbsen in die Masala und rühre gut um, damit alle Kichererbsen überzogen sind. Gieße etwa 250 ml Kochwasser dazu und lasse alles 15 bis 20 Minuten bei kleiner Hitze leise köcheln. Zerdrücke einen Teil der Kichererbsen mit dem Löffelrücken am Topfrand, so bindet die Sauce natürlich. Die Sauce ist fertig, wenn sie dickflüssig ist und die Kichererbsen darin glänzen.","dauer":20,"tipp":"Bei Dosen-Kichererbsen genügen 10 Minuten Kochzeit in der Sauce."},{"titel":"Amchur und Garam Masala","aktion":"abschmecken","text":"Rühre Amchur und Garam Masala ein und koche alles noch 2 Minuten bei kleiner Hitze. Das Garam Masala wird bewusst spät zugegeben, damit seine flüchtigen, süßlich-warmen Aromen nicht verfliegen. Schmecke mit Salz und etwas Zitronensaft ab; die Sauce soll deutlich säuerlich, würzig und leicht scharf sein. Fehlt die Säure, gib einen weiteren halben Teelöffel Amchur oder einen Spritzer Zitronensaft dazu, denn sie hebt alle anderen Gewürze hervor.","dauer":2,"tipp":"Säure am Schluss anpassen – sie hebt alle Gewürze hervor."},{"titel":"Anrichten","aktion":"garnieren","text":"Fülle das Chana Masala in eine vorgewärmte Schüssel und streue gehackten Koriander, feine rohe Zwiebelringe und ein paar Ingwerstreifen darüber. Serviere es mit frittierten Bhatura, Roti oder Basmatireis und lege Zitronenspalten und grüne Chilischoten dazu, damit sich jeder die Säure und Schärfe selbst einstellen kann. Am zweiten Tag schmeckt es besonders gut, weil die Gewürze durchgezogen sind; beim Aufwärmen gibst du einen Schuss Wasser dazu.","dauer":0,"tipp":"Chana Masala eignet sich hervorragend zum Vorkochen und Einfrieren."}],"profitipps":["Teebeutel mitkochen für dunkle Farbe und leichte Herbe.","Zwiebeln geduldig dunkel braten.","Gewürze frisch rösten und mahlen.","Amchur oder Anardana für die typische Säure nutzen.","Kochwasser der Kichererbsen für die Sauce aufheben."],"varianten":["Amritsari Chole mit mehr Anardana und trockener Konsistenz.","Chole Bhature mit frittiertem Hefebrot.","Mit Spinat als Palak Chana.","Schnelle Variante mit Dosen-Kichererbsen."],"beilagen":["Bhatura oder Roti","Jeera-Reis","Zwiebel-Salat","Raita"],"getraenk":"Lassi, Chai oder ein kühles Bier.","koeche":[],"quellen":[{"titel":"Chana masala – Wikipedia","url":"https://en.wikipedia.org/wiki/Chana_masala"},{"titel":"TasteAtlas Top 10 Indian dishes – Deccan Herald","url":"https://deccanherald.com/lifestyle/food-and-drink/from-chole-bhature-to-butter-chicken-tasteatlas-top-10-indian-dishes-3090780"},{"titel":"Garam masala – Wikipedia","url":"https://en.wikipedia.org/wiki/Garam_masala"}],"bild":"curry","farben":["#a8581e","#d9953a","#f0dcae"],"schlagworte":["Vegan","Kichererbsen","Punjab","Chole"],"vegetarisch_moeglich":true},{"id":"indien-masala-dosa-sambar","name":"Masala Dosa mit Sambar","originalname":"","kueche":"indien","region":"Südindien (Tamil Nadu/Karnataka)","beliebtheit":87,"hauptkategorie":"vegan","fleischsorte":"","gang":"hauptgericht","kurz":"Hauchdünne, knusprige Reis-Linsen-Crêpes mit würziger Kartoffelfüllung, dazu Sambar und Kokos-Chutney – das südindische Frühstück schlechthin.","hintergrund":"Masala Dosa wurde in den 1930er-Jahren in Madras (Chennai) von K. Krishna Rao in seinen Udupi-Restaurants bekannt gemacht; eine ältere Legende nennt Köche am Hof von Mysore, wird aber wegen der erst im 16. Jahrhundert mit den Portugiesen eingeführten Kartoffeln bezweifelt. Der Teig besteht aus Reis und geschälten schwarzen Linsen (Urad) und gärt über Nacht. Dazu gehört Sambar, ein Linsen-Gemüse-Eintopf mit Tamarinde, den die Überlieferung auf den Hof der Marathen in Thanjavur zurückführt. Dosa wird in Südindien zu jeder Tageszeit gegessen.","portionen":4,"zeit":{"vorbereitung":60,"garen":90,"ruhen":960},"schwierigkeit":3,"zutaten":[{"gruppe":"Dosa-Teig (ca. 10 Dosas)","liste":[{"menge":300,"einheit":"g","name":"Parboiled-Reis oder Idli-Reis","hinweis":"ersatzweise Rundkornreis; parboiled gelingt am besten"},{"menge":100,"einheit":"g","name":"geschälte schwarze Urad-Dal (weiß)","hinweis":"im Asialaden"},{"menge":1,"einheit":"TL","name":"Bockshornkleesamen (Methi)","hinweis":"unterstützt Gärung und Bräunung"},{"menge":2,"einheit":"EL","name":"Poha (Reisflocken)","hinweis":"für knusprige Ränder"},{"menge":1.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":4,"einheit":"EL","name":"Öl zum Backen","hinweis":"oder Ghee"}]},{"gruppe":"Kartoffelmasala","liste":[{"menge":600,"einheit":"g","name":"Kartoffeln, mehligkochend","hinweis":"gekocht und grob zerdrückt"},{"menge":2,"einheit":"EL","name":"Öl","hinweis":""},{"menge":1,"einheit":"TL","name":"Senfsamen","hinweis":""},{"menge":1,"einheit":"EL","name":"Chana Dal und Urad Dal gemischt","hinweis":"für Biss, optional"},{"menge":10,"einheit":"Stück","name":"Curryblätter","hinweis":"frisch oder tiefgekühlt"},{"menge":2,"einheit":"Stück","name":"Zwiebeln, in Scheiben","hinweis":""},{"menge":2,"einheit":"Stück","name":"grüne Chilischoten","hinweis":""},{"menge":1,"einheit":"EL","name":"Ingwer, gerieben","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":1,"einheit":"Prise","name":"Asafoetida (Hing)","hinweis":""},{"menge":1,"einheit":"EL","name":"Zitronensaft","hinweis":""}]},{"gruppe":"Sambar","liste":[{"menge":150,"einheit":"g","name":"Toor Dal (Tauben-Erbsen-Linsen)","hinweis":"gewaschen"},{"menge":400,"einheit":"g","name":"gemischtes Gemüse (Kürbis, Möhre, Aubergine, Zwiebel)","hinweis":"in 3 cm Stücken"},{"menge":1,"einheit":"EL","name":"Tamarindenpaste","hinweis":"in 100 ml heißem Wasser gelöst"},{"menge":2,"einheit":"EL","name":"Sambar-Gewürzpulver","hinweis":"selbst gemischt: siehe Schritt oder gekauft"},{"menge":1,"einheit":"Stück","name":"Tomate","hinweis":"gewürfelt"},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":1,"einheit":"EL","name":"Jaggery oder Zucker","hinweis":""},{"menge":2,"einheit":"EL","name":"Kokosöl","hinweis":"für Tadka"},{"menge":1,"einheit":"TL","name":"Senfsamen","hinweis":""},{"menge":12,"einheit":"Stück","name":"Curryblätter","hinweis":""},{"menge":2,"einheit":"Stück","name":"getrocknete rote Chilis","hinweis":""},{"menge":1,"einheit":"Prise","name":"Asafoetida (Hing)","hinweis":""}]},{"gruppe":"Sambar-Gewürzmischung (frisch geröstet)","liste":[{"menge":2,"einheit":"EL","name":"Koriandersamen","hinweis":""},{"menge":1,"einheit":"EL","name":"Chana Dal","hinweis":""},{"menge":1,"einheit":"TL","name":"Kreuzkümmelsamen","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Bockshornkleesamen","hinweis":""},{"menge":4,"einheit":"Stück","name":"getrocknete rote Chilischoten","hinweis":""},{"menge":8,"einheit":"Stück","name":"Curryblätter","hinweis":""}]}],"ausruestung":["Standmixer oder Wet-Grinder","Große gusseiserne Pfanne oder beschichtete Crêpe-Pfanne","Topf für Sambar","Kleine Pfanne für Tadka","Kelle oder Schöpflöffel","Halbe Zwiebel zum Einfetten"],"schritte":[{"titel":"Mise en place und Einweichen","aktion":"vorbereiten","text":"Wasche Reis und Urad Dal getrennt in mehreren Wassern, bis das Wasser klar ist. Weiche den Reis mit Poha in einer Schüssel, die Urad Dal mit den Bockshornkleesamen in einer anderen, jeweils in kaltem Wasser, 5 bis 6 Stunden ein. Gieße das Wasser nicht weg, du brauchst es zum Mahlen. Schneide Gemüse für den Sambar und koche Kartoffeln für die Füllung. Kleine Details am Anfang sparen später Zeit.","dauer":0,"tipp":"Urad Dal nicht länger als 6 Stunden einweichen, sonst wird sie glitschig."},{"titel":"Teig mahlen","aktion":"mischen","text":"Mahle zuerst die Urad Dal mit etwas Einweichwasser im Mixer 5 bis 8 Minuten zu einer sehr feinen, luftigen Creme; sie sollte stark aufgehen und fast wie Schlagsahne aussehen. Gib sie in eine große Schüssel. Mahle dann den Reis mit Poha zu einer feinkörnigen Paste, die sich noch ein wenig grießig anfühlt. Vermische beides mit den Händen, was Wärme und gärende Mikroorganismen einbringt. Salze erst nach der Gärung oder nutze nicht-jodiertes Salz. Der Teig soll dickflüssig wie Pfannkuchenteig sein.","dauer":20,"tipp":"Beim Mahlen eiskaltes Wasser nutzen, damit der Mixer den Teig nicht erhitzt und die Gärung nicht stört."},{"titel":"Teig gären lassen","aktion":"gehen","text":"Decke die Schüssel mit einem Tuch ab, ohne den Deckel zu verschließen, und stelle sie 8 bis 12 Stunden an einen warmen Ort (ideal 28 bis 32 °C); der Backofen mit eingeschalteter Lampe ist gut. Der Teig ist fertig, wenn er sein Volumen etwa verdoppelt hat, Blasen zeigt und angenehm säuerlich-hefig riecht. Rühre ihn nicht zu stark um, damit die Luft erhalten bleibt. Gib dann Salz hinzu und verdünne ihn mit wenig Wasser auf die Konsistenz von dünnem Pfannkuchenteig.","dauer":600,"tipp":"Im Winter hilft ein vorgewärmter Ofen (nur 40 °C) für die Gärung."},{"titel":"Sambar-Gewürze rösten und mahlen","aktion":"braten","text":"Erhitze eine trockene Pfanne bei kleiner bis mittlerer Hitze und röste zuerst Chana Dal 1 Minute, dann Koriander, Kreuzkümmel, Bockshornklee und Chilis weitere 1 bis 2 Minuten, bis alles duftet und leicht nachdunkelt. Gib zuletzt die Curryblätter dazu, 20 Sekunden, bis sie knusprig werden. Bockshornklee verbrennt schnell und wird dann sehr bitter, also früh vom Herd. Lasse alles abkühlen und mahle es zu einem feinen Pulver.","dauer":6,"tipp":"Beim Rösten gilt: Die Gewürze sollen duften, nicht rauchen."},{"titel":"Toor Dal und Gemüse garen","aktion":"kochen","text":"Koche die gewaschene Toor Dal mit Kurkuma und 700 ml Wasser 25 bis 30 Minuten weich, im Schnellkochtopf 12 Minuten, bis sie zerfällt und sich leicht zerdrücken lässt. Rühre sie glatt. Gib in einem zweiten Topf Gemüse mit 300 ml Wasser und Tamarindenlösung hinzu und koche 10 bis 15 Minuten, bis es bissfest-weich ist. Die Säure der Tamarinde dämpft die Süße von Kürbis und Möhre.","dauer":30,"tipp":"Gemüse mit längerer Garzeit zuerst hineingeben."},{"titel":"Sambar vereinen","aktion":"koecheln","text":"Gib die glatt gerührte Dal zum Gemüse, füge das frisch gemahlene Sambar-Pulver, Tomate, Jaggery und Salz hinzu und lasse alles 10 bis 12 Minuten leise köcheln, bis der Sambar leicht sämig ist. Er soll weder zu dick noch zu dünn sein, ungefähr wie eine dicke Suppe. Probiere: Er soll gleichzeitig säuerlich, würzig, leicht süß und salzig sein. Fehlt Säure, gib Tamarinde dazu; ist er zu sauer, hilft ein Teelöffel Jaggery.","dauer":12,"tipp":"Sambar wird am nächsten Tag noch besser."},{"titel":"Tadka für Sambar","aktion":"braten","text":"Erhitze Kokosöl in einer kleinen Pfanne bei mittlerer Hitze, gib die Senfsamen hinein und warte, bis sie knackend aufspringen. Das dauert etwa 20 bis 30 Sekunden. Füge die getrockneten Chilis, Curryblätter und Asafoetida hinzu, rühre 10 bis 15 Sekunden und gieße das Ganze sofort in den Sambar. Es zischt und duftet; decke den Topf kurz ab, damit die Aromen einziehen. Die Senfsamen müssen vor allem in der richtigen Reihenfolge zuerst, sonst werden die Curryblätter verbrannt.","dauer":3,"tipp":"Nie die Pfanne unbeaufsichtigt lassen, Senfsamen springen und verbrennen schnell."},{"titel":"Kartoffelmasala zubereiten","aktion":"anbraten","text":"Erhitze Öl in einer Pfanne bei mittlerer Hitze, gib Senfsamen und Dal hinein und warte, bis die Senfsamen aufspringen. Füge Curryblätter, Asafoetida, Zwiebeln und Chilis hinzu und brate 6 bis 8 Minuten, bis die Zwiebeln weich und leicht glasig sind. Gib Ingwer und Kurkuma dazu, dann die grob zerdrückten Kartoffeln, Salz und einen kleinen Schuss Wasser. Brate 5 Minuten und gib am Ende Zitronensaft zu. Die Füllung soll weich, aber nicht matschig sein.","dauer":15,"tipp":"Kartoffeln nur grob zerdrücken, Stücke geben Biss."},{"titel":"Dosa-Pfanne vorbereiten","aktion":"vorbereiten","text":"Erhitze die Pfanne bei mittlerer bis hoher Hitze, bis ein Tropfen Wasser zischend verdampft. Reibe die Oberfläche mit einer halben Zwiebel, die du auf eine Gabel gesteckt und in Öl getaucht hast, ein. Das reinigt, fettet und sorgt für Haftung. Lass die Pfanne kurz abkühlen, indem du einen Schluck Wasser darübersprenkelst und mit einem Tuch auswischst, sonst wird der Teig nicht gleichmäßig. Eine heiße, aber nicht rauchende Pfanne ist die Voraussetzung für dünne Dosas.","dauer":3,"tipp":"Zu heiße Pfanne: Der Teig gerinnt, bevor du ihn verteilt hast."},{"titel":"Dosa ausstreichen und backen","aktion":"braten","text":"Gib eine Kelle Teig in die Mitte der Pfanne und verstreiche ihn sofort mit dem Boden der Kelle in kreisenden Bewegungen von der Mitte nach außen zu einem dünnen Kreis von etwa 25 cm. Träufle etwas Öl rund um den Rand und über die Fläche. Backe die Dosa 2 bis 3 Minuten, bis der Boden tief goldbraun und knusprig ist und sich der Rand vom Pfannenboden löst. Das Wenden ist bei dünnen Dosas nicht nötig. Die Oberfläche soll nicht mehr feucht, sondern matt aussehen.","dauer":3,"tipp":"Die erste Dosa gelingt selten perfekt – sie ist die Testdosa."},{"titel":"Füllen, falten und anrichten","aktion":"fuellen","text":"Gib zwei Esslöffel Kartoffelmasala auf eine Hälfte der Dosa und klappe die andere Hälfte darüber oder rolle die Dosa zusammen. Serviere sie sofort, solange sie knusprig ist, mit einer Schale Sambar und Kokos-Chutney. Der Sambar wird zum Eintunken verwendet. Weitere Dosas backst du portionsweise und hältst sie nicht lange warm, sonst werden sie weich.","dauer":0,"tipp":"Teigreste halten sich im Kühlschrank 3 Tage."}],"profitipps":["Der Teig braucht Wärme zum Gären – im Winter ruhig den Ofen mit Lampe nutzen.","Eine heiße, aber nicht rauchende Pfanne ist das Geheimnis für dünne Dosas.","Sambar-Pulver frisch rösten und mahlen, es macht den Unterschied.","Tadka immer zum Schluss in den Sambar gießen.","Die erste Dosa ist meist ein Probestück."],"varianten":["Paper Dosa: größer und hauchdünn.","Rava Dosa mit Grieß, ohne Gärung.","Set Dosa: kleine, dicke Dosas.","Mysore Masala Dosa mit roter Chutney-Paste unter der Füllung."],"beilagen":["Kokos-Chutney","Tomaten-Chutney","Sambar","Filterkaffee"],"getraenk":"Südindischer Filterkaffee oder Buttermilch.","koeche":[],"quellen":[{"titel":"Masala dosa – Wikipedia","url":"https://en.wikipedia.org/wiki/Masala_dosa"},{"titel":"Sambar (dish) – Wikipedia","url":"https://en.wikipedia.org/wiki/Sambar_(dish)"},{"titel":"Dal – Wikipedia","url":"https://en.wikipedia.org/wiki/Dal"},{"titel":"The art of tadka – World Spice Cooks Club","url":"https://cooksclub.worldspice.com/posts/32-the-art-of-tadka-indian-tempering-technique-explained"}],"bild":"pfannkuchen","farben":["#c58a3c","#e9c27a","#6e4a1c"],"schlagworte":["Südindien","Fermentiert","Frühstück","Vegan"],"vegetarisch_moeglich":true},{"id":"indien-rogan-josh","name":"Rogan Josh","originalname":"Roghan Josh","kueche":"indien","region":"Nordindien (Kaschmir)","beliebtheit":86,"hauptkategorie":"fleisch","fleischsorte":"lamm","gang":"hauptgericht","kurz":"Zartes Lamm in tiefroter, duftender Sauce mit Fenchel, getrocknetem Ingwer und Kashmiri-Chili – mild, aromatisch und ohne Tomaten.","hintergrund":"Rogan Josh ist ein Klassiker der kaschmirischen Küche und Teil des festlichen Wazwan-Menüs. Die Mughals sollen das Gericht im 16. Jahrhundert nach Nordindien gebracht haben, es geht vermutlich auf persische Fleischgerichte in heißem Fett zurück. Der Name wird entweder aus dem persischen roghan (Fett, Öl) und josh (Hitze, Schmoren) hergeleitet oder aus kaschmirisch roghan (rot). Die rote Farbe stammt traditionell von Ratan Jot (Alkannawurzel), Mawal (Hahnenkamm-Blüten) oder mildem Kashmiri-Chili, nicht von Tomaten oder viel Schärfe. Es gibt zwei Traditionen: die der Kaschmiri Pandits ohne Zwiebel und Knoblauch, mit Asafoetida und Fenchel, und die muslimische Wazwan-Variante mit Knoblauch, Schalotten und Safran.","portionen":4,"zeit":{"vorbereitung":25,"garen":90,"ruhen":120},"schwierigkeit":3,"zutaten":[{"gruppe":"Fleisch und Marinade","liste":[{"menge":900,"einheit":"g","name":"Lammschulter, mit Knochen, in 4 cm Stücken","hinweis":"Knochenstücke geben Körper; ersatzweise entbeinte Keule"},{"menge":150,"einheit":"g","name":"Vollmilchjoghurt","hinweis":"Raumtemperatur, glatt gerührt"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Gewürze und Fett","liste":[{"menge":3,"einheit":"EL","name":"Senföl","hinweis":"bis zum leichten Rauchen erhitzen, dann abkühlen lassen, um die Schärfe zu mildern; ersatzweise Ghee"},{"menge":2,"einheit":"EL","name":"Ghee","hinweis":""},{"menge":5,"einheit":"Stück","name":"Gewürznelken","hinweis":""},{"menge":5,"einheit":"Stück","name":"grüne Kardamomkapseln","hinweis":""},{"menge":1,"einheit":"Stück","name":"schwarze Kardamomkapsel","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zimtstange (Cassia), 5 cm","hinweis":""},{"menge":1,"einheit":"Stück","name":"Lorbeerblatt","hinweis":""},{"menge":1,"einheit":"Prise","name":"Asafoetida (Hing)","hinweis":""},{"menge":2,"einheit":"TL","name":"gemahlener Fenchel","hinweis":"frisch geröstet und gemahlen"},{"menge":1.5,"einheit":"TL","name":"gemahlener getrockneter Ingwer (Sonth)","hinweis":"ersatzweise 1 EL frischer Ingwer, fein gerieben"},{"menge":2,"einheit":"EL","name":"Kashmiri-Chilipulver","hinweis":"für Farbe; das Pulver ist mild"},{"menge":1,"einheit":"Prise","name":"Safranfäden","hinweis":"in 2 EL warmem Wasser eingeweicht"},{"menge":1,"einheit":"TL","name":"kaschmirisches Garam Masala","hinweis":"Kardamom, Zimt, Nelken, Pfeffer frisch gerieben"},{"menge":1,"einheit":"TL","name":"Rote-Bete-Pulver oder 1 kleine gekochte Rote Bete (püriert)","hinweis":"natürliche Farbe; Ersatz für schwer erhältliche Ratan Jot"}]}],"ausruestung":["Schwerer Schmortopf (Gusseisen) mit Deckel","Kleine Pfanne zum Rösten","Mörser","Feines Sieb"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Lege das Lammfleisch 30 Minuten vor dem Kochen auf Raumtemperatur, damit es im heißen Fett nicht Wasser zieht. Schneide es in 4 cm große Stücke, lasse Knochen und etwas Fett dran, denn beides trägt Aroma. Tupfe es trocken. Rühre den Joghurt mit einer Gabel glatt, damit er später nicht flockt. Weiche den Safran in 2 Esslöffeln warmem Wasser ein. Röste Fenchelsamen kurz trocken an und mahle sie, sobald sie abgekühlt sind. Stelle alle Gewürze in Schälchen bereit, denn die Schritte folgen schnell aufeinander.","dauer":30,"tipp":"Trockenes Fleisch bräunt besser; feuchtes dämpft nur."},{"titel":"Garam Masala frisch mahlen","aktion":"braten","text":"Röste 4 Kardamomkapseln, ein kleines Stück Zimt, 3 Nelken und 5 Pfefferkörner in einer trockenen Pfanne bei kleiner Hitze etwa 45 bis 60 Sekunden, bis sie warm und süßlich duften. Schwenke ständig. Lass sie auf einem Teller auskühlen und zerstoße sie im Mörser fein. Dieses kaschmirische Garam Masala ist weniger kräftig als die Mischung aus dem Punjab und kommt erst am Schluss ins Gericht, damit die flüchtigen Aromen erhalten bleiben. Verbrenne die Gewürze nicht; sonst riecht die Mischung beißend und bitter.","dauer":3,"tipp":"Kleine Mengen rösten sich schneller und gleichmäßiger – bleib dabei."},{"titel":"Senföl und ganze Gewürze tempern","aktion":"braten","text":"Erhitze das Senföl in einem schweren Topf, bis es leicht raucht und der scharfe Geruch verfliegt (etwa 1 Minute); das nimmt dem Öl die beißende Note. Lasse es kurz abkühlen, gib Ghee dazu und erhitze wieder bei mittlerer Hitze. Gib Nelken, grüne und schwarze Kardamomkapseln, Zimt und Lorbeer hinein und warte 20 bis 30 Sekunden, bis die Nelken aufquellen, die Kardamomkapseln leicht aufplatzen und es intensiv würzig duftet. Dieses sogenannte Tempern in heißem Fett löst fettlösliche Aromastoffe. Dunkeln die Gewürze zu schnell, nimm den Topf kurz vom Herd.","dauer":3,"tipp":"Das Senföl muss wirklich rauchen, sonst bleibt es scharf wie Senf."},{"titel":"Fleisch anbraten","aktion":"anbraten","text":"Gib die Lammstücke in zwei Portionen in das heiße, gewürzte Fett, damit die Temperatur nicht abfällt. Brate jede Portion 6 bis 8 Minuten, wende gelegentlich und lasse jede Seite wirklich braun werden. Das Fleisch sollte außen eine goldbraune Kruste haben, die Röststoffe erzeugt; sie sind das Fundament des Aromas. Wenn es kocht statt brät, ist der Topf überfüllt. Nimm die erste Portion heraus, brate die zweite und gib alles zurück in den Topf.","dauer":15,"tipp":"Wende das Fleisch erst, wenn es sich leicht vom Topfboden löst – klebt es noch, ist die Kruste nicht fertig."},{"titel":"Joghurt einarbeiten","aktion":"binden","text":"Nimm den Topf vom Herd und lasse ihn 1 Minute abkühlen. Rühre den Joghurt esslöffelweise ein und rühre ständig, damit er nicht gerinnt. Setze den Topf wieder auf mittlere Hitze und rühre weiter, bis der Joghurt vollständig mit dem Fett verbunden ist. Koche so lange (5 bis 8 Minuten), bis die Sauce Öl absondert und der Joghurt geteilt aussieht; das ist hier gewollt. Dann ist die Säure abgebaut und das Fett setzt sich ab. Schmecke das Fett an: Es soll nach Joghurt, nicht mehr nach Milch riechen.","dauer":8,"tipp":"Kalter Joghurt in heißes Fett geben lässt ihn flocken – Zimmertemperatur und langsames Einrühren verhindern das."},{"titel":"Gewürzpulver und Chili zugeben","aktion":"braten","text":"Verrühre Fenchel, Ingwerpulver, Hing und Kashmiri-Chilipulver in 100 ml kaltem Wasser zu einer glatten Paste. Gib die Paste in den Topf und brate sie unter Rühren 2 bis 3 Minuten, bis das Wasser verdampft ist und sich das Fett wieder an den Rändern sammelt. Das Wasser schützt die Gewürze vor Verbrennen, während sie aufschließen. Die Farbe wird jetzt sattrot und der Duft süßlich-würzig. Salze das Gericht.","dauer":4,"tipp":"Chilipulver in trockener Hitze verbrennt in Sekunden – deshalb die Wasserpaste."},{"titel":"Schmoren","aktion":"schmoren","text":"Gieße 400 ml heißes Wasser dazu, bringe alles zum Kochen, setze den Deckel schräg auf und reduziere die Hitze auf die kleinste Stufe. Lasse das Lamm 60 bis 75 Minuten schmoren, rühre alle 15 Minuten um und gieße bei Bedarf etwas heißes Wasser nach. Das Fleisch ist fertig, wenn es sich mühelos vom Knochen löst und mit der Gabel zerfällt. Die Sauce soll sämig und rot glänzen. Ist sie zu dünn, nimm den Deckel ab und lasse sie zum Schluss einkochen.","dauer":75,"tipp":"Heißes Wasser nachgießen, kaltes bremst das Garen und lässt das Fleisch zäh werden."},{"titel":"Farbe und Safran","aktion":"abschmecken","text":"Rühre Rote-Bete-Pulver oder die pürierte Rote Bete ein, um die Farbe zu vertiefen. Sie schmeckt nicht, färbt aber das Gericht schön dunkelrot, so wie früher die Ratan-Jot-Wurzel. Gib den eingeweichten Safran samt Wasser dazu und lasse alles 3 Minuten ziehen. Rühre das frische Garam Masala unter und schmecke mit Salz ab. Die Sauce soll warm, mild, würzig und leicht süßlich schmecken, nicht scharf. Wenn sie flach wirkt, hilft eine Prise Salz oder etwas mehr Fenchel.","dauer":5,"tipp":"Vivek Singh nennt in einem Festtagsmenü Rote Bete als Ersatz für die schwer erhältliche Ratan-Jot-Wurzel."},{"titel":"Ruhen lassen","aktion":"ruhen","text":"Nimm den Topf vom Herd und lasse das Gericht 15 bis 20 Minuten mit Deckel ruhen. Die Aromen verbinden sich, das Fett sammelt sich oben und das Fleisch zieht nach. Schöpfe überschüssiges rotes Öl nach Geschmack ab, lasse aber etwas davon, es trägt den Geschmack. Rogan Josh schmeckt am nächsten Tag noch besser. Erwärme es dann bei kleiner Hitze mit einem Schuss Wasser.","dauer":20,"tipp":"Das rote Fett ist ein Aromaträger; schöpfe es nicht komplett ab."},{"titel":"Anrichten","aktion":"anrichten","text":"Fülle das Rogan Josh in eine vorgewärmte Schüssel, gieße das rote Fett darüber und garniere mit ein paar Safranfäden oder frischen Korianderblättern. Serviere es mit Basmatireis oder Naan. In Kaschmir isst man dazu oft Reis, Joghurt und einen Salat aus rohen Zwiebeln. Die Zwiebel bringt Frische und Schärfe, die zur tiefen, würzigen Sauce passt.","dauer":0,"tipp":"Reichlich Sauce zum Reis servieren, sie ist das Beste am Gericht."}],"profitipps":["Senföl vor dem Gebrauch bis zum Rauchen erhitzen, dann abkühlen lassen.","Joghurt bei Zimmertemperatur einrühren, damit er nicht flockt.","Chili und Gewürze in einer Wasserpaste zugeben, so verbrennen sie nicht.","Rogan Josh ist ein Kaschmir-Gericht ohne Tomaten; Tomaten sind eine Ersatzfarbe, wenn Ratan Jot fehlt.","Lange und langsam schmoren, dann zerfällt das Fleisch."],"varianten":["Kaschmiri-Pandit-Version ohne Zwiebel und Knoblauch, mit Hing und Fenchel.","Wazwan-Version mit Knoblauch, Schalotten und Safran, ohne Joghurt.","Westliche Variante mit Tomaten und Zwiebeln.","Lammhaxe langsam im Ofen geschmort, wie in britischen Restaurants."],"beilagen":["Basmatireis","Naan oder Roti","Zwiebel-Salat","Joghurt"],"getraenk":"Kräftiger Rotwein wie Syrah oder ein Lagerbier; traditionell Kahwa (Safran-Tee).","koeche":[{"name":"Ranveer Brar","bezug":"Auf seiner Website steht ein Rezept für Rogan Josh nach Kaschmiri-Art, das mit Senföl, Fenchel, getrocknetem Ingwer, Asafoetida, Safran und Ratanjot arbeitet.","quelle":"https://ranveerbrar.com/?p=3658"},{"name":"Vivek Singh","bezug":"Serviert in einem Festtagsmenü für Delicious Magazine eine Kashmiri-Lammhaxe als Rogan Josh und ersetzt die schwer erhältliche Ratanjot-Wurzel durch Rote Bete.","quelle":"https://www.deliciousmagazine.co.uk/?p=51282"}],"quellen":[{"titel":"Rogan josh – Wikipedia","url":"https://en.wikipedia.org/wiki/Rogan_josh"},{"titel":"The truth about Rogan Josh – Free Press Journal","url":"https://www.freepressjournal.in/food/the-truth-about-rogan-josh"},{"titel":"Rogan Josh – Ranveer Brar","url":"https://ranveerbrar.com/?p=3658"},{"titel":"Vivek Singh's celebration dinner menu – Delicious Magazine","url":"https://www.deliciousmagazine.co.uk/?p=51282"}],"bild":"curry","farben":["#a8231a","#d9552b","#f0cf9a"],"schlagworte":["Kaschmir","Lamm","Wazwan","Schmorgericht"],"vegetarisch_moeglich":false},{"id":"indien-paneer-tikka","name":"Paneer Tikka","originalname":"","kueche":"indien","region":"Nordindien (Punjab)","beliebtheit":85,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"vorspeise","kurz":"Gegrillte Paneer-Würfel mit Paprika und Zwiebel in würziger Joghurt-Marinade – außen angekohlt, innen weich.","hintergrund":"Paneer Tikka ist die vegetarische Antwort auf Chicken Tikka und wird in Nordindien vor allem in Restaurants und bei Festen serviert. Paneer, ein frischer Käse, der beim Erhitzen nicht schmilzt, wird in Joghurt und Gewürzen mariniert, mit Paprika, Zwiebeln und Tomaten auf Spieße gesteckt und im Tandoor gegrillt. Er wird mit Zitrone und Chaat Masala bestreut und zu Minz-Chutney gereicht. Beliebte Abwandlungen sind Paneer Tikka Masala in Sauce, Paneer-Rolls im Fladenbrot und gefüllter Paneer nach Kaschmiri-Art.","portionen":4,"zeit":{"vorbereitung":25,"garen":20,"ruhen":120},"schwierigkeit":1,"zutaten":[{"gruppe":"Tikka","liste":[{"menge":400,"einheit":"g","name":"Paneer","hinweis":"in 3 cm Würfeln"},{"menge":1,"einheit":"Stück","name":"rote Paprika","hinweis":"in 3 cm Stücken"},{"menge":1,"einheit":"Stück","name":"gelbe Paprika","hinweis":""},{"menge":1,"einheit":"Stück","name":"rote Zwiebel","hinweis":"in Stücken, Schichten lose"}]},{"gruppe":"Marinade","liste":[{"menge":200,"einheit":"g","name":"Joghurt, abgetropft","hinweis":"Griechischer Joghurt geht auch"},{"menge":2,"einheit":"EL","name":"Kichererbsenmehl (Besan)","hinweis":"trocken angeröstet, bindet die Marinade"},{"menge":1,"einheit":"EL","name":"Ingwer-Knoblauch-Paste","hinweis":""},{"menge":1,"einheit":"TL","name":"Kashmiri-Chilipulver","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Ajwain","hinweis":"optional"},{"menge":1,"einheit":"TL","name":"Garam Masala","hinweis":"selbst gemischt"},{"menge":1,"einheit":"TL","name":"Kasuri Methi","hinweis":"zerrieben"},{"menge":1,"einheit":"TL","name":"Amchur oder 1 EL Zitronensaft","hinweis":""},{"menge":2,"einheit":"EL","name":"Senföl oder Öl","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Zum Servieren","liste":[{"menge":1,"einheit":"TL","name":"Chaat Masala","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zitrone","hinweis":"in Spalten"},{"menge":1,"einheit":"Handvoll","name":"frischer Koriander","hinweis":""}]}],"ausruestung":["Metallspieße oder eingeweichte Holzspieße","Backofen mit Grill oder Grillpfanne","Backblech mit Rost"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide den Paneer in 3 cm große Würfel; kleinere Stücke trocknen im Grill aus, größere bleiben saftig. Tupfe ihn mit Küchenpapier trocken. Schneide Paprika und Zwiebel in gleich große Stücke und trenne die Zwiebelschichten voneinander. Lasse den Joghurt 30 Minuten im Sieb abtropfen, damit die Marinade dick wird und am Käse haftet. Weiche Holzspieße 30 Minuten in Wasser ein, damit sie im Ofen nicht verbrennen.","dauer":30,"tipp":"Nimm den Paneer kurz vor dem Marinieren aus dem Kühlschrank; kalt bleibt er im Kern kühl."},{"titel":"Besan rösten","aktion":"braten","text":"Röste das Kichererbsenmehl in einer trockenen Pfanne bei kleiner Hitze 1 bis 2 Minuten unter ständigem Rühren, bis es nussig riecht und leicht Farbe annimmt. Das Rösten nimmt den rohen, bohnigen Geschmack und gibt eine feine Röstnote. Gib es auf einen Teller und lasse es abkühlen. Es bindet später die Marinade und sorgt dafür, dass sie am Käse haftet und eine Kruste bildet.","dauer":3,"tipp":"Rühre ständig; Besan verbrennt in Sekunden."},{"titel":"Marinade anrühren","aktion":"mischen","text":"Verrühre den abgetropften Joghurt mit Besan, Ingwer-Knoblauch-Paste, Chilipulver, Ajwain, Garam Masala, Kasuri Methi, Amchur, Salz und Öl zu einer dicken, cremigen Paste. Sie soll beim Anheben des Löffels kurz an ihm hängen bleiben. Ist sie zu flüssig, gib mehr Besan dazu. Schmecke die Marinade ab: Sie sollte etwas salziger sein als gewünscht, weil der Käse sie ausgleicht. Rühre sie 1 Minute kräftig, damit sie glatt wird.","dauer":3,"tipp":"Dicke Marinade gleich dicke Kruste – wässrige läuft vom Käse ab."},{"titel":"Marinieren","aktion":"marinieren","text":"Gib Paneer und Gemüse in die Marinade und wende alles vorsichtig mit den Händen, damit der Käse nicht zerbricht. Decke es ab und stelle es 2 bis 4 Stunden in den Kühlschrank. Paneer nimmt Aromen langsam auf, aber nicht beliebig viel; länger als 6 Stunden bringt nichts. Das Gemüse nimmt die Marinade ebenfalls an und bekommt mehr Geschmack.","dauer":0,"tipp":"Hole alles 20 Minuten vor dem Grillen aus dem Kühlschrank."},{"titel":"Aufspießen","aktion":"formen","text":"Stecke abwechselnd Paneer, Paprika und Zwiebel auf die Spieße und lasse zwischen den Stücken etwas Platz, damit die Hitze überall hinkommt. Drücke nicht zu fest, sonst brechen die Würfel. Beginne und ende mit Paprika oder Zwiebel, sie halten den Käse an Ort und Stelle. Lege die Spieße auf ein Gitter über ein mit Alufolie ausgelegtes Blech.","dauer":10,"tipp":"Zwei parallele Spieße pro Portion halten die Würfel stabiler beim Wenden."},{"titel":"Grillen","aktion":"grillen","text":"Heize den Backofen auf Grillstufe oder 250 °C Ober-/Unterhitze (Umluft 230 °C) vor und setze den Rost auf die oberste Schiene. Grille die Spieße 8 bis 10 Minuten, wende sie nach der Hälfte und beobachte die Farbe. Der Paneer soll an den Rändern goldbraun mit dunklen Röstflecken sein, das Gemüse an den Kanten leicht angekohlt. Bestreiche die Spieße zum Schluss kurz mit etwas Öl oder Ghee, damit sie glänzen. Zu lange gegrillt wird Paneer gummiartig.","dauer":10,"tipp":"Paneer verträgt hohe Hitze, aber nur kurz – sonst wird er fest."},{"titel":"Würzen und Servieren","aktion":"garnieren","text":"Nimm die Spieße aus dem Ofen und lasse sie 2 Minuten ruhen. Streue Chaat Masala und einen Spritzer Zitronensaft darüber, das hebt die Aromen und gibt eine säuerlich-salzige Note. Streue gehackten Koriander darüber. Serviere sofort mit Minz-Chutney und Zwiebelringen. Paneer Tikka schmeckt am besten warm; kalt wird er fest.","dauer":2,"tipp":"Chaat Masala nie vor dem Grillen aufstreuen, es verbrennt schnell."},{"titel":"Anrichten","aktion":"anrichten","text":"Schiebe die Stücke vom Spieß auf eine vorgewärmte Platte oder serviere sie direkt am Spieß. Lege Zitronenspalten, rohe rote Zwiebelringe und eine Schale Minz-Chutney dazu, deren Frische die Würze ausgleicht. Wer es als Hauptgericht möchte, reicht Paneer Tikka mit Naan und einer kühlen Gurken-Raita. Reste kannst du am nächsten Tag in einem Fladenbrot mit Zwiebeln und Chutney zu einem Wrap aufrollen, kalt wird der Käse allerdings fest.","dauer":0,"tipp":"Als Paneer Tikka Masala funktioniert es auch in einer Tomaten-Sahne-Sauce."}],"profitipps":["Joghurt abtropfen lassen, dann haftet die Marinade.","Besan trocken rösten für Bindung und Röstaroma.","Hohe Hitze, kurze Zeit – Paneer wird sonst gummiartig.","Würfel nicht zu klein schneiden.","Chaat Masala erst nach dem Grillen aufstreuen."],"varianten":["Paneer Tikka Masala in Tomaten-Sahne-Sauce.","Hariyali Paneer Tikka mit Minze-Koriander-Marinade.","Paneer-Tikka-Roll im Roti mit Zwiebeln und Chutney.","Mit Mandeln gefüllt nach Kaschmiri-Art."],"beilagen":["Minz-Chutney","Zwiebelringe mit Zitrone","Naan","Raita"],"getraenk":"Kühles Lagerbier, Lassi oder ein trockener Riesling.","koeche":[],"quellen":[{"titel":"Paneer tikka – Wikipedia","url":"https://en.wikipedia.org/wiki/Paneer_tikka"},{"titel":"Tandoor – Wikipedia","url":"https://en.wikipedia.org/wiki/Tandoor"}],"bild":"spiess","farben":["#d9722a","#f2b04a","#6b8f3a"],"schlagworte":["Vegetarisch","Grill","Vorspeise","Tikka"],"vegetarisch_moeglich":true},{"id":"indien-aloo-gobi","name":"Aloo Gobi","originalname":"","kueche":"indien","region":"Nordindien (Punjab)","beliebtheit":84,"hauptkategorie":"vegan","fleischsorte":"","gang":"hauptgericht","kurz":"Trocken gebratener Blumenkohl mit Kartoffeln, Kurkuma und Kreuzkümmel – einfach, aromatisch und im Alltag Nordindiens allgegenwärtig.","hintergrund":"Aloo Gobi (aloo = Kartoffel, gobi = Blumenkohl) ist ein vegetarisches Alltagsgericht aus Nordindien und ebenso in Nepal, Bengalen und Pakistan beliebt. Es wird trocken (sukha) zubereitet: Das Gemüse gart im eigenen Dampf mit Gewürzen, nicht in einer Sauce. Kurkuma gibt die gelbe Farbe, Kreuzkümmel und Koriander die Würze, Amchur die Säure. Gegessen wird es mit Roti, Paratha oder als Teil eines Thali mit Dal und Reis.","portionen":4,"zeit":{"vorbereitung":20,"garen":35,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Gemüse","liste":[{"menge":600,"einheit":"g","name":"Blumenkohl","hinweis":"in kleine Röschen, gewaschen und trocken getupft"},{"menge":400,"einheit":"g","name":"festkochende Kartoffeln","hinweis":"in 2 cm Würfeln"}]},{"gruppe":"Gewürze und Würzbasis","liste":[{"menge":4,"einheit":"EL","name":"Öl oder Ghee","hinweis":""},{"menge":1,"einheit":"TL","name":"Kreuzkümmelsamen","hinweis":""},{"menge":1,"einheit":"Prise","name":"Asafoetida (Hing)","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zwiebel","hinweis":"fein gehackt"},{"menge":1,"einheit":"EL","name":"Ingwer, fein gerieben","hinweis":""},{"menge":3,"einheit":"Zehe","name":"Knoblauch","hinweis":"gehackt"},{"menge":2,"einheit":"Stück","name":"grüne Chilischoten","hinweis":""},{"menge":1,"einheit":"Stück","name":"Tomate","hinweis":"gewürfelt"},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":1,"einheit":"TL","name":"gemahlener Koriander","hinweis":""},{"menge":1,"einheit":"TL","name":"Kashmiri-Chilipulver","hinweis":""},{"menge":1,"einheit":"TL","name":"Amchur","hinweis":"oder Zitronensaft"},{"menge":1,"einheit":"TL","name":"Garam Masala","hinweis":""},{"menge":1,"einheit":"Handvoll","name":"frischer Koriander","hinweis":""},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]}],"ausruestung":["Große, schwere Pfanne mit Deckel","Holzlöffel","Schüssel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Teile den Blumenkohl in gleichmäßige kleine Röschen und wasche sie; tupfe sie danach gut trocken, weil nasses Gemüse dämpft statt bräunt. Schäle die Kartoffeln und schneide sie in etwa 2 cm große Würfel. Hacke Zwiebel, Ingwer, Knoblauch und Chilis fein, würfle die Tomate. Stelle alle Gewürze in kleinen Schälchen bereit, damit du später nicht suchen musst.","dauer":0,"tipp":"Röschen und Kartoffeln in ähnlicher Größe sorgen für gleichmäßige Garung."},{"titel":"Blumenkohl anrösten","aktion":"anbraten","text":"Erhitze die Hälfte des Öls in einer großen Pfanne bei mittlerer bis hoher Hitze. Gib die Blumenkohlröschen hinein und brate sie 6 bis 8 Minuten, ohne sie ständig zu bewegen, bis sie an mehreren Seiten goldbraun sind. Streue eine Prise Salz darüber und nimm sie dann heraus. Diese Röstung gibt süßlich-nussiges Aroma und verhindert, dass der Kohl später zerkocht. Wenn er zu dunkel wird, ist die Hitze zu hoch.","dauer":8,"tipp":"Nicht überfüllen: Röschen sollen den Pfannenboden berühren, sonst dämpfen sie."},{"titel":"Kartoffeln anbraten","aktion":"anbraten","text":"Gib das restliche Öl in die Pfanne und brate die Kartoffelwürfel bei mittlerer Hitze 8 bis 10 Minuten, bis sie an den Rändern goldgelb und außen leicht knusprig sind. Streue eine Prise Salz und Kurkuma darüber. Die Kartoffeln sind noch nicht gar, das geschieht später im Dampf. Nimm sie ebenfalls heraus, oder schiebe sie an den Rand, wenn die Pfanne groß ist.","dauer":10,"tipp":"Kartoffeln trocken tupfen, sonst spritzen sie und kleben an."},{"titel":"Gewürze temperieren","aktion":"braten","text":"Gib bei Bedarf noch einen Esslöffel Öl in die Pfanne. Erhitze es bei mittlerer Hitze, gib Kreuzkümmelsamen hinein und warte etwa 20 Sekunden, bis sie zischen und nach Nuss duften. Füge Hing hinzu. Gib dann die Zwiebel dazu und brate 6 bis 8 Minuten, bis sie goldgelb ist. Gib Ingwer, Knoblauch und Chili dazu und brate eine Minute weiter, bis der rohe Geruch verfliegt. Dieses Anbraten der Gewürze in heißem Fett (Tadka) setzt fettlösliche Aromen frei.","dauer":10,"tipp":"Kreuzkümmel nicht dunkel werden lassen – braun heißt bitter."},{"titel":"Pulvergewürze und Tomate","aktion":"braten","text":"Nimm die Pfanne kurz vom Herd und streue Koriander, Chilipulver und etwas Kurkuma hinein, rühre 10 Sekunden und stelle die Pfanne wieder auf die Flamme. Gib sofort die Tomate dazu und brate sie 3 bis 4 Minuten, bis sie zerfällt und die Masse kompakt wird. Das Fett setzt sich am Rand ab. Gemahlene Gewürze verbrennen schnell und werden bitter, daher kurz vom Herd nehmen.","dauer":5,"tipp":"Ein Schuss Wasser rettet angebrannte Gewürze nicht – lieber neu beginnen."},{"titel":"Gemüse zurückgeben und dämpfen","aktion":"daempfen","text":"Gib Kartoffeln und Blumenkohl zurück in die Pfanne, mische vorsichtig, damit alle Stücke mit Masala überzogen sind, und gib 3 bis 4 Esslöffel Wasser dazu. Decke die Pfanne ab und gare das Gemüse 10 bis 12 Minuten bei kleiner Hitze im eigenen Dampf, rühre nur ein- oder zweimal um. Die Kartoffeln sind gar, wenn ein Messer leicht eindringt, der Blumenkohl ist noch bissfest. Gieße kein zusätzliches Wasser nach, das Gericht soll trocken bleiben.","dauer":12,"tipp":"Zu viel Rühren zerstört die Röschen – einfach schütteln."},{"titel":"Amchur, Garam Masala und Abschmecken","aktion":"abschmecken","text":"Nimm den Deckel ab, streue Amchur und Garam Masala darüber und rühre vorsichtig um. Brate alles noch 2 bis 3 Minuten ohne Deckel, damit die Feuchtigkeit verdampft und das Gemüse leicht anröstet. Schmecke mit Salz ab und gib Zitronensaft hinzu, wenn dir die Säure fehlt. Das Gemüse soll weich, aber noch mit Struktur sein, die Gewürze haften als trockene Kruste.","dauer":3,"tipp":"Garam Masala erst am Schluss, sonst verfliegt das Aroma."},{"titel":"Anrichten","aktion":"anrichten","text":"Gib das Aloo Gobi in eine vorgewärmte Schüssel und streue frisch gehackten Koriander darüber. Serviere es heiß mit Roti oder Paratha oder als Teil eines Thali mit Dal, Reis und Raita. Frische Zitronenspalten und rohe Zwiebelringe dazu ergänzen die Säure und bringen Frische. Ein Löffel Ghee obendrauf gibt Glanz und Aroma. Reste schmecken am nächsten Tag auch kalt im Fladenbrot-Sandwich.","dauer":0,"tipp":"Ein Löffel Ghee obendrauf gibt Glanz und Aroma."}],"profitipps":["Blumenkohl getrennt anrösten, so wird er nicht matschig.","Gemüse nicht überladen und nicht ständig rühren.","Gewürzpulver nur kurz in das heiße Fett – sie verbrennen schnell.","Wenig Wasser und Deckel: Das Gemüse gart im eigenen Dampf.","Amchur zum Schluss bringt die typische Säure."],"varianten":["Mit Erbsen für Süße und Farbe.","Mit Tomaten-Zwiebel-Sauce als Aloo Gobi Masala.","Punjabi-Stil mit Ingwerstreifen und Kasuri Methi.","Im Ofen geröstet bei 220 °C Ober-/Unterhitze."],"beilagen":["Roti oder Paratha","Dal Tadka","Jeera-Reis","Raita"],"getraenk":"Lassi, Chai oder ein kühles Bier.","koeche":[],"quellen":[{"titel":"Aloo gobi – Wikipedia","url":"https://en.wikipedia.org/wiki/Aloo_gobi"},{"titel":"Tadka: the simple Indian cooking technique – SBS Food","url":"https://www.sbs.com.au/food/article/tadka-the-simple-indian-cooking-technique-you-should-know/8nucpkdcu"}],"bild":"pfanne","farben":["#e0b23a","#f0d98a","#8aa05a"],"schlagworte":["Vegan","Alltagsküche","Trockencurry","Blumenkohl"],"vegetarisch_moeglich":true},{"id":"indien-gulab-jamun","name":"Gulab Jamun","originalname":"","kueche":"indien","region":"Nordindien (Mughal-Küche)","beliebtheit":83,"hauptkategorie":"suess","fleischsorte":"","gang":"dessert","kurz":"Weiche, goldbraun frittierte Milchbällchen, die in Rosen-Kardamom-Sirup baden – das Festtagsdessert Indiens.","hintergrund":"Gulab Jamun entstand in der Mughal-Zeit aus persischen und lokalen Einflüssen. Gulab leitet sich vom persischen Wort für Rosenwasser ab, Jamun heißt die javanische Pflaume, der die Bällchen in Größe und Farbe ähneln. Traditionell werden sie aus Khoya geformt, dem eingekochten Milchfeststoff, der mit etwas Mehl verknetet, in Ghee frittiert und in Zuckersirup mit Kardamom, Rosenwasser oder Safran getränkt wird. Heute nehmen viele Haushalte Milchpulver, das schnell geht. Gulab Jamun wird warm serviert, oft mit Eis oder Rabri.","portionen":6,"zeit":{"vorbereitung":25,"garen":30,"ruhen":120},"schwierigkeit":2,"zutaten":[{"gruppe":"Teig (ca. 18 Stück)","liste":[{"menge":150,"einheit":"g","name":"Vollmilchpulver","hinweis":"kein Magermilchpulver; alternativ 250 g Khoya, gerieben"},{"menge":3,"einheit":"EL","name":"Weizenmehl","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Backpulver","hinweis":"nicht mehr; sonst platzen die Bällchen"},{"menge":1,"einheit":"EL","name":"Ghee, zerlassen","hinweis":""},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":5,"einheit":"EL","name":"lauwarme Milch","hinweis":"nach und nach"}]},{"gruppe":"Sirup","liste":[{"menge":400,"einheit":"g","name":"Zucker","hinweis":""},{"menge":500,"einheit":"ml","name":"Wasser","hinweis":""},{"menge":5,"einheit":"Stück","name":"grüne Kardamomkapseln","hinweis":"angedrückt"},{"menge":1,"einheit":"Prise","name":"Safranfäden","hinweis":"optional"},{"menge":1,"einheit":"TL","name":"Rosenwasser","hinweis":"oder Kewra-Wasser"},{"menge":1,"einheit":"TL","name":"Zitronensaft","hinweis":"verhindert Auskristallisieren"}]},{"gruppe":"Zum Frittieren","liste":[{"menge":500,"einheit":"ml","name":"Ghee oder neutrales Öl","hinweis":""},{"menge":1,"einheit":"EL","name":"gehackte Pistazien","hinweis":"zum Garnieren"}]}],"ausruestung":["Kleiner, tiefer Topf zum Frittieren","Fritierthermometer","Topf für Sirup","Schaumlöffel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege alle Zutaten ab. Siebe Milchpulver, Mehl und Backpulver zusammen in eine Schüssel, damit keine Klumpen entstehen. Wärme die Milch leicht an. Zerlasse das Ghee. Bereite einen Teller mit leichtem Öl-Film vor, auf dem du die geformten Bällchen ablegen kannst. Lege Kardamom, Safran und Rosenwasser für den Sirup bereit. Alle Zutaten sollten Zimmertemperatur haben, kalte Zutaten erschweren das Kneten.","dauer":0,"tipp":"Eingeölte Hände verhindern, dass der Teig an den Fingern klebt."},{"titel":"Zuckersirup kochen","aktion":"koecheln","text":"Gib Zucker, Wasser und die angedrückten Kardamomkapseln in einen Topf und erhitze unter Rühren, bis sich der Zucker aufgelöst hat. Koche den Sirup 5 bis 7 Minuten ohne Rühren, bis er leicht klebrig ist, aber noch dünn fließt (Einfaden-Konsistenz ist nicht nötig). Gib Safran, Rosenwasser und Zitronensaft dazu und halte ihn warm bei kleiner Hitze. Der Sirup soll warm, nicht kochend sein, wenn die Bällchen hineinkommen. Ist er zu dick, kristallisiert er; zu dünn zieht er nicht ein.","dauer":10,"tipp":"Der Zitronensaft verhindert das Auskristallisieren des Zuckers."},{"titel":"Teig kneten","aktion":"kneten","text":"Gib Ghee zur Milchpulvermischung und reibe es mit den Fingerspitzen ein, bis feine Krümel entstehen. Gib die Milch esslöffelweise dazu und knete nur sanft, bis ein weicher, glatter Teig entsteht. Knete nicht zu lange, denn überknetet wird der Teig zäh und die Bällchen werden hart. Der Teig soll weich sein wie Knetmasse und leicht an den Fingern haften, ohne zu kleben. Decke ihn ab und lasse ihn 10 Minuten ruhen.","dauer":12,"tipp":"Wenn der Teig reißt, gib einen halben Teelöffel Milch dazu."},{"titel":"Bällchen formen","aktion":"formen","text":"Forme aus dem Teig kleine Kugeln von etwa 2,5 cm, rolle sie zwischen eingeölten Handflächen, bis die Oberfläche völlig glatt und rissfrei ist. Risse in der Oberfläche führen beim Frittieren zum Aufplatzen. Die Bällchen werden beim Frittieren etwa doppelt so groß, deshalb nicht größer formen. Lege sie auf den eingeölten Teller und decke sie ab, damit sie nicht austrocknen.","dauer":10,"tipp":"Rolle die Kugeln lange – ein glatter Ball reißt nicht."},{"titel":"Langsam frittieren","aktion":"frittieren","text":"Erhitze Ghee oder Öl auf nur 120 bis 130 °C; es soll kaum rauchen. Gib 5 bis 6 Bällchen vorsichtig hinein. Sie sinken und steigen nach etwa 30 Sekunden wieder auf. Rühre das Fett sanft um sie herum, damit sie sich drehen, und frittiere sie 8 bis 10 Minuten, bis sie gleichmäßig tief goldbraun sind. Bei zu hoher Hitze bräunen sie außen, bleiben innen roh und platzen. Hole sie mit dem Schaumlöffel heraus.","dauer":10,"tipp":"Ein Test: Ein Teigstück sollte in 5 Sekunden aufsteigen, nicht sofort sprudeln."},{"titel":"Im Sirup tränken","aktion":"einlegen","text":"Lasse die frittierten Bällchen 1 Minute abtropfen und gib sie warm in den warmen Sirup. Kalte Bällchen in heißem Sirup oder umgekehrt ziehen den Sirup nicht gleichmäßig auf. Lasse sie mindestens 1 Stunde im Sirup ziehen; sie saugen sich voll und werden weich und saftig. Zum Test schneidest du eine in der Mitte durch: Sie soll durch und durch gleichmäßig braun und saftig sein, ohne trockenen Kern.","dauer":60,"tipp":"Je länger sie ziehen, desto saftiger werden sie."},{"titel":"Anrichten","aktion":"anrichten","text":"Serviere die Gulab Jamun warm oder zimmerwarm in einer Schale mit etwas Sirup und streue gehackte Pistazien darüber. Sie schmecken pur oder mit einer Kugel Vanilleeis, denn der Kontrast aus warm und kalt ist besonders reizvoll. Reste halten sich im Sirup im Kühlschrank bis zu fünf Tage; erwärme sie vor dem Servieren sanft im Wasserbad oder kurz in der Mikrowelle, damit sie wieder weich werden.","dauer":0,"tipp":"Ein paar Safranfäden auf dem Sirup machen sie festlich."}],"profitipps":["Vollmilchpulver verwenden, nicht Magermilchpulver.","Teig nur kurz kneten, damit die Bällchen weich bleiben.","Bei niedriger Temperatur (120 bis 130 °C) frittieren, damit sie durchgaren.","Bällchen warm in warmen Sirup geben.","Oberfläche glatt rollen, damit sie nicht reißen."],"varianten":["Kala Jamun, dunkler, mit karamellisiertem Zucker im Teig.","Mit Khoya statt Milchpulver, die klassische Version.","Gefüllt mit Pistazien oder Rosinen.","Gulab Jamun mit Eiscreme oder Rabri."],"beilagen":["Vanilleeis","Rabri","Pistazien","Chai"],"getraenk":"Masala Chai oder ein Dessertwein.","koeche":[],"quellen":[{"titel":"Gulab jamun – Wikipedia","url":"https://en.wikipedia.org/wiki/Gulab_jamun"},{"titel":"Khoya – Wikipedia","url":"https://en.wikipedia.org/wiki/Khoya"}],"bild":"dessert","farben":["#7a3a1a","#b8651f","#e8b86a"],"schlagworte":["Dessert","Festtag","Milchspeise","Rosenwasser"],"vegetarisch_moeglich":true},{"id":"indien-goan-vindaloo","name":"Goan Vindaloo","originalname":"Vindalho","kueche":"indien","region":"Südindien (Goa)","beliebtheit":82,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"hauptgericht","kurz":"Schweinefleisch in einer feurig-sauren Paste aus Chilis, Knoblauch und Essig – das goanische Original hinter dem britischen Curry-House-Klassiker.","hintergrund":"Vindaloo geht auf das portugiesische Gericht carne de vinha d'alhos (Fleisch in Knoblauchwein) zurück, das Goa im 16. Jahrhundert erreichte. Köche in Goa ersetzten den Wein durch Palmessig und Tamarinde und gaben Chilis und Gewürze hinzu. Das ursprüngliche Vindalho enthält Schwein, Essig, Knoblauch und Gewürze, aber keine Kartoffeln; sie kamen durch das Missverständnis mit dem Hindi-Wort aloo in manche Versionen. In Großbritannien wurde Vindaloo zum Synonym für ein sehr scharfes Curry. Das Original ist eher säuerlich-aromatisch als nur scharf.","portionen":4,"zeit":{"vorbereitung":30,"garen":100,"ruhen":720},"schwierigkeit":2,"zutaten":[{"gruppe":"Fleisch","liste":[{"menge":900,"einheit":"g","name":"Schweinenacken","hinweis":"in 3 cm Würfeln; etwas Fett dran lassen"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Vindaloo-Paste","liste":[{"menge":10,"einheit":"Stück","name":"getrocknete Kashmiri-Chilischoten","hinweis":"geben Farbe und Aroma, wenig Schärfe; für mehr Feuer einige scharfe dazu"},{"menge":100,"einheit":"ml","name":"Apfelessig oder Weißweinessig","hinweis":"traditionell Palmessig; Aroma milder bei Apfelessig"},{"menge":8,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":3,"einheit":"Stück","name":"Stück Ingwer, 3 cm","hinweis":""},{"menge":2,"einheit":"TL","name":"Kreuzkümmelsamen","hinweis":""},{"menge":1,"einheit":"TL","name":"schwarze Pfefferkörner","hinweis":""},{"menge":6,"einheit":"Stück","name":"Gewürznelken","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zimtstange, 5 cm","hinweis":""},{"menge":1,"einheit":"TL","name":"Senfsamen","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":1,"einheit":"TL","name":"Zucker oder Jaggery","hinweis":""},{"menge":1,"einheit":"TL","name":"Tamarindenpaste","hinweis":"optional"}]},{"gruppe":"Sauce","liste":[{"menge":3,"einheit":"EL","name":"Öl oder Schweineschmalz","hinweis":""},{"menge":2,"einheit":"Stück","name":"Zwiebeln","hinweis":"fein gehackt"},{"menge":1,"einheit":"Stück","name":"Tomate","hinweis":"optional, gewürfelt"},{"menge":300,"einheit":"ml","name":"heißes Wasser","hinweis":""},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]}],"ausruestung":["Schwerer Schmortopf mit Deckel","Mixer oder Mörser","Kleine Pfanne zum Rösten","Schüssel zum Marinieren"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide das Schweinefleisch in etwa 3 cm große Würfel und lasse etwas Fett daran, denn es hält das Gericht saftig und trägt Aroma. Tupfe es trocken. Entkerne die Chilis teilweise, wenn du es milder möchtest; die Kerne enthalten die meiste Schärfe. Hacke Zwiebeln, schäle Knoblauch und Ingwer. Stelle den Essig, Zucker und Tamarindenpaste bereit. Das Gericht lebt von der Marinierzeit, plane also mindestens 8 Stunden ein.","dauer":0,"tipp":"Die Chilikerne bestimmen die Schärfe – mehr oder weniger Kerne regulieren das Feuer."},{"titel":"Gewürze rösten","aktion":"braten","text":"Röste Kreuzkümmel, Pfefferkörner, Nelken, Zimt und Senfsamen in einer trockenen Pfanne bei kleiner bis mittlerer Hitze 60 bis 90 Sekunden. Sobald die Senfsamen leise aufspringen, die Nelken aufquellen und es intensiv würzig duftet, nimm die Pfanne vom Herd. Lasse alles abkühlen. Das Rösten entwickelt eine süßlich-warme Tiefe, die ein Roh-Pulver nicht hat. Verbrennst du die Gewürze, entsteht Bitterkeit, die in der Paste nicht mehr zu retten ist.","dauer":3,"tipp":"Senfsamen springen – halte einen Deckel bereit."},{"titel":"Chilis einweichen und Paste mahlen","aktion":"puerieren","text":"Weiche die getrockneten Chilis 15 Minuten in warmem Essig und etwas Wasser ein, damit sie weich werden. Gib sie mit der Einweichflüssigkeit, den abgekühlten Gewürzen, Knoblauch, Ingwer, Kurkuma, Zucker und Tamarinde in einen Mixer und püriere alles zu einer glatten, tiefroten Paste. Falls sie zu dick ist, gib noch einen Schuss Essig dazu. Die Paste soll intensiv sauer, würzig und scharf riechen. Der Essig ist hier nicht nur Säure, er konserviert und macht das Fleisch zart.","dauer":20,"tipp":"Beim Mixen kann Dampf entstehen – lass die Paste kurz abkühlen, bevor du den Deckel öffnest."},{"titel":"Fleisch marinieren","aktion":"marinieren","text":"Vermische das Fleisch mit Salz und der Vindaloo-Paste und knete alles gründlich ein, damit jedes Stück bedeckt ist. Decke es ab und lasse es mindestens 8 Stunden, besser über Nacht, im Kühlschrank durchziehen. Die Säure lockert das Fleisch und die Gewürze dringen tief ein. Länger als 24 Stunden solltest du nicht marinieren, sonst wird die Oberfläche mürbe.","dauer":0,"tipp":"Hole das Fleisch 30 Minuten vor dem Kochen aus dem Kühlschrank."},{"titel":"Zwiebeln anbraten","aktion":"anbraten","text":"Erhitze das Öl in einem schweren Topf bei mittlerer Hitze und brate die gehackten Zwiebeln 12 bis 15 Minuten, bis sie weich und goldbraun sind. Rühre häufig, damit sie nicht anbrennen. Die Zwiebeln bilden die Basis der Sauce und geben ihr Süße, die den Essig ausgleicht. Wenn sie braun werden, bevor sie weich sind, ist die Hitze zu hoch. Sie sollen duften wie Karamell, nicht verbrannt riechen.","dauer":15,"tipp":"Eine Prise Salz hilft den Zwiebeln, schneller Wasser abzugeben."},{"titel":"Fleisch scharf anbraten","aktion":"anbraten","text":"Gib das marinierte Fleisch samt Paste in den Topf, erhöhe die Hitze und brate es 8 bis 10 Minuten unter häufigem Rühren, bis die Paste dunkler wird und sich Öl abzusetzen beginnt. Das Fleisch bekommt außen eine Kruste, und der rohe Essiggeruch verfliegt. Die Farbe wird tiefrot-braun und der Duft rund und würzig. Falls es ansetzt, gib einen Schuss Wasser dazu und löse den Bratensatz vom Boden.","dauer":10,"tipp":"Das Anbraten der Paste ist wichtig; sonst bleibt die Säure scharf und roh."},{"titel":"Schmoren","aktion":"schmoren","text":"Gieße das heiße Wasser dazu, bringe alles zum Kochen, setze den Deckel schräg auf und schmore das Fleisch bei kleinster Hitze 75 bis 90 Minuten. Rühre alle 20 Minuten um und gib bei Bedarf etwas Wasser dazu. Das Fleisch ist fertig, wenn es sich leicht mit der Gabel zerdrücken lässt und das Fett rot an der Oberfläche schwimmt. Die Sauce soll dick und glänzend sein. Ist sie zu dünn, nimm den Deckel ab und lasse sie einkochen.","dauer":90,"tipp":"Schweinenacken braucht Zeit; zu hohe Hitze macht ihn zäh."},{"titel":"Abschmecken","aktion":"abschmecken","text":"Schmecke die Sauce mit Salz, Zucker und etwas Essig ab. Sie soll gleichzeitig sauer, süß, scharf und würzig sein. Wenn sie zu sauer ist, hilft ein Teelöffel Zucker; fehlt Säure, ein Schuss Essig. Lasse den Vindaloo 15 Minuten ruhen. Die Aromen verbinden sich und die Sauce dickt leicht nach. Am nächsten Tag schmeckt er noch besser; erwärme ihn sanft.","dauer":15,"tipp":"Vindaloo wird traditionell einen Tag vorher gekocht."},{"titel":"Anrichten","aktion":"anrichten","text":"Serviere den Vindaloo heiß mit gedämpftem Basmatireis oder Goan Pao, einem weichen Brötchen, und einem kühlenden Gurkensalat. Garniere ihn mit frischem Koriander. Stelle Zitronenspalten und Joghurt auf den Tisch, damit jeder die Schärfe nach Wunsch mildern kann. In Goa isst man dazu oft schlicht Reis und trinkt ein Glas Feni oder ein kühles Bier.","dauer":0,"tipp":"Ein Löffel Joghurt neben der Sauce nimmt die Schärfe."}],"profitipps":["Chilikerne entfernen für milderes Vindaloo.","Essig und Gewürze bilden die Paste; sie muss gut angebraten werden.","Mindestens 8 Stunden marinieren.","Am nächsten Tag schmeckt Vindaloo am besten.","Kartoffeln gehören nicht ins Original."],"varianten":["Hähnchen- oder Rinder-Vindaloo.","Lamm-Vindaloo mit Lammschulter.","Entenvindaloo nach britischem Vorbild.","Mit Kartoffeln wie im britischen Curry House."],"beilagen":["Basmatireis oder Pao","Gurkensalat","Joghurt","Papad"],"getraenk":"Kühles Lagerbier oder ein Glas Feni (Goan Cashew-Schnaps).","koeche":[],"quellen":[{"titel":"Vindaloo – Wikipedia","url":"https://en.wikipedia.org/wiki/Vindaloo"}],"bild":"curry","farben":["#a8221a","#d85a2a","#f0c88a"],"schlagworte":["Goa","Schwein","Portugiesisch","Scharf-sauer"],"vegetarisch_moeglich":false},{"id":"indien-pani-puri","name":"Pani Puri","originalname":"Golgappa / Phuchka","kueche":"indien","region":"Nordindien (Uttar Pradesh/Delhi, landesweit verbreitet)","beliebtheit":81,"hauptkategorie":"vegan","fleischsorte":"","gang":"snack","kurz":"Knusprige, hohle Teigkugeln, gefüllt mit Kartoffeln und Kichererbsen und mit eiskaltem, minzig-scharfem Wasser geflutet – ein Streetfood, das man in einem Bissen essen muss.","hintergrund":"Pani Puri heißt in Delhi Golgappa, in Bengalen und Bihar Phuchka und in Rajasthan Pani ke Batashe. Wer das Gericht erfunden hat, ist unbekannt; Historiker nennen Varanasi und die Chaat-Tradition der Mughal-Zeit in Uttar Pradesh, als sich die Füllungen aus Kachori-Füllungen entwickelten. Verbreitet hat es sich vor allem im 20. Jahrhundert durch Binnenmigration. Die kleine, hohle Puri besteht meist aus Grieß, die Füllung aus Kartoffeln oder Kichererbsen; das Pani gibt es in einer scharfen grünen Minz-Variante und einer süßen Tamarinden-Variante. Man isst eine Puri nach der anderen, sofort nach dem Befüllen.","portionen":4,"zeit":{"vorbereitung":60,"garen":45,"ruhen":60},"schwierigkeit":2,"zutaten":[{"gruppe":"Puri (ca. 40 Stück)","liste":[{"menge":150,"einheit":"g","name":"feiner Grieß (Sooji/Rava)","hinweis":"Hartweizengrieß; fein gemahlener Grieß gelingt besser"},{"menge":2,"einheit":"EL","name":"Weizenmehl","hinweis":""},{"menge":1,"einheit":"Prise","name":"Backpulver","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"EL","name":"Öl","hinweis":"für den Teig"},{"menge":80,"einheit":"ml","name":"lauwarmes Wasser","hinweis":"nach Bedarf"},{"menge":700,"einheit":"ml","name":"Frittieröl","hinweis":""}]},{"gruppe":"Pani (würziges Minzwasser)","liste":[{"menge":1,"einheit":"Bund","name":"frische Minze","hinweis":"Blätter"},{"menge":0.5,"einheit":"Bund","name":"frischer Koriander","hinweis":""},{"menge":3,"einheit":"Stück","name":"grüne Chilischoten","hinweis":"nach Schärfewunsch"},{"menge":1,"einheit":"Stück","name":"Stück Ingwer, 2 cm","hinweis":""},{"menge":1,"einheit":"TL","name":"Kreuzkümmelsamen","hinweis":"trocken geröstet und gemahlen"},{"menge":1,"einheit":"TL","name":"Kala Namak (Schwarzsalz)","hinweis":"gibt den typischen schwefligen Geschmack; im Asialaden"},{"menge":1,"einheit":"TL","name":"Chaat Masala","hinweis":""},{"menge":2,"einheit":"EL","name":"Tamarindenpaste","hinweis":""},{"menge":2,"einheit":"EL","name":"Zitronensaft","hinweis":""},{"menge":800,"einheit":"ml","name":"Eiswasser","hinweis":""},{"menge":3,"einheit":"EL","name":"Boondi","hinweis":"frittierte Kichererbsenperlen, optional"}]},{"gruppe":"Süßes Tamarinden-Chutney (Imli)","liste":[{"menge":3,"einheit":"EL","name":"Tamarindenpaste","hinweis":""},{"menge":3,"einheit":"EL","name":"Jaggery oder brauner Zucker","hinweis":""},{"menge":1,"einheit":"TL","name":"Kreuzkümmel, geröstet und gemahlen","hinweis":""},{"menge":100,"einheit":"ml","name":"Wasser","hinweis":""}]},{"gruppe":"Füllung","liste":[{"menge":300,"einheit":"g","name":"gekochte Kartoffeln","hinweis":"mehligkochend, grob zerdrückt"},{"menge":150,"einheit":"g","name":"gekochte Kichererbsen","hinweis":"aus der Dose geht"},{"menge":1,"einheit":"Stück","name":"rote Zwiebel","hinweis":"sehr fein gehackt"},{"menge":1,"einheit":"TL","name":"Chaat Masala","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Kashmiri-Chilipulver","hinweis":""},{"menge":1,"einheit":"Handvoll","name":"frischer Koriander","hinweis":"gehackt"},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]}],"ausruestung":["Tiefer Topf oder Wok zum Frittieren","Fritierthermometer","Mixer","Feines Sieb","Nudelholz und Ausstecher (ca. 4 cm)","Küchentuch"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege alle Zutaten ab und teile sie in Puri, Pani, Chutney und Füllung. Koche die Kartoffeln in Salzwasser, bis sie weich sind, und lasse sie abkühlen. Gieße Wasser in einen Behälter und lege ihn mit Eiswürfeln ins Gefrierfach, denn das Pani muss richtig kalt sein. Wasche Minze und Koriander. Plane genug Zeit ein: Der Puri-Teig muss ruhen, und Pani und Chutney schmecken besser, wenn sie durchgezogen sind.","dauer":25,"tipp":"Je kälter das Pani, desto besser der Kontrast zur warmen, knusprigen Puri."},{"titel":"Puri-Teig kneten","aktion":"kneten","text":"Vermische Grieß, Mehl, Backpulver und Salz und gib Öl dazu. Füge lauwarmes Wasser esslöffelweise hinzu und knete 8 bis 10 Minuten zu einem sehr festen, glatten Teig, deutlich fester als Brotteig. Er soll sich anfühlen wie knetfester Ton. Zu weicher Teig lässt die Puri nicht hohl aufblasen, sondern saugt Fett. Decke den Teig mit einem feuchten Tuch ab und lasse ihn 30 Minuten ruhen, damit der Grieß quillt.","dauer":40,"tipp":"Wenn der Teig am Finger klebt, ist er zu weich; gib einen Teelöffel Grieß dazu."},{"titel":"Puri ausrollen","aktion":"ausrollen","text":"Knete den ruhenden Teig noch einmal 2 Minuten durch und rolle ihn auf einer leicht bemehlten Fläche sehr dünn aus, etwa 1,5 mm. Steche mit einem Ausstecher oder einem Glas Kreise von etwa 4 cm aus. Die Dicke ist entscheidend: Zu dick gibt keine Hohlkugel, zu dünn reißt. Lege die ausgestochenen Kreise unter ein feuchtes Tuch, damit sie nicht austrocknen, bis du frittierst. Verwende die Reste noch einmal, aber knete sie vorher kurz durch.","dauer":20,"tipp":"Gleichmäßig dünn ausrollen – so blasen alle Puri gleichzeitig auf."},{"titel":"Puri frittieren","aktion":"frittieren","text":"Erhitze das Öl auf 180 °C. Gib die Teigkreise portionsweise hinein (5 bis 6 Stück). Sie sinken kurz, dann steigen sie auf und blasen sich bei Berührung mit dem Löffel kugelig auf. Drücke sie sanft mit dem Löffel unter die Oberfläche, damit sie sich gleichmäßig aufblähen. Frittiere sie 1 bis 2 Minuten, bis sie goldgelb und völlig hohl sind. Sie müssen beim Anklopfen hohl klingen. Hole sie mit dem Schaumlöffel heraus, lasse sie auf Küchenpapier abtropfen und abkühlen; dabei werden sie knusprig.","dauer":20,"tipp":"Fällt die Hitze unter 170 °C, werden die Puri fettig und blasen nicht auf."},{"titel":"Pani ansetzen","aktion":"puerieren","text":"Püriere Minze, Koriander, Chilis, Ingwer, Tamarindenpaste, Kreuzkümmel, Kala Namak, Chaat Masala und etwa 200 ml Eiswasser zu einer feinen grünen Paste. Gib sie durch ein Sieb in einen Krug und drücke das Püree aus. Verdünne es mit dem restlichen Eiswasser und dem Zitronensaft. Schmecke ab: Das Pani soll scharf, sauer, salzig, kräftig minzig und leicht schwefelig schmecken. Lasse es mindestens 30 Minuten im Kühlschrank ziehen, sonst schmeckt es noch roh nach Kräutern.","dauer":35,"tipp":"Kala Namak riecht nach Eiern; das ist gewollt und gehört zum typischen Geschmack."},{"titel":"Süßes Tamarinden-Chutney kochen","aktion":"koecheln","text":"Koche Tamarindenpaste, Jaggery, gemahlenen Kreuzkümmel und Wasser in einem kleinen Topf 8 bis 10 Minuten bei mittlerer Hitze, bis der Zucker gelöst und die Mischung leicht sirupartig ist. Sie soll beim Abkühlen wie flüssiger Honig fließen. Zu stark eingekocht wird sie fest wie Karamell; dann gib einen Schuss Wasser dazu. Das Chutney muss süß-sauer schmecken, mit einem warmen, leicht rauchigen Ton. Lasse es abkühlen.","dauer":12,"tipp":"Nach dem Abkühlen wird das Chutney dicker; koche es nicht zu fest ein."},{"titel":"Füllung mischen","aktion":"mischen","text":"Zerdrücke die gekochten Kartoffeln grob mit einer Gabel, damit noch Stücke bleiben. Mische sie mit Kichererbsen, fein gehackter Zwiebel, Chaat Masala, Chilipulver, Salz und Koriander. Probiere die Füllung: Sie soll deutlich gewürzt, leicht scharf und säuerlich sein, weil Puri und Pani sie verdünnen. Wenn sie fad schmeckt, gib mehr Chaat Masala und Salz hinzu.","dauer":5,"tipp":"Die Füllung darf nicht zu feucht sein, sonst weicht die Puri sofort auf."},{"titel":"Befüllen und essen","aktion":"fuellen","text":"Stich mit dem Daumen ein Loch in die Oberseite einer Puri, gib einen Teelöffel Füllung hinein, träufle etwas süßes Chutney darauf und gieße kaltes Pani aus einem Löffel oder Krug ein. Iss die Puri sofort in einem Bissen, sonst weicht sie auf und läuft aus. Bereite immer nur wenige Stück gleichzeitig zu. Wer es nicht scharf mag, nutzt nur das süße Tamarinden-Wasser; scharfes und süßes Pani werden in Indien oft nebeneinander serviert.","dauer":0,"tipp":"Auf einer Platte anrichten und jeden Gast selbst befüllen lassen – das macht den Spaß aus."}],"profitipps":["Der Teig muss fest sein, sonst blasen die Puri nicht hohl auf.","Puri nach dem Frittieren vollständig abkühlen lassen, damit sie knusprig bleiben.","Pani gut kühlen und 30 Minuten ziehen lassen.","Erst im letzten Moment befüllen.","Kala Namak liefert den typischen Chaat-Geschmack."],"varianten":["Süßes Pani mit Tamarinde und Jaggery.","Pani mit Knoblauch und Asafoetida (Hing-Pani).","Dahi Puri mit Joghurt und Chutney statt Pani.","Puri aus Vollkornmehl (Atta) für herzhafteren Geschmack."],"beilagen":["Süßes Tamarinden-Chutney","Sev (Kichererbsen-Nudeln)","Granatapfelkerne","Joghurt"],"getraenk":"Kühles Lassi, Jaljeera oder ein Lagerbier.","koeche":[],"quellen":[{"titel":"Pani puri – Wikipedia","url":"https://en.wikipedia.org/wiki/Pani_puri"},{"titel":"Samosa (Chaat-Servierung) – Wikipedia","url":"https://en.wikipedia.org/wiki/Samosa"}],"bild":"gebaeck","farben":["#d9a845","#7aa84a","#f0e0b0"],"schlagworte":["Streetfood","Chaat","Vegan","Knusprig"],"vegetarisch_moeglich":true},{"id":"indien-sambar","name":"Sambar – südindischer Linsen-Gemüse-Eintopf mit Tamarinde","originalname":"சாம்பார்","kueche":"indien","region":"Tamil Nadu, Karnataka, Kerala","beliebtheit":80,"hauptkategorie":"vegan","fleischsorte":"","gang":"eintopf","kurz":"Der würzig-säuerliche Linseneintopf Südindiens: Toor Dal, saftiges Gemüse, Tamarinde und eine duftende Gewürzmischung, gekrönt von einem prasselnden Senfsamen-Tadka. Er gehört zu Idli, Dosa und Reis.","hintergrund":"Sambar ist das Herz der südindischen Küche. Eine bekannte Legende führt ihn auf den Hof der Maratha-Herrscher von Thanjavur im späten 17. Jahrhundert zurück: Ein Koch soll den kokum-gesäuerten Linsenfond Amti mit Tamarinde und Gemüse abgewandelt haben, und der Name stamme von Sambhaji, dem Gast. Historiker zweifeln die Geschichte an; ein kannadischer Text von 1648 beschreibt bereits ein ähnliches Gericht namens Huli. Heute hat jede Region und jede Familie ihre eigene Variante – in Karnataka mit mehr Süße und Kokos, in Tamil Nadu mit kräftiger Säure, in Kerala oft mit gerösteter Kokosnuss und Fenugreek. Gegessen wird Sambar zum Frühstück mit Idli, Vada und Dosa, mittags mit Reis und abends als Suppe. Der Trick liegt in der Balance aus Linsencremigkeit, Säure der Tamarinde, Schärfe der Chili und der erdigen Wärme der Gewürze.","portionen":4,"zeit":{"vorbereitung":30,"garen":45,"ruhen":30},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Linsen","liste":[{"menge":150,"einheit":"g","name":"Toor Dal (gespaltene Straucherbsen)","hinweis":"im Asialaden; ersatzweise geschälte gelbe Spalterbsen oder rote Linsen (kürzere Garzeit)"},{"menge":700,"einheit":"ml","name":"Wasser","hinweis":"zum Kochen der Linsen"},{"menge":0.5,"einheit":"TL","name":"Kurkumapulver"},{"menge":1,"einheit":"TL","name":"Öl oder Ghee","hinweis":"für vegane Variante Öl; verhindert Überkochen"}]},{"gruppe":"Für das Gemüse und die Säure","liste":[{"menge":1,"einheit":"Stück","name":"Zwiebel (mittelgroß), grob gewürfelt oder 8 Schalotten halbiert","hinweis":"kleine Schalotten (Sambar-Zwiebeln) sind das Original"},{"menge":2,"einheit":"Stück","name":"Tomaten, gewürfelt"},{"menge":150,"einheit":"g","name":"Möhren, in Stücken"},{"menge":150,"einheit":"g","name":"Drumsticks (Meerrettichbaum-Schoten) oder Kürbis","hinweis":"Drumsticks gibt es TK im Asialaden; Kürbis oder Zucchini sind geeigneter Ersatz"},{"menge":100,"einheit":"g","name":"Aubergine, in 3 cm Würfeln"},{"menge":30,"einheit":"g","name":"Tamarindenpaste oder ein Stück Tamarindenblock (walnussgroß)","hinweis":"im Asialaden"},{"menge":2,"einheit":"EL","name":"Sambar-Pulver","hinweis":"fertige Mischung aus dem Asialaden oder Eigenmischung (siehe Variante)"},{"menge":1,"einheit":"TL","name":"Salz"},{"menge":1,"einheit":"TL","name":"Jaggery oder brauner Zucker"}]},{"gruppe":"Für den Tadka (Gewürzöl)","liste":[{"menge":2,"einheit":"EL","name":"Öl (idealerweise Sesamöl oder Kokosöl)"},{"menge":1,"einheit":"TL","name":"schwarze Senfsamen"},{"menge":0.5,"einheit":"TL","name":"Bockshornkleesamen (Methi)"},{"menge":2,"einheit":"Stück","name":"getrocknete rote Chilis"},{"menge":12,"einheit":"Blatt","name":"frische Curryblätter"},{"menge":0.25,"einheit":"TL","name":"Asafoetida (Asant, Hing)","hinweis":"gibt die zwiebelartige Tiefe; im Asialaden, kann weggelassen werden"},{"menge":1,"einheit":"Bund","name":"frischer Koriander, gehackt"}]}],"ausruestung":["Schnellkochtopf oder großer Topf","Topf für das Gemüse","kleine Pfanne oder Tadka-Pfännchen","Stabmixer oder Schneebesen zum Zerdrücken der Linsen"],"schritte":[{"titel":"Linsen waschen und einweichen","aktion":"vorbereiten","text":"Gib den Toor Dal in eine Schüssel und wasche ihn unter fließendem Wasser mehrmals, bis das Wasser nicht mehr milchig-trüb ist. Das entfernt Staub und überschüssige Stärke. Lass die Linsen anschließend mindestens 30 Minuten in reichlich Wasser einweichen; das verkürzt die Garzeit und macht sie cremiger. Währenddessen weichst du die Tamarinde in 150 ml heißem Wasser ein, falls du Block-Tamarinde verwendest, und drückst sie nach 15 Minuten mit den Fingern auseinander, bis sich Fruchtfleisch von Kernen und Fasern löst. Seihe die dunkle Flüssigkeit durch ein Sieb und wirf die Fasern weg.","dauer":30,"tipp":"Nimm für den Tamarinden-Auszug lieber zu wenig als zu viel Wasser – lässt sich verdünnen, aber nicht konzentrieren."},{"titel":"Gemüse schneiden","aktion":"schneiden","text":"Schäle die Möhren und schneide sie in 2 cm dicke Scheiben, Aubergine in 3 cm große Würfel, Drumsticks in 6 cm lange Stücke und die Tomaten in grobe Würfel. Halbiere die kleinen Schalotten, wenn du sie hast, oder würfele die Zwiebel in 2 cm große Stücke. Das Gemüse darf bei Sambar kräftig groß bleiben, denn es soll im Eintopf noch Biss haben und seine Form halten. Schneide die Gemüse nach Garzeit sortiert: festes zuerst, weiches später, und halte sie in getrennten Schüsseln bereit.","dauer":0,"tipp":"Auberginen bräunen schnell – erst kurz vor dem Kochen schneiden oder in Salzwasser legen."},{"titel":"Dal weich kochen","aktion":"kochen","text":"Gib die abgetropften Linsen mit 700 ml Wasser, Kurkuma und 1 Teelöffel Öl in den Schnellkochtopf, schließe den Deckel und koche sie nach dem Druckaufbau 3 Pfeiflaute (etwa 12–15 Minuten) lang bei mittlerer Hitze. Im normalen Topf brauchst du 40–50 Minuten bei halb geschlossenem Deckel und musst den Schaum abschöpfen. Das Öl verhindert, dass der Schaum überkocht. Die Linsen sind fertig, wenn sie sich mit einem Löffelrücken mühelos zerdrücken lassen. Rühre sie mit einem Schneebesen cremig, bis keine Stücke mehr zu erkennen sind.","dauer":20,"tipp":"Das Dal soll eine sämige, gleichmäßige Suppe ergeben, in der Löffel sich noch bewegen lässt."},{"titel":"Gemüse garen","aktion":"koecheln","text":"Koche in einem separaten, großen Topf 600 ml Wasser mit Möhren, Drumsticks, Zwiebel und etwas Salz bei mittlerer Hitze an. Nach 5 Minuten kommen die Auberginen und die Tomaten dazu. Lass alles weitere 8–10 Minuten sanft köcheln, bis die Möhren bissfest sind. Das Gemüse sollte noch nicht zerfallen: Es gart in der späteren Brühe noch nach. Probiere eine Möhre – sie darf einen leichten Biss haben, aber nicht mehr nach rohem Gemüse schmecken.","dauer":15,"tipp":"Kürbis und Zucchini erst zum Schluss für die letzten 5 Minuten zugeben, sonst werden sie matschig."},{"titel":"Säure und Gewürze einrühren","aktion":"mischen","text":"Gieße den Tamarinden-Auszug zum Gemüse, gib Sambar-Pulver, Salz und Jaggery dazu und lass alles 5–7 Minuten köcheln. In dieser Zeit verliert die Tamarinde ihren rohen, scharfen Geruch und wird fruchtig-sauer, während das Gewürzpulver sein Aroma an die Brühe abgibt. Es sollte nun duften wie ein südindischer Markt: warm, erdig, leicht rauchig und fruchtig. Der Zucker rundet die Säure ab, er soll nicht süß, sondern ausgleichend wirken.","dauer":7,"tipp":"Das Aroma von Sambar-Pulver verflüchtigt sich, wenn es zu lange kocht – spätestens nach 10 Minuten zum Dal gehen."},{"titel":"Dal und Gemüse vereinen","aktion":"mischen","text":"Gieße das cremige Dal in den Gemüsetopf und rühre es gründlich unter. Gib so viel heißes Wasser dazu, dass die Konsistenz einer dicken Suppe entsteht, die gerade noch langsam vom Löffel fließt. Lass alles bei niedriger Hitze 5–8 Minuten leise blubbern und rühre öfter, damit nichts am Boden ansetzt. Probiere nun mit Salz, Säure und Schärfe: Fehlt Tiefe, hilft eine Prise Sambar-Pulver; ist es zu sauer, ein Löffel Jaggery; zu dünn, kocht man 3 Minuten ohne Deckel ein.","dauer":8,"tipp":""},{"titel":"Tadka zubereiten","aktion":"braten","text":"Erhitze das Öl in einer kleinen Pfanne bei mittlerer Hitze, bis ein Senfkorn beim Hineinwerfen sofort zu knistern beginnt. Gib alle Senfsamen hinein und warte, bis sie prasseln und aufspringen – das dauert nur wenige Sekunden. Gib sofort Bockshornklee, Chilis, Asafoetida und die Curryblätter hinzu; es spritzt und zischt, halte den Deckel bereit. Rühre 10–15 Sekunden, bis die Curryblätter knusprig werden und die Chilis dunkler. Alles muss duftend, aber nicht schwarz sein: Verbrannte Gewürze schmecken bitter.","dauer":2,"tipp":"Stelle alle Gewürze für den Tadka griffbereit auf einen Teller – du hast nur Sekunden."},{"titel":"Tadka unterrühren und ruhen lassen","aktion":"garnieren","text":"Gieße das heiße Gewürzöl samt Gewürzen direkt in den Sambar – er zischt, und ein intensiver, nussig-würziger Duft steigt auf. Rühre kurz um, nimm den Topf vom Herd und decke ihn zu. Lass den Sambar 10–15 Minuten ziehen, bevor du ihn servierst, denn in dieser Zeit verbinden sich Öl, Gewürze und Brühe zu einem runden Ganzen. Streue den gehackten Koriander erst bei Tisch darüber, damit er frisch grün bleibt.","dauer":10,"tipp":"Sambar schmeckt am nächsten Tag noch besser – gerne am Vortag kochen und morgens aufwärmen."},{"titel":"Anrichten","aktion":"anrichten","text":"Serviere den Sambar heiß in tiefen Tellern oder Schalen mit gedämpftem Basmati- oder Parboiled-Reis. In Südindien gießt man ihn über den Reis, vermischt beides mit der rechten Hand und isst mit den Fingern; mit Löffel schmeckt er aber genauso gut. Als Frühstück oder Snack passt er in einer kleinen Schale zu Idli, Medu Vada oder Dosa, die du hineintunken kannst. Reiche dazu Kokos-Chutney, ein Papadam und etwas Zitronenpickle, die Säure und Schärfe nochmal anheben.","dauer":0,"tipp":"Ein Löffel Ghee obendrauf (nicht vegan) macht den Sambar besonders reich."}],"profitipps":["Der Tadka (Tempering) ist die Seele: Öl heiß genug, Senfsamen müssen springen, sonst bleiben sie bitter und roh im Geschmack.","Toor Dal richtig weich kochen und glatt rühren – ein cremiger, gebundener Sambar ist das Ziel, kein klares Linsenwasser.","Tamarinde erst mit Gemüse kochen, nicht mit den Linsen: Säure verhindert, dass Hülsenfrüchte weich werden.","Kein Fertigpulver? Röste 2 EL Koriandersamen, 1 EL Kichererbsen-Dal, 1 TL Senfsamen, 0,5 TL Bockshornklee, 4 getrocknete Chilis trocken an, mahle sie und rühre 0,5 TL Kurkuma unter.","Gemüse möglichst vielfältig: Drumsticks, Okra, Kürbis, Aubergine und Rettich sind klassisch."],"varianten":["Arachuvitta Sambar (Tamil Nadu): mit frisch gemahlener Paste aus gerösteter Kokosnuss und Gewürzen statt Fertigpulver.","Udupi-Sambar (Karnataka): milder, süßlicher, mit Kokos und Jaggery.","Tiffin-Sambar: dünner und mit viel Zwiebel, extra zum Dippen von Idli und Vada.","Kerala-Sambar: mit Kürbis und Kokos, oft mit Ingwer."],"beilagen":["Basmatireis","Idli","Dosa","Medu Vada","Papadam","Kokos-Chutney"],"getraenk":"Südindischer Filterkaffee, Buttermilch (Masala Chaas) oder ein leichtes Lager-Bier","koeche":[],"quellen":[{"titel":"Sambar (dish) – Wikipedia","url":"https://en.wikipedia.org/wiki/Sambar_(dish)"}],"bild":"eintopf","farben":["#c4631a","#e8a33d","#7a2e0e"],"schlagworte":["Südindien","vegan","Linsen","Frühstück","Tamarinde"],"vegetarisch_moeglich":true},{"id":"indien-goan-prawn-curry","name":"Goan Prawn Curry – Garnelencurry mit Kokos und Tamarinde","originalname":"Goan Sungta Hooman","kueche":"indien","region":"Goa","beliebtheit":80,"hauptkategorie":"fisch","fischsorte":"meeresfruechte","gang":"hauptgericht","kurz":"Saftige Garnelen in einer leuchtend orangeroten Kokos-Sauce mit getrockneten Chilis, Tamarinde und Koriander. Süß, sauer und würzig – das Alltagsgericht Goas.","hintergrund":"Der Goan Prawn Curry (Konkani: Sungta Hooman) ist das Alltagsessen der Küste Goas und gehört dort zu jedem Mittagstisch mit Reis. Frische Kokosnuss, die in Goa überall wächst, wird mit getrockneten Kashmiri-Chilis, Koriandersamen, Kreuzkümmel und Kurkuma zu einer Paste gemahlen, die dem Curry seine Farbe und Dicke gibt. Säure kommt von Tamarinde oder Kokum, einer getrockneten Frucht, die dem Curry eine rauchig-fruchtige Säure verleiht. Der portugiesische Einfluss zeigt sich in der Verwendung von Essig, der in manchen Familien zugegeben wird. Anders als in anderen indischen Currys fehlt Milchprodukt, das Gericht ist deshalb von frischer Leichtigkeit.","portionen":4,"zeit":{"vorbereitung":25,"garen":25,"ruhen":15},"schwierigkeit":2,"zutaten":[{"gruppe":"Garnelen","liste":[{"menge":600,"einheit":"g","name":"große Garnelen, geschält, Darm entfernt","hinweis":"Schwänze dranlassen; TK aus ASC-Zucht"},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"EL","name":"Zitronensaft","hinweis":""}]},{"gruppe":"Kokos-Gewürzpaste","liste":[{"menge":100,"einheit":"g","name":"frische oder TK-Kokosraspel","hinweis":"ungesüßt; Ersatz 150 ml Kokosmilch"},{"menge":6,"einheit":"Stück","name":"getrocknete rote Chilis (Kashmiri)","hinweis":"Kashmiri ist farbstark und mild; sonst Chilis entkernen"},{"menge":1,"einheit":"EL","name":"Koriandersamen","hinweis":""},{"menge":1,"einheit":"TL","name":"Kreuzkümmel","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":5,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":1,"einheit":"Stück","name":"Ingwer (ca. 2 cm)","hinweis":""}]},{"gruppe":"Curry","liste":[{"menge":3,"einheit":"EL","name":"Kokosöl oder neutrales Öl","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zwiebel, fein gehackt","hinweis":""},{"menge":2,"einheit":"Stück","name":"Tomaten, gewürfelt","hinweis":""},{"menge":4,"einheit":"Stück","name":"Kokum (getrocknet)","hinweis":"Ersatz: 2 EL Tamarindenpaste"},{"menge":300,"einheit":"ml","name":"Wasser","hinweis":""},{"menge":2,"einheit":"Stück","name":"grüne Chilis, längs eingeschnitten","hinweis":""},{"menge":1,"einheit":"Handvoll","name":"Koriander","hinweis":""}]}],"ausruestung":["Standmixer oder Mörser","weiter Topf oder tiefe Pfanne","kleine Pfanne zum Rösten"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schäle die Garnelen, lasse den Schwanz dran und entferne den Darm mit einem scharfen Messer entlang des Rückens. Spüle sie kurz ab und tupfe sie trocken. Hacke die Zwiebel fein, würfle die Tomaten in 1 cm Würfel und schneide Chilis und Koriander zu. Weiche die getrockneten Chilis in warmem Wasser 10 Minuten ein, damit sie weich werden und sich gut mahlen lassen.","dauer":10,"tipp":""},{"titel":"Garnelen marinieren","aktion":"marinieren","text":"Vermische die Garnelen mit Kurkuma, Salz und Zitronensaft und lasse sie 15 Minuten im Kühlschrank ziehen. Das Salz würzt und festigt das Fleisch leicht, der Zitronensaft nimmt den „Fischgeruch“. Kurkuma färbt die Garnelen gelb und gibt eine erdige Basis. Länger als 30 Minuten solltest du nicht marinieren, sonst wird das Fleisch durch die Säure mehlig.","dauer":15,"tipp":""},{"titel":"Gewürze rösten","aktion":"braten","text":"Röste Koriandersamen und Kreuzkümmel in einer trockenen Pfanne bei mittlerer Hitze 1 bis 2 Minuten, bis sie duften und leicht dunkler werden; schwenke sie ständig, damit nichts verbrennt. Sobald es nussig riecht, kommen sie auf einen Teller. Das Rösten entfaltet die ätherischen Öle und nimmt den Gewürzen die Rohheit.","dauer":2,"tipp":""},{"titel":"Paste mahlen","aktion":"puerieren","text":"Gib Kokos, abgetropfte Chilis, geröstete Gewürze, Kurkuma, Knoblauch, Ingwer und 100 ml Wasser in den Mixer und pürieren, bis eine feine, leuchtend orangerote Paste entsteht. Sie soll möglichst glatt sein; grobe Kokosfäden darf man erst am Rand sehen. Kratze mehrfach den Rand ab. Die Paste ist die Seele des Currys: Farbe, Schärfe und Dickflüssigkeit kommen von ihr.","dauer":3,"tipp":""},{"titel":"Zwiebel und Tomaten anschwitzen","aktion":"anbraten","text":"Erhitze das Öl im Topf bei mittlerer Hitze, gib die Zwiebel hinein und dünste sie 6 bis 8 Minuten, bis sie goldgelb und weich ist. Gib die Tomaten dazu und schmore sie weitere 4 bis 5 Minuten, bis sie zerfallen und das Öl sich rötlich absetzt. So entsteht das süßliche Fundament, das die Schärfe der Paste abfedert.","dauer":12,"tipp":""},{"titel":"Paste anbraten","aktion":"braten","text":"Gib die Paste in den Topf und brate sie unter ständigem Rühren 5 bis 6 Minuten bei mittlerer Hitze, bis das Öl sich am Rand absetzt und der Rohgeruch von Kokos und Knoblauch verschwunden ist. Wird sie zu trocken, gib einen Schuss Wasser dazu. Diese Phase ist entscheidend: Ungebratene Paste schmeckt grasig und mehlig.","dauer":6,"tipp":"Erst wenn das Öl an den Rändern sichtbar wird, ist die Paste durchgebraten."},{"titel":"Curry aufkochen","aktion":"koecheln","text":"Gieße 300 ml Wasser dazu, rühre alles glatt, gib Kokum (oder Tamarindenpaste) und die eingeschnittenen grünen Chilis hinein und lasse das Curry 8 bis 10 Minuten leise köcheln. Die Sauce soll leicht sämig sein und einen Löffel überziehen. Probiere und würze mit Salz nach; die Säure soll deutlich spürbar sein, aber nicht scharf.","dauer":10,"tipp":""},{"titel":"Garnelen garen","aktion":"koecheln","text":"Gib die marinierten Garnelen in die köchelnde Sauce und lasse sie 3 bis 4 Minuten ziehen, bis sie sich krümmen und weißlich-rosa sind; kochen sie länger, werden sie zäh. Wende sie einmal. Die Garnelen sollen nicht im sprudelnden Curry garen, sondern sanft ziehen. Nimm den Topf vom Herd, sobald sie ein C bilden.","dauer":4,"tipp":"Garnelen ziehen in der Resthitze noch nach, deshalb lieber eine Minute zu früh abschalten."},{"titel":"Abschmecken und servieren","aktion":"abschmecken","text":"Schmecke mit Salz und eventuell einer Prise Zucker ab, streue frischen Koriander darüber und lass das Curry 5 Minuten ruhen, damit sich die Aromen verbinden. Serviere es mit gedämpftem Reis oder Poi, goanischem Brot. Das Curry schmeckt am nächsten Tag oft noch besser, nur die Garnelen sollten dann schonend erwärmt werden.","dauer":5,"tipp":""}],"profitipps":["Die Paste gründlich anbraten, bis sich das Öl absetzt – das trennt gutes Curry von rohem.","Kokum bringt eine rauchig-saure Tiefe, die Tamarinde nur annähernd erreicht.","Garnelen erst ganz am Ende zugeben; in der Sauce brauchen sie nur 3 bis 4 Minuten.","Kashmiri-Chilis liefern Farbe ohne zu viel Schärfe.","Frische Kokosnuss macht das Curry feiner, TK-Raspeln sind ein guter Ersatz."],"varianten":["Mit Fischsteaks (Kingfish, Seelachs) statt Garnelen","Mit grüner Mango statt Tamarinde im Frühling","Mit Kokosmilch statt Kokosraspel für eine cremigere Sauce","Balchão: stark fermentierte, essigscharfe Variante, die eingemacht werden kann"],"beilagen":["gedämpfter Basmatireis","Pao (Goa-Brötchen)","gebratenes Gemüse"],"getraenk":"Kaltes Kingfisher-Bier oder ein trockener Weißwein","koeche":[{"name":"Madhur Jaffrey","bezug":"Die britisch-indische Kochbuchautorin hat ein Garnelen-Curry-Rezept (Prawn Curry), das auf food.com als „Madhur Jaffrey's Prawn (Shrimp) Curry“ gelistet ist und die Technik des Currys mit Gewürzen und Kokos darstellt.","quelle":"https://www.food.com/amp/recipe/madhur-jaffreys-prawn-shrimp-curry-309194"}],"quellen":[{"titel":"Madhur Jaffrey's Prawn (Shrimp) Curry – Food.com","url":"https://www.food.com/amp/recipe/madhur-jaffreys-prawn-shrimp-curry-309194"},{"titel":"Sea Salt with Food – Goan Prawn Curry","url":"https://www.seasaltwithfood.com/2011/06/goan-prawn-curry.html"},{"titel":"My Food Story – Goan Prawn Curry with Coconut","url":"https://myfoodstory.com/goan-prawn-curry-recipe/comment-page-3/"},{"titel":"Great British Chefs – Goan prawn curry","url":"https://www.greatbritishchefs.com/recipes/goan-prawn-curry-recipe/shopping-list"}],"bild":"curry","farben":["#d9582b","#f3a24a","#f5e3c0"],"schlagworte":["Goa","Garnelen","Kokos","Curry"],"vegetarisch_moeglich":false},{"id":"indien-amritsari-fish","name":"Amritsari Fish – Knusprig frittierter Fisch im Kichererbsenmehl-Teig","originalname":"ਅੰਮ੍ਰਿਤਸਰੀ ਮੱਛੀ","kueche":"indien","region":"Punjab / Amritsar","beliebtheit":80,"hauptkategorie":"fisch","fischsorte":"fisch","gang":"vorspeise","kurz":"Fischwürfel in einem würzigen Teig aus Kichererbsenmehl, Joghurt, Ajwain und Chili, goldbraun frittiert und mit Chaat Masala und Zitrone serviert. Der Klassiker der Punjabi-Straßenküche.","hintergrund":"Amritsari Fish stammt aus Amritsar im Punjab, einer Stadt, die für ihre Straßenküche berühmt ist. Obwohl der Punjab weit vom Meer liegt, ist der Fisch aus den Flüssen (Singhara-Wels, Rohu) hier tief verwurzelt. Typisch ist die Marinade aus Ingwer-Knoblauch-Paste, Ajwain (Carom-Samen), Chilipulver und Zitronensaft, dazu ein Teig aus Kichererbsenmehl, der beim Frittieren knusprig und leicht würzig wird. Ein Spritzer Essig oder Zitrone in der Vormarinade festigt das Fleisch und nimmt den Fischgeruch. Das Gericht wird heiß zu Minzchutney, Zwiebelringen und Zitronenspalten serviert und passt als Vorspeise zu Bier.","portionen":4,"zeit":{"vorbereitung":25,"garen":15,"ruhen":40},"schwierigkeit":2,"zutaten":[{"gruppe":"Fisch","liste":[{"menge":600,"einheit":"g","name":"festes, grätenfreies Fischfilet (Seehecht, Kabeljau, Wels, Pangasius)","hinweis":"In Indien: Singhara oder Surmai; in 3 cm Würfel geschnitten"},{"menge":80,"einheit":"ml","name":"Weißweinessig oder Malzessig","hinweis":"für die Vormarinade"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Teig","liste":[{"menge":120,"einheit":"g","name":"Kichererbsenmehl (Besan)","hinweis":"Asia- oder Bioladen"},{"menge":125,"einheit":"g","name":"Naturjoghurt","hinweis":""},{"menge":1,"einheit":"Stück","name":"Ei","hinweis":""},{"menge":1,"einheit":"TL","name":"Ajwain (Königskümmel)","hinweis":"Ersatz: Thymian oder etwas Kümmel"},{"menge":1,"einheit":"EL","name":"Zitronensaft","hinweis":""},{"menge":1,"einheit":"EL","name":"Chilipulver (Kashmiri)","hinweis":"für Farbe, mild"},{"menge":2,"einheit":"EL","name":"Ingwer-Knoblauch-Paste","hinweis":""},{"menge":1,"einheit":"TL","name":"Garam Masala","hinweis":""}]},{"gruppe":"Frittieren und Servieren","liste":[{"menge":1,"einheit":"l","name":"neutrales Öl zum Frittieren","hinweis":""},{"menge":1,"einheit":"TL","name":"Chaat Masala","hinweis":""},{"menge":2,"einheit":"Stück","name":"Zitronen, in Spalten","hinweis":""},{"menge":1,"einheit":"Stück","name":"rote Zwiebel, in Ringen","hinweis":""}]}],"ausruestung":["tiefe Pfanne oder Wok","Frittierthermometer","Schaumlöffel","Schüssel"],"schritte":[{"titel":"Fisch vorbereiten","aktion":"vorbereiten","text":"Tupfe das Filet trocken und prüfe mit den Fingern auf Gräten; ziehe sie mit der Pinzette in Faserrichtung heraus. Schneide das Fleisch in 3 cm große Würfel, damit sie gleichmäßig garen. Zu kleine Stücke werden trocken, zu große bleiben innen glasig. Lege sie in eine Schüssel und stelle alle Zutaten für Marinade und Teig bereit.","dauer":0,"tipp":""},{"titel":"Vormarinade mit Essig","aktion":"marinieren","text":"Übergieße die Fischwürfel mit dem Essig und dem Salz, wende sie vorsichtig und lasse sie 20 Minuten bei Raumtemperatur stehen. Die Säure festigt das Fleisch und mindert den Fischgeruch. Hebe sie danach heraus und tupfe sie sehr gründlich trocken: Der Teig haftet nur auf trockener Oberfläche und das Öl spritzt sonst stark.","dauer":20,"tipp":"Nicht länger als 30 Minuten, sonst wird das Fleisch mehlig."},{"titel":"Teig anrühren","aktion":"mischen","text":"Verrühre Kichererbsenmehl, Joghurt, Ei, zerriebenes Ajwain (zwischen den Handflächen zerreiben, setzt Aroma frei), Zitronensaft, Chilipulver, Garam Masala und Ingwer-Knoblauch-Paste zu einem dicken, glatten Teig. Er soll wie dicke Pfannkuchenmasse vom Löffel fließen und am Fisch haften. Ist er zu fest, gib einen Teelöffel Wasser dazu, ist er zu dünn, einen Esslöffel Mehl.","dauer":0,"tipp":""},{"titel":"Fisch in Teig wenden und ruhen lassen","aktion":"panieren","text":"Gib die trockenen Fischwürfel in den Teig und wende sie vorsichtig, bis jedes Stück vollständig überzogen ist. Lass die Schüssel abgedeckt 20 Minuten im Kühlschrank stehen. Die Ruhezeit lässt Gewürze und Joghurt in den Fisch ziehen und den Teig fester haften, wodurch er beim Frittieren knusprig bleibt und nicht abplatzt.","dauer":20,"tipp":""},{"titel":"Öl erhitzen","aktion":"vorbereiten","text":"Erhitze das Öl in einer tiefen Pfanne oder einem Wok auf 175 bis 180 °C. Prüfe die Temperatur mit dem Thermometer oder tauche den Stiel eines Holzlöffels hinein: Steigen sofort feine Bläschen auf, ist das Öl bereit. Zu kühl ergibt ein fettiges, blasses Ergebnis, zu heiß verbrennt der Teig, bevor der Fisch gar ist. Bereite einen Teller mit Küchenpapier vor.","dauer":5,"tipp":""},{"titel":"Frittieren","aktion":"frittieren","text":"Lasse die Fischwürfel einzeln und portionsweise (etwa 6 Stück auf einmal) ins heiße Öl gleiten, damit die Temperatur nicht abfällt. Frittiere sie 3 bis 4 Minuten, bis sie goldbraun und knusprig sind; der Teig wirft kleine Bläschen und das Zischen lässt nach, wenn das Wasser verdampft ist. Wende sie nach der Hälfte der Zeit. Hebe sie mit dem Schaumlöffel heraus und lasse sie auf Küchenpapier abtropfen.","dauer":12,"tipp":"Wer extra Knusprigkeit will, frittiert ein zweites Mal 30 Sekunden bei 190 °C."},{"titel":"Würzen","aktion":"abschmecken","text":"Bestreue den heißen Fisch sofort mit Chaat Masala; das Gewürz haftet nur auf dem frischen Fett und entfaltet seinen säuerlich-salzigen Duft. Schmecke ein Stück ab: Es soll außen knusprig, innen saftig und weiß sein, mit Ajwain-Aroma und leichter Schärfe. Nachsalzen kannst du bei Bedarf. Ein bis zwei Prisen extra Chaat Masala am Tisch erlauben jedem, die Säure nach eigenem Geschmack zu dosieren.","dauer":0,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Richte den Fisch auf einer Platte an mit Zwiebelringen, Zitronenspalten und einem Schälchen Minz-Koriander-Chutney. Serviere ihn sofort, denn der Teig verliert beim Stehen seine Knusprigkeit. Der Zitronensaft über dem heißen Fisch frischt das Gericht auf und mildert die Schärfe. Wer eine größere Runde bewirtet, hält die ersten Portionen im Ofen bei 100 °C auf einem Gitter warm, damit sie nicht weich werden.","dauer":0,"tipp":""}],"profitipps":["Fisch sehr gut trocknen, bevor er in den Teig kommt – sonst blättert der Teig ab.","Teig nicht zu dünn machen: Er muss wie dicker Pfannkuchenteig haften.","Ajwain zwischen den Händen zerreiben, damit es mehr Aroma abgibt.","Öltemperatur halten; nie zu viele Stücke gleichzeitig frittieren.","Chaat Masala sofort nach dem Frittieren, solange das Fett noch warm ist."],"varianten":["Amritsari Machhi mit Garnelen","Tawa-Version: in wenig Öl in der Pfanne ausgebacken (weniger Fett)","Ofen-Version: 220 °C Ober-/Unterhitze, 200 °C Umluft, 15 Minuten, mit Öl bepinselt","Mit Reismehl-Anteil im Teig für mehr Knusprigkeit"],"beilagen":["Minz-Koriander-Chutney","Zwiebelringe","Zitronenspalten","Naan"],"getraenk":"Kaltes Lagerbier, Lassi oder ein trockener Riesling","koeche":[{"name":"Sanjeev Kapoor","bezug":"Der bekannte indische Fernsehkoch hat ein Rezept „Amritsari Fish“ in seinem Online-Archiv „Khazana of Indian Recipes“ mit Essig-Vormarinade und Kichererbsenmehl-Teig.","quelle":"https://www.sanjeevkapoor.com/Recipe/Amritsari-Fish-Khazana-of-Indian-Recipes.html"}],"quellen":[{"titel":"Sanjeev Kapoor – Amritsari Fish","url":"https://www.sanjeevkapoor.com/Recipe/Amritsari-Fish-Khazana-of-Indian-Recipes.html"},{"titel":"Hari Ghotra – Fish Amritsari","url":"https://www.harighotra.co.uk/fish-amristasri-recipe/amp"},{"titel":"Indian Healthy Recipes – Amritsari Fish Fry","url":"https://www.indianhealthyrecipes.com/2014/01/amritsari-tawa-fish-fry-pan-fried.html"}],"bild":"fisch","farben":["#d9942b","#f1d28a","#9a3b1f"],"schlagworte":["Punjab","Frittiert","Kichererbsenmehl","Vorspeise"],"vegetarisch_moeglich":false},{"id":"indien-dal-tadka","name":"Dal Tadka","originalname":"","kueche":"indien","region":"Nordindien (landesweit)","beliebtheit":80,"hauptkategorie":"vegan","fleischsorte":"","gang":"hauptgericht","kurz":"Weich gekochte gelbe Linsen, gekrönt von einem zischenden Tadka aus Ghee, Kreuzkümmel, Knoblauch und Chili – das Alltagsgericht, das man in Indien täglich isst.","hintergrund":"Dal bezeichnet geschälte Hülsenfrüchte und das daraus gekochte Gericht. Dal Tadka ist die alltägliche Form: Toor Dal (Tauben-Erbse), manchmal gemischt mit Moong Dal, wird mit Kurkuma weich gekocht und zum Schluss mit einem Tadka übergossen. Der Tadka (auch Tarka, Chaunk, Baghar) ist in heißem Fett gerösteter Gewürz-Zwiebel-Knoblauch-Mix, der kurz vor dem Servieren in das Dal gegeben wird. Seine Aromen liegen deshalb frisch obenauf. In Restaurants gibt es oft einen zweiten Tadka aus Ghee, Knoblauch und Chili.","portionen":4,"zeit":{"vorbereitung":15,"garen":50,"ruhen":30},"schwierigkeit":1,"zutaten":[{"gruppe":"Dal","liste":[{"menge":150,"einheit":"g","name":"Toor Dal (geschälte Tauben-Erbsen-Linsen)","hinweis":"im Asialaden; gelbe geschälte Linsen als Ersatz"},{"menge":50,"einheit":"g","name":"Moong Dal (geschälte gelbe Mungbohnen)","hinweis":"kocht schneller und macht das Dal cremiger"},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"Stück","name":"reife Tomate","hinweis":"gewürfelt"},{"menge":1,"einheit":"Stück","name":"Stück Ingwer, 2 cm","hinweis":"in feinen Streifen"}]},{"gruppe":"Erster Tadka (im Dal)","liste":[{"menge":1,"einheit":"EL","name":"Ghee","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zwiebel","hinweis":"fein gehackt"},{"menge":2,"einheit":"Stück","name":"grüne Chilischoten","hinweis":""},{"menge":0.5,"einheit":"TL","name":"gemahlener Koriander","hinweis":""}]},{"gruppe":"Zweiter Tadka (zum Servieren)","liste":[{"menge":2,"einheit":"EL","name":"Ghee","hinweis":""},{"menge":1,"einheit":"TL","name":"Kreuzkümmelsamen","hinweis":""},{"menge":1,"einheit":"Prise","name":"Asafoetida (Hing)","hinweis":""},{"menge":4,"einheit":"Zehe","name":"Knoblauch","hinweis":"in feinen Scheiben"},{"menge":2,"einheit":"Stück","name":"getrocknete rote Chilischoten","hinweis":""},{"menge":1,"einheit":"TL","name":"Kashmiri-Chilipulver","hinweis":"für die rote Farbe"},{"menge":1,"einheit":"TL","name":"Garam Masala","hinweis":"optional, frisch gemahlen"},{"menge":1,"einheit":"Handvoll","name":"frischer Koriander","hinweis":""}]}],"ausruestung":["Schwerer Topf oder Schnellkochtopf","Kleine Pfanne für den Tadka","Schneebesen oder Pürierstab","Deckel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wasche Toor Dal und Moong Dal in mehreren Wassern, bis das Wasser fast klar ist; dabei löst sich Staub und überschüssige Stärke, die sonst zu viel Schaum bildet. Weiche sie 20 bis 30 Minuten in warmem Wasser ein, das verkürzt die Garzeit. Schneide Zwiebel, Ingwer, Chili und Tomate. Schneide den Knoblauch in feine Scheiben, nicht pressen, damit er im Fett nicht verbrennt. Stelle alle Gewürze bereit: Der Tadka geht in Sekunden und du hast keine Zeit zum Suchen.","dauer":30,"tipp":"Alles für den Tadka griffbereit neben den Herd stellen – er braucht deine volle Aufmerksamkeit."},{"titel":"Dal weich kochen","aktion":"kochen","text":"Gib die abgegossenen Linsen mit 800 ml Wasser, Kurkuma und Ingwer in einen Topf und bringe sie zum Kochen. Schöpfe den weißen Schaum mit einem Löffel ab. Reduziere die Hitze, decke den Topf halb ab und koche 30 bis 40 Minuten (im Schnellkochtopf 12 bis 15 Minuten), bis die Linsen zerfallen und sich zwischen den Fingern zerdrücken lassen. Rühre gelegentlich um, damit nichts anbrennt. Das Dal soll sämig sein wie dicke Suppe. Zu dünn: Nimm den Deckel ab und lasse es einkochen.","dauer":40,"tipp":"Erst jetzt salzen; Salz am Anfang kann die Linsen länger hart halten."},{"titel":"Dal glattrühren","aktion":"puerieren","text":"Schlage das Dal mit einem Schneebesen oder dem Pürierstab kurz glatt, bis es cremig, aber nicht ganz püriert ist; ein wenig Struktur darf bleiben. Gib die gewürfelte Tomate dazu und koche noch 5 Minuten, bis sie zerfällt. Gib Salz hinzu und prüfe die Konsistenz: Fehlt Flüssigkeit, gib etwas heißes Wasser dazu. Das Dal sollte leicht vom Löffel fließen und eine schöne, gelbe Farbe haben.","dauer":8,"tipp":"Heißes Wasser zum Verdünnen verwenden; kaltes lässt das Dal körnig wirken."},{"titel":"Erster Tadka mit Zwiebeln","aktion":"braten","text":"Erhitze 1 Esslöffel Ghee in einer Pfanne bei mittlerer Hitze, brate die Zwiebel 6 bis 8 Minuten, bis sie goldbraun ist, und gib Chili und Koriander hinzu. Rühre 30 Sekunden und gib alles in den Dal-Topf. Dieser erste Tadka gibt dem Dal Körper und Süße. Rühre ihn unter und lasse das Dal weitere 5 Minuten leise köcheln. Der Duft sollte jetzt warm und süßlich-würzig sein.","dauer":10,"tipp":"Madhur Jaffrey brät Zwiebeln im Tadka bis zu rötlich-brauner Knusprigkeit, dadurch entsteht mehr Röstaroma."},{"titel":"Zweiten Tadka vorbereiten","aktion":"vorbereiten","text":"Stelle den Topf mit dem Dal auf kleinste Hitze und lege den Deckel bereit. Für den zweiten Tadka erhitzt du Ghee in einer kleinen Pfanne bei mittlerer Hitze, bis es flüssig ist und leicht schimmert. Teste die Hitze: Wirf einen Kreuzkümmelsamen hinein; wenn er sofort zischt, aber nicht verbrennt, ist das Fett richtig. Zu kaltes Ghee bringt die Gewürze nicht zum Blühen, zu heißes verbrennt sie in Sekunden.","dauer":2,"tipp":"Das Fett darf nicht rauchen; riecht es nach verbranntem Öl, ist es zu heiß."},{"titel":"Tadka rösten","aktion":"braten","text":"Gib Kreuzkümmel in das heiße Ghee und warte 10 bis 15 Sekunden, bis er aufschäumt und nussig duftet. Gib sofort die Hing-Prise und die Knoblauchscheiben dazu und rühre ständig 20 bis 30 Sekunden, bis der Knoblauch hellgolden wird. Füge die getrockneten Chilis zu und warte 5 Sekunden, bis sie leicht aufquellen. Nimm die Pfanne vom Herd und streue das Kashmiri-Chilipulver in das heiße Fett; es verbrennt sonst. Die Reihenfolge ist wichtig: harte Samen zuerst, schnell verbrennende Zutaten zuletzt.","dauer":2,"tipp":"Wird der Knoblauch dunkelbraun, ist er bitter; mach den Tadka lieber neu."},{"titel":"Tadka ins Dal gießen","aktion":"garnieren","text":"Gieße den heißen Tadka sofort über das heiße Dal. Es zischt laut und der Duft steigt auf. Setze den Deckel augenblicklich auf und lasse es 1 bis 2 Minuten ziehen, damit die Aromen in das Dal einziehen und nicht verfliegen. Streue Garam Masala darüber und rühre dann vorsichtig um. Probiere und stelle mit Salz, Zitronensaft und etwas Zucker die Balance ein. Das Dal soll herzhaft, würzig, leicht säuerlich und buttrig sein.","dauer":3,"tipp":"Der Deckel hält das flüchtige Aroma im Topf – das ist der ganze Zweck."},{"titel":"Anrichten","aktion":"anrichten","text":"Fülle das Dal in eine vorgewärmte Schüssel und streue frisch gehackten Koriander darüber. Serviere es mit Basmatireis, Jeera-Reis oder Roti. Gib Zitronenspalten und einen kleinen Salat aus roten Zwiebeln, Gurke und Tomate dazu. Am nächsten Tag zieht das Dal an und wird dicker; erwärme es mit etwas Wasser und gib einen frischen Tadka dazu.","dauer":0,"tipp":"Ein Klecks Ghee obendrauf macht das Gericht reichhaltiger."}],"profitipps":["Tadka immer frisch zubereiten; aufbewahrter Tadka verliert Aroma.","Reihenfolge: Samen zuerst, Knoblauch dann, Chilipulver zuletzt und vom Herd.","Nach dem Eingießen sofort abdecken, damit die Aromen im Dal bleiben.","Linsen erst gegen Ende der Garzeit salzen.","Schaum abschöpfen, damit das Dal klar schmeckt."],"varianten":["Dhaba-Dal mit Tomaten und viel Knoblauch.","Mit Moong und Masoor wie bei Madhur Jaffrey, mit Röstzwiebeln im Tadka.","Südindischer Tadka mit Senfsamen, Curryblättern und Kokosöl.","Meera Sodhas Moong Dal mit Kreuzkümmel, Schalotten, Knoblauch und Garam Masala."],"beilagen":["Basmatireis oder Jeera-Reis","Roti oder Paratha","Aloo Gobi","Raita"],"getraenk":"Lassi, Chai oder Buttermilch.","koeche":[{"name":"Madhur Jaffrey","bezug":"In ihrer MasterClass-Lektion kocht sie Moong- und Masoor-Dal, schöpft den Schaum ab und gießt zum Schluss einen Tadka aus Asafoetida, Kreuzkümmel, roten Chilis und bräunlich gebratenen Zwiebeln darüber; sie deckt sofort ab, damit die Aromen einziehen.","quelle":"https://www.masterclass.com/articles/dal-recipe-by-madhur-jaffrey"},{"name":"Meera Sodha","bezug":"Ihr Moong-Dal-Rezept aus Fresh India erhält den Geschmack aus einer Pfanne mit Kreuzkümmel, Schalotten, grünen Chilis, Knoblauch, Kurkuma und Garam Masala, die in das gekochte Dal gegossen wird.","quelle":"https://thehappyfoodie.co.uk/recipes/meera-sodhas-moong-dal/"}],"quellen":[{"titel":"Dal – Wikipedia","url":"https://en.wikipedia.org/wiki/Dal"},{"titel":"Dal recipe by Madhur Jaffrey – MasterClass","url":"https://www.masterclass.com/articles/dal-recipe-by-madhur-jaffrey"},{"titel":"Meera Sodha's Moong Dal – The Happy Foodie","url":"https://thehappyfoodie.co.uk/recipes/meera-sodhas-moong-dal/"},{"titel":"Tadka: the simple Indian cooking technique – SBS Food","url":"https://www.sbs.com.au/food/article/tadka-the-simple-indian-cooking-technique-you-should-know/8nucpkdcu"},{"titel":"The Crackling Spices Of Indian Tempering – NPR","url":"https://www.npr.org/2011/12/07/143251451/the-crackling-spices-of-indian-tempering"}],"bild":"eintopf","farben":["#d8a52a","#e8c55a","#a8481a"],"schlagworte":["Tadka","Tempering","Linsen","Alltagsküche","Vegan"],"vegetarisch_moeglich":true},{"id":"indien-pav-bhaji","name":"Pav Bhaji","originalname":"","kueche":"indien","region":"Westindien (Mumbai, Maharashtra)","beliebtheit":79,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"hauptgericht","kurz":"Cremig-pikant zerdrücktes Gemüse mit reichlich Butter und Pav Bhaji Masala, dazu in Butter geröstete weiche Brötchen – Mumbais Streetfood-Ikone.","hintergrund":"Pav Bhaji ist ein Gericht aus Mumbai und war ursprünglich ein schnelles Mittagessen für Arbeiter der Textilfabriken. Bhaji ist ein dickes, würziges Gemüsepüree aus Kartoffeln, Zwiebeln, Chilis, Erbsen, Paprika und Tomaten, das auf einer großen Tawa-Platte mit viel Butter gekocht und zerdrückt wird. Pav sind weiche Brötchen, die in geschmolzener Butter geröstet werden. Das Gericht wird mit Zwiebeln, Koriander, Zitrone und einem Butterklecks serviert.","portionen":4,"zeit":{"vorbereitung":25,"garen":50,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Bhaji","liste":[{"menge":400,"einheit":"g","name":"Kartoffeln, mehligkochend","hinweis":"geschält, in 2 cm Würfeln"},{"menge":200,"einheit":"g","name":"Blumenkohl","hinweis":"in kleinen Röschen"},{"menge":100,"einheit":"g","name":"Erbsen","hinweis":"tiefgekühlt"},{"menge":1,"einheit":"Stück","name":"kleine Rote Bete","hinweis":"optional, für Farbe"},{"menge":80,"einheit":"g","name":"Butter","hinweis":"plus mehr zum Servieren"},{"menge":2,"einheit":"Stück","name":"Zwiebeln","hinweis":"fein gehackt"},{"menge":1,"einheit":"Stück","name":"grüne Paprika","hinweis":"fein gewürfelt"},{"menge":4,"einheit":"Stück","name":"reife Tomaten","hinweis":"fein gewürfelt"},{"menge":1,"einheit":"EL","name":"Ingwer-Knoblauch-Paste","hinweis":""},{"menge":1,"einheit":"TL","name":"Kashmiri-Chilipulver","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":1,"einheit":"EL","name":"Zitronensaft","hinweis":""},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]},{"gruppe":"Pav Bhaji Masala (selbst gemischt)","liste":[{"menge":2,"einheit":"EL","name":"Koriandersamen","hinweis":""},{"menge":1,"einheit":"EL","name":"Kreuzkümmelsamen","hinweis":""},{"menge":1,"einheit":"TL","name":"Fenchelsamen","hinweis":""},{"menge":1,"einheit":"TL","name":"schwarze Pfefferkörner","hinweis":""},{"menge":4,"einheit":"Stück","name":"Gewürznelken","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zimtstange, 3 cm","hinweis":""},{"menge":4,"einheit":"Stück","name":"getrocknete rote Chilischoten","hinweis":"Kashmiri"},{"menge":1,"einheit":"TL","name":"Amchur","hinweis":"nach dem Mahlen zugeben"},{"menge":0.5,"einheit":"TL","name":"Kala Namak (Schwarzsalz)","hinweis":"optional"}]},{"gruppe":"Pav","liste":[{"menge":8,"einheit":"Stück","name":"weiche Milchbrötchen (Pav)","hinweis":"ersatzweise weiche Burger-Brötchen oder Mini-Brioche"},{"menge":40,"einheit":"g","name":"Butter","hinweis":"zum Rösten"},{"menge":1,"einheit":"Stück","name":"rote Zwiebel","hinweis":"fein gehackt, zum Servieren"},{"menge":1,"einheit":"Handvoll","name":"frischer Koriander","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zitrone in Spalten","hinweis":""}]}],"ausruestung":["Große, schwere Pfanne oder Tawa","Kartoffelstampfer","Topf zum Kochen","Gewürzmühle"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schäle Kartoffeln und Rote Bete und schneide sie wie den Blumenkohl in gleichmäßig kleine Stücke, damit alles zusammen gar wird. Hacke Zwiebeln, Paprika und Tomaten fein; je kleiner sie sind, desto leichter lassen sie sich später zerdrücken. Stelle die Butter bei Raumtemperatur bereit. Für die Masala legst du alle Gewürze in einem Schälchen bereit. Plane genug Butter ein: Das Gericht ist ohne sie nicht authentisch.","dauer":0,"tipp":"Frische Rote Bete färbt die Bhaji kräftig rot, ohne den Geschmack zu verändern."},{"titel":"Pav-Bhaji-Masala rösten","aktion":"braten","text":"Röste Koriander, Kreuzkümmel, Fenchel, Pfeffer, Nelken, Zimt und getrocknete Chilis in einer trockenen Pfanne bei kleiner Hitze 1,5 bis 2 Minuten unter ständigem Schwenken, bis es kräftig duftet und der Kreuzkümmel leicht dunkler wird. Gib sie auf einen Teller und lasse sie vollständig abkühlen. Mahle sie anschließend fein und mische Amchur und Kala Namak darunter. Das Rösten entwickelt süßlich-nussige Aromen; ein verbrannter Fenchel dagegen macht die Mischung bitter.","dauer":5,"tipp":"Frisch gemahlen duftet die Masala doppelt so intensiv wie gekauftes Pulver."},{"titel":"Gemüse kochen","aktion":"kochen","text":"Gib Kartoffeln, Blumenkohl, Rote Bete und Erbsen mit 400 ml Wasser und einer Prise Salz in einen Topf. Koche alles zugedeckt 15 bis 20 Minuten, bis das Gemüse sehr weich ist und sich leicht zerdrücken lässt. Gieße das Kochwasser nicht weg, du brauchst es später. Zerdrücke das Gemüse mit einem Stampfer grob, es soll weder ganz glatt noch stückig sein.","dauer":20,"tipp":"Wenn du es sehr glatt magst, lasse einen Teil durch ein Sieb."},{"titel":"Zwiebelbasis in Butter","aktion":"anbraten","text":"Schmelze 50 g Butter in einer großen, schweren Pfanne bei mittlerer Hitze, gib die Zwiebeln hinein und brate sie 8 bis 10 Minuten, bis sie weich und goldbraun sind. Gib Ingwer-Knoblauch-Paste dazu und brate eine Minute, bis der Knoblauch nicht mehr roh riecht. Die Butter bräunt leicht und riecht nussig. Wenn sie schwarz wird, war die Hitze zu hoch.","dauer":12,"tipp":"Ein Löffel Öl zur Butter verhindert, dass sie zu schnell verbrennt."},{"titel":"Paprika und Tomaten einkochen","aktion":"koecheln","text":"Gib die Paprika zu den Zwiebeln und brate sie 3 Minuten. Füge Tomaten, Chilipulver, Kurkuma und die Hälfte der selbst gemischten Masala hinzu und koche alles 10 Minuten, bis sich die Tomaten aufgelöst haben und sich Butter am Rand absetzt. Rühre häufig und zerdrücke die Tomaten mit dem Löffel. Dieser Schritt ist das Herzstück: Die Masse muss dick und dunkelrot sein, bevor das Gemüse hineinkommt.","dauer":15,"tipp":"Absetzende Butter am Rand ist das klassische Zeichen für eine fertige Masala."},{"titel":"Gemüse einarbeiten und zerdrücken","aktion":"schmoren","text":"Gib das gekochte, zerdrückte Gemüse in die Pfanne, gieße etwa die Hälfte des Kochwassers dazu und zerdrücke alles mit dem Stampfer direkt in der Pfanne. Koche es 10 bis 15 Minuten bei mittlerer Hitze, rühre häufig und drücke immer wieder mit dem Stampfer nach, bis die Masse cremig, dickflüssig und gleichmäßig rot ist. Gib die restliche Masala und die restliche Butter zu. Wenn die Bhaji zu dick wird, gib heißes Kochwasser dazu. Sie soll wie dicker Brei sein.","dauer":15,"tipp":"Je länger du sie einkochst und zerdrückst, desto cremiger wird sie."},{"titel":"Abschmecken","aktion":"abschmecken","text":"Schmecke die Bhaji mit Salz, Zitronensaft und etwas Masala ab. Sie soll würzig, leicht säuerlich, mild scharf und buttrig sein. Wenn sie flach schmeckt, hilft Zitronensaft. Wenn sie zu scharf ist, gib einen Löffel Butter oder einen Teelöffel Zucker dazu. Halte sie bei kleinster Hitze warm, während du die Brötchen röstest.","dauer":3,"tipp":"Säure am Ende hebt alle Aromen."},{"titel":"Pav in Butter rösten","aktion":"braten","text":"Schneide die Brötchen waagerecht auf, ohne sie ganz zu trennen. Schmelze Butter in einer Pfanne bei mittlerer Hitze, gib eine Prise Pav-Bhaji-Masala dazu und röste die Brötchen mit der Schnittseite nach unten 1 bis 2 Minuten, bis sie goldbraun und knusprig sind. Das Aroma der Butter zieht ein und ergänzt die Bhaji perfekt. Wende sie und röste die Außenseite kurz an.","dauer":6,"tipp":"Butter in der Pfanne nie zu heiß werden lassen, sonst verbrennt sie vor dem Rösten."},{"titel":"Anrichten","aktion":"anrichten","text":"Gib die heiße Bhaji in eine tiefe Schale, setze einen großen Klecks Butter obenauf und streue rohe rote Zwiebeln und frischen Koriander darüber. Serviere sie sofort mit den gerösteten Pav und Zitronenspalten. Man bricht ein Stück Brötchen ab und tunkt es in die Bhaji. Rohe Zwiebeln und Zitrone bringen Frische und Schärfe, die dem butterreichen Gericht Gegengewicht geben. Aufgewärmt schmeckt die Bhaji am nächsten Tag sogar besser, verdünne sie dann mit etwas Wasser.","dauer":0,"tipp":"Die Bhaji schmeckt aufgewärmt sogar besser, mit etwas Wasser verdünnen."}],"profitipps":["Viel Butter ist authentisch.","Rote Bete färbt natürlich und dezent süß.","Gemüse auf der Tawa/Pfanne direkt zerdrücken, so wird es cremig.","Masala frisch rösten und mahlen.","Brötchen in Butter rösten, bis sie knusprig sind."],"varianten":["Jain Pav Bhaji ohne Zwiebel und Knoblauch.","Cheese Pav Bhaji mit geriebenem Käse.","Pav Bhaji Fondue oder Pizza.","Kolhapuri-Variante mit mehr Schärfe."],"beilagen":["Frische Zwiebelringe","Zitronenspalten","Buttermilch","Papad"],"getraenk":"Masala Chai, Lassi oder ein kühles Bier.","koeche":[],"quellen":[{"titel":"Pav bhaji – Wikipedia","url":"https://en.wikipedia.org/wiki/Pav_bhaji"},{"titel":"Garam masala – Wikipedia","url":"https://en.wikipedia.org/wiki/Garam_masala"}],"bild":"pfanne","farben":["#c4381c","#e8742a","#f2d49a"],"schlagworte":["Streetfood","Mumbai","Gemüse","Butter"],"vegetarisch_moeglich":true},{"id":"indien-chingri-malai-curry","name":"Chingri Malai Curry – Bengalisches Garnelencurry in Kokosmilch","originalname":"চিংড়ি মালাইকারি","kueche":"indien","region":"Westbengalen / Kalkutta","beliebtheit":78,"hauptkategorie":"fisch","fischsorte":"meeresfruechte","gang":"hauptgericht","kurz":"Zarte Riesengarnelen in einer cremigen, goldgelben Kokosmilchsauce, mit ganzen Gewürzen, Senföl und einer Prise Zucker – mild, duftend und festlich.","hintergrund":"Chingri Malai Curry ist eines der bekanntesten Festtagsgerichte Bengalens. „Chingri“ heißt Garnele (traditionell die großen Süßwasser-Garnelen, Golda Chingri), „Malai“ Sahne, hier aber Kokosmilch. Anders als andere indische Currys wird es sehr mild gewürzt: keine Chilischärfe, sondern ganze Gewürze wie Kardamom, Zimt und Nelken, dazu Ingwer und eine Prise Zucker. Typisch ist, dass die Garnelen zuerst kurz in Senföl angebraten werden, bevor sie in der Kokossauce ziehen. Es wird mit weißem Reis (Bhaat) gegessen, oft bei Familienessen und Hochzeiten.","portionen":4,"zeit":{"vorbereitung":20,"garen":25,"ruhen":10},"schwierigkeit":2,"zutaten":[{"gruppe":"Garnelen","liste":[{"menge":500,"einheit":"g","name":"große Garnelen, geschält, mit Schwanz, Darm entfernt","hinweis":"TK aus ASC-Zucht; Süßwasser-Flusskrebse als Alternative"},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Curry","liste":[{"menge":3,"einheit":"EL","name":"Senföl","hinweis":"kaltgepresstes aus dem Asia-Laden; Ersatz: Rapsöl + 1 Prise Senfpulver; muss vorher erhitzt werden, bis es nicht mehr scharf riecht"},{"menge":1,"einheit":"EL","name":"Ghee","hinweis":"oder Butterschmalz"},{"menge":2,"einheit":"Stück","name":"Lorbeerblätter","hinweis":""},{"menge":3,"einheit":"Stück","name":"Kardamomkapseln, angedrückt","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zimtstange (3 cm)","hinweis":""},{"menge":4,"einheit":"Stück","name":"Gewürznelken","hinweis":""},{"menge":1,"einheit":"Stück","name":"große Zwiebel, fein gerieben","hinweis":""},{"menge":1,"einheit":"EL","name":"Ingwerpaste","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Chilipulver (Kashmiri)","hinweis":"nur für Farbe"},{"menge":400,"einheit":"ml","name":"Kokosmilch","hinweis":"ungesüßt, ungeschüttelt; die dicke Schicht oben extra verwenden"},{"menge":1,"einheit":"TL","name":"Zucker","hinweis":""},{"menge":2,"einheit":"Stück","name":"grüne Chilis, längs eingeschnitten","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Garam Masala","hinweis":"frisch gemahlen"}]}],"ausruestung":["tiefe Pfanne oder Wok mit Deckel","Reibe","Mörser für Kardamom"],"schritte":[{"titel":"Garnelen vorbereiten und würzen","aktion":"vorbereiten","text":"Schäle die Garnelen, lasse aber den Schwanz dran, und entferne den Darm mit der Messerspitze entlang des Rückens. Spüle sie kurz kalt ab und tupfe sie sehr gut trocken, sonst spritzt das Öl später. Reibe sie mit Kurkuma und Salz ein und lasse sie 10 Minuten stehen. Das Salz würzt, die Kurkuma sorgt für den goldenen Farbton und nimmt den Fischgeruch.","dauer":10,"tipp":""},{"titel":"Senföl erhitzen","aktion":"vorbereiten","text":"Erhitze das Senföl in einer Pfanne bei mittlerer Hitze, bis es leicht raucht und der scharfe, stechende Geruch verfliegt. Das Erhitzen („Raw-Ausbrennen“) macht das Öl mild und nussig. Stelle zur Sicherheit den Dunstabzug an. Nimm die Pfanne kurz vom Herd und lass das Öl 30 Sekunden abkühlen, bevor du weitermachst.","dauer":2,"tipp":"Wer Senföl nicht kennt: Es riecht im rohen Zustand sehr scharf; erst nach dem Erhitzen schmeckt es mild."},{"titel":"Garnelen kurz anbraten","aktion":"anbraten","text":"Brate die Garnelen im heißen Senföl nur 30 bis 40 Sekunden pro Seite, bis sie außen rosa werden, aber innen noch roh sind. Sie sollen nur Farbe und Röstaroma bekommen. Nimm sie sofort heraus und lege sie beiseite, denn sie garen später in der Sauce weiter. Würden sie jetzt durchgaren, wären sie später gummiartig.","dauer":2,"tipp":""},{"titel":"Gewürze anbraten","aktion":"braten","text":"Gib im gleichen Öl Ghee, Lorbeer, Kardamom, Zimt und Nelken hinein und brate sie 20 bis 30 Sekunden, bis sie intensiv duften und die Kardamomkapseln aufplatzen. Die Gewürze verströmen ihre fettlöslichen Aromen im Öl; dies ist die Basis für die milde, würzig-süße Note. Sie dürfen nicht dunkel werden.","dauer":1,"tipp":""},{"titel":"Zwiebel und Ingwer anschwitzen","aktion":"braten","text":"Gib die geriebene Zwiebel und die Ingwerpaste hinein und brate sie bei mittlerer Hitze 5 bis 7 Minuten unter häufigem Rühren, bis die Masse goldgelb ist, nicht braun, und der Rohgeruch verschwindet. Gib das Chilipulver kurz hinzu. Die Zwiebel soll sich fast auflösen und die Sauce später sämig machen.","dauer":7,"tipp":""},{"titel":"Kokosmilch zugeben","aktion":"koecheln","text":"Gieße die Kokosmilch langsam unter Rühren ein, gib Zucker und die geschlitzten grünen Chilis dazu und bringe alles zum leichten Sieden. Lass die Sauce bei kleiner Hitze 8 bis 10 Minuten köcheln, bis sie leicht eindickt und glänzt. Koche sie nicht stark sprudelnd, sonst trennt sich das Fett von der Milch und die Sauce wird körnig.","dauer":10,"tipp":""},{"titel":"Garnelen garen","aktion":"koecheln","text":"Gib die Garnelen zurück in die Sauce und lass sie 3 bis 4 Minuten sanft ziehen, bis sie vollständig rosa-weiß und fest sind. Sie dürfen nur noch leicht glasig aussehen, denn sie garen in der Sauce nach. Zu langes Kochen macht sie hart. Wende sie einmal vorsichtig. Rühre dabei nur sanft, damit die Garnelen nicht zerbrechen und die Sauce glatt bleibt.","dauer":4,"tipp":"Garnelen sind gar bei ca. 60 °C Kerntemperatur; sie bilden ein weites C."},{"titel":"Garam Masala und Abschmecken","aktion":"abschmecken","text":"Nimm die Pfanne vom Herd, rühre das Garam Masala unter und schmecke mit Salz und etwas Zucker ab. Die Sauce soll mild-süßlich, cremig und nach Kardamom und Zimt duften. Lasse das Curry zugedeckt 5 Minuten ziehen, damit sich Aromen verbinden. Sollte die Sauce zu dick sein, verdünne sie mit einem Schluck Wasser.","dauer":5,"tipp":""},{"titel":"Servieren","aktion":"anrichten","text":"Serviere das Curry heiß mit gedämpftem Basmatireis oder Kochreis. Entferne vor dem Essen die ganzen Gewürze oder weise die Gäste darauf hin, dass man sie nicht mitisst. Ein Spritzer frischer Zitronensaft ist nicht traditionell, kann das Gericht aber aufhellen. Das Curry schmeckt am nächsten Tag noch aromatischer, doch die Garnelen sollten dann nur sanft erwärmt werden.","dauer":0,"tipp":""}],"profitipps":["Senföl vor Gebrauch erhitzen, bis der scharfe Geruch weg ist.","Garnelen nur kurz vorbraten; fertig garen sie in der Sauce.","Kokosmilch nie hart kochen, sie trennt sich sonst.","Eine Prise Zucker ist typisch bengalisch und rundet die Gewürze ab.","Ganze Gewürze nicht mitessen – nur zum Duft."],"varianten":["Lau Chingri: mit Flaschenkürbis","Daab Chingri: im Kokosnuss gedämpft (Daab = junge Kokosnuss)","Mit Hummer- oder Flusskrebsschwänzen","Mit Kokosraspel-Paste statt Kokosmilch"],"beilagen":["weißer Reis","Dal","gebratene Aubergine"],"getraenk":"Frischer Weißwein (Riesling Kabinett), Lassi oder Kokoswasser","koeche":[{"name":"Sanjeev Kapoor","bezug":"Der indische Fernsehkoch führt in seiner Rezeptsammlung eine Version „Chingri Macher Malai Curry“ mit Garnelen in Kokosmilch.","quelle":"https://www.sanjeevkapoor.com/Recipe/Chingri-Macher-Malai-Curry.html"}],"quellen":[{"titel":"Sanjeev Kapoor – Chingri Macher Malai Curry","url":"https://www.sanjeevkapoor.com/Recipe/Chingri-Macher-Malai-Curry.html"},{"titel":"UNB – Chingri Malai Curry","url":"https://unb.com.bd/news/tag/129509"}],"bild":"curry","farben":["#e8b84a","#f5e7c0","#8a5a2b"],"schlagworte":["Bengalen","Kokosmilch","Garnelen","mild","Festessen"],"vegetarisch_moeglich":false},{"id":"indien-aloo-paratha","name":"Aloo Paratha","originalname":"","kueche":"indien","region":"Nordindien (Punjab/Haryana)","beliebtheit":78,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"fruehstueck","kurz":"Mit würzigen Kartoffeln gefüllte, in Ghee goldbraun gebratene Fladen – das Frühstück Nordindiens mit Joghurt und Pickles.","hintergrund":"Paratha wird meist mit dem Punjab verbunden, Historiker sehen auch persische oder zentralasiatische Fladenbrote als Vorläufer; ein Rezept steht bereits im Sanskrit-Text Manasollasa aus dem 12. Jahrhundert. Das Wort kommt von para (Schicht). Aloo Paratha ist die häufigste gefüllte Variante: Der Weizenteig wird um eine Füllung aus gewürzten Kartoffeln mit Koriander, grüner Chili, Amchur und Garam Masala geschlossen, ausgerollt und auf der Tawa mit Ghee gebraten. In Punjab und Haryana ist es ein klassisches Frühstück, serviert mit Joghurt, Butter oder Pickle.","portionen":4,"zeit":{"vorbereitung":40,"garen":30,"ruhen":30},"schwierigkeit":2,"zutaten":[{"gruppe":"Teig (8 Paratha)","liste":[{"menge":350,"einheit":"g","name":"Weizenvollkornmehl, fein (Atta)","hinweis":"ersatzweise 200 g Type 1050 und 150 g Type 405"},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"EL","name":"Öl","hinweis":"für den Teig"},{"menge":200,"einheit":"ml","name":"lauwarmes Wasser","hinweis":"nach Bedarf"}]},{"gruppe":"Füllung","liste":[{"menge":500,"einheit":"g","name":"mehligkochende Kartoffeln","hinweis":"in der Schale gekocht, geschält, trocken zerdrückt"},{"menge":1,"einheit":"TL","name":"Kreuzkümmelsamen","hinweis":"trocken geröstet und grob zerstoßen"},{"menge":2,"einheit":"Stück","name":"grüne Chilischoten","hinweis":"fein gehackt"},{"menge":1,"einheit":"EL","name":"frischer Ingwer","hinweis":"gerieben"},{"menge":1,"einheit":"Handvoll","name":"frischer Koriander","hinweis":"fein gehackt"},{"menge":1,"einheit":"TL","name":"Amchur","hinweis":"oder Zitronensaft"},{"menge":1,"einheit":"TL","name":"Garam Masala","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Kashmiri-Chilipulver","hinweis":""},{"menge":1,"einheit":"TL","name":"Anardana (getrocknete Granatapfelkerne)","hinweis":"optional, grob gemahlen"},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]},{"gruppe":"Zum Braten und Servieren","liste":[{"menge":80,"einheit":"g","name":"Ghee oder Butter","hinweis":""},{"menge":200,"einheit":"g","name":"Joghurt","hinweis":"zum Servieren"},{"menge":4,"einheit":"TL","name":"Mango- oder Limetten-Pickle","hinweis":"optional"}]}],"ausruestung":["Gusseiserne Pfanne oder Tawa","Nudelholz","Schüssel","Küchentuch"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Koche die Kartoffeln in der Schale in Salzwasser 20 bis 25 Minuten, bis sie weich sind; ungeschält saugen sie weniger Wasser auf, die Füllung bleibt trocken. Lasse sie vollständig abkühlen, schäle sie und zerdrücke sie mit einer Gabel, ohne dass Klumpen bleiben. Hacke Chili, Ingwer und Koriander fein. Röste Kreuzkümmel kurz trocken an und zerstoße ihn. Stelle Mehl, Wasser und Ghee bereit.","dauer":30,"tipp":"Warme Kartoffeln sind klebrig und machen die Füllung matschig – wirklich abkühlen lassen."},{"titel":"Teig kneten","aktion":"kneten","text":"Vermische Mehl und Salz, gib Öl und nach und nach lauwarmes Wasser dazu und knete 8 bis 10 Minuten, bis ein weicher, geschmeidiger, nicht klebriger Teig entsteht. Er soll weicher sein als Chapati-Teig, damit er sich um die Füllung ziehen lässt, ohne zu reißen. Wenn er zu fest ist, gib einen Teelöffel Wasser dazu. Decke ihn ab und lasse ihn 30 Minuten ruhen, damit das Gluten entspannt.","dauer":40,"tipp":"Ein Teig, der sich wie ein weiches Ohrläppchen anfühlt, ist richtig."},{"titel":"Füllung würzen","aktion":"mischen","text":"Mische die zerdrückten Kartoffeln mit Kreuzkümmel, Chili, Ingwer, Koriander, Amchur, Garam Masala, Chilipulver, Anardana und Salz. Knete die Masse leicht mit den Händen, bis sie homogen ist. Probiere sie und würze kräftig nach, weil der Teig neutral ist und die Füllung abschwächt. Sie soll trocken und leicht krümelig sein; ist sie nass, reißt der Paratha beim Ausrollen.","dauer":5,"tipp":"Eine Prise Chaat Masala macht die Füllung säuerlich und lebendig."},{"titel":"Füllen","aktion":"fuellen","text":"Teile den Teig in 8 Kugeln. Drücke eine Kugel mit den Fingern zu einer Schale flach, gib einen gehäuften Esslöffel Füllung hinein und ziehe die Ränder über der Füllung zusammen, bis sie völlig verschlossen sind. Drücke die Naht fest zu und tauche den Ball in etwas Mehl. Die Füllung darf nicht an den Rand drücken; ist der Teigrand zu dünn, platzt er später. Lege die gefüllten Bälle abgedeckt bereit.","dauer":10,"tipp":"Das Verhältnis ist etwa 2 Teile Teig zu 1 Teil Füllung."},{"titel":"Ausrollen","aktion":"ausrollen","text":"Drücke eine gefüllte Kugel mit der Handfläche flach, rolle sie dann auf einer bemehlten Fläche mit leichtem Druck zu einem Kreis von etwa 15 bis 18 cm aus. Drehe den Teig nach jeder Rollbewegung ein Stück und rolle von der Mitte nach außen. Rolle nicht zu stark drücken, damit die Füllung nicht durchbricht. Falls Füllung austritt, drücke den Riss mit etwas Mehl zu. Der Paratha soll etwa 3 mm dick sein.","dauer":10,"tipp":"Ein wenig Mehl am Nudelholz verhindert Ankleben, zu viel macht den Paratha trocken."},{"titel":"Auf der Tawa braten","aktion":"braten","text":"Erhitze die Tawa oder Gusseisenpfanne bei mittlerer bis hoher Hitze ohne Fett, bis ein Tropfen Wasser sofort verdampft. Lege den Paratha hinein und backe ihn 30 bis 45 Sekunden, bis sich kleine Blasen zeigen. Wende ihn, bestreiche die gebräunte Seite mit etwas Ghee und backe weiter, bis die andere Seite Flecken zeigt. Wende ein letztes Mal, streiche Ghee auf die zweite Seite und drücke leicht mit dem Spatel, damit er sich aufbläht. Beide Seiten sollen goldbraun mit dunklen Flecken sein.","dauer":3,"tipp":"Zu niedrige Hitze macht den Paratha zäh, zu hohe verbrennt vor dem Durchgaren."},{"titel":"Warm halten","aktion":"ruhen","text":"Lege die fertigen Paratha in ein sauberes Küchentuch oder eine Alufolie gewickelt, damit sie warm und weich bleiben. Wiederhole die Schritte mit den restlichen Teigbällen. Backe nacheinander und halte die fertigen Paratha zugedeckt. Der Dampf macht sie weich und saftig. Eine Pfanne, die zwischendurch zu heiß wird, kannst du kurz vom Herd nehmen.","dauer":20,"tipp":"Nicht stapeln ohne Tuch, sonst werden sie klamm."},{"titel":"Anrichten","aktion":"anrichten","text":"Serviere die Aloo Paratha sofort heiß, mit einem Stück Butter oder Ghee obenauf, dazu kühlen Naturjoghurt und scharfes Mango- oder Limettenpickle. So isst man sie klassisch zum Frühstück in Punjab: Man reißt ein Stück ab und tunkt es in den Joghurt. Reste kannst du am nächsten Tag in der Pfanne ohne Fett kurz aufwärmen oder kalt in der Lunchbox mitnehmen; sie schmecken auch lauwarm noch sehr gut.","dauer":0,"tipp":"Ein Löffel Ghee obendrauf gibt Glanz und Geschmack."}],"profitipps":["Kartoffeln in der Schale kochen und vollständig abkühlen lassen.","Füllung trocken und kräftig würzen.","Teig weich halten, damit er sich um die Füllung ziehen lässt.","Mit mittlerer Hitze und Ghee braten, dann wird er knusprig und weich.","Fertige Paratha im Tuch warm halten."],"varianten":["Gobi Paratha mit Blumenkohl-Füllung.","Paneer Paratha mit Paneer und Gewürzen.","Methi Paratha mit Bockshornkleeblättern im Teig.","Lachha Paratha, geschichtet und ungefüllt."],"beilagen":["Joghurt","Mango-Pickle","Butter","Chai"],"getraenk":"Masala Chai oder Lassi.","koeche":[],"quellen":[{"titel":"Paratha – Wikipedia","url":"https://en.wikipedia.org/wiki/Paratha"},{"titel":"Naan (Tava-Methode) – Wikipedia","url":"https://en.wikipedia.org/wiki/Naan"}],"bild":"brot","farben":["#c9902f","#e8c27a","#7a4a1a"],"schlagworte":["Frühstück","Fladenbrot","Gefüllt","Punjab"],"vegetarisch_moeglich":true},{"id":"indien-vada-pav","name":"Vada Pav – Mumbai-Kartoffelburger","originalname":"वडा पाव (Wada pav)","kueche":"indien","region":"Mumbai, Maharashtra","beliebtheit":78,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"snack","themen":["streetfood"],"kurz":"Würziges Kartoffelbällchen im Kichererbsenteig, knusprig frittiert und in ein weiches Brötchen geklemmt – mit scharfer Knoblauchchutney und grünen Chilis. Mumbais Antwort auf den Burger.","hintergrund":"Vada Pav entstand 1966 in Mumbai: Ashok Vaidya soll bei Dadar Station das erste Kartoffel-Vada zwischen zwei Brötchen gelegt haben, damit Fabrikarbeiter schnell und günstig satt wurden. Der Snack besteht aus einer frittierten Kartoffelkugel (Batata Vada), einem weichen Pav-Brötchen und mindestens zwei Chutneys – der trockenen roten Knoblauch-Kokos-Chutney und einer grünen Koriander-Chutney – dazu gehört eine gebratene grüne Chili. In Mumbai ist er so selbstverständlich wie anderswo die Bratwurst und wird oft als „indischer Burger“ bezeichnet.","portionen":4,"zeit":{"vorbereitung":40,"garen":45,"ruhen":20},"schwierigkeit":2,"zutaten":[{"gruppe":"Kartoffelfüllung (8 Vadas)","liste":[{"menge":600,"einheit":"g","name":"mehligkochende Kartoffeln","hinweis":"geschält und gewürfelt"},{"menge":1,"einheit":"EL","name":"Öl","hinweis":""},{"menge":1,"einheit":"TL","name":"Senfsamen","hinweis":""},{"menge":8,"einheit":"Blatt","name":"Curryblätter","hinweis":"optional"},{"menge":2,"einheit":"Zehe","name":"Knoblauch","hinweis":"fein gehackt"},{"menge":1,"einheit":"Stück","name":"Ingwer (2 cm)","hinweis":"fein gehackt"},{"menge":2,"einheit":"Stück","name":"grüne Chilis","hinweis":"fein gehackt"},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":1,"einheit":"Prise","name":"Asafoetida","hinweis":"optional, verdauungsfördernd"},{"menge":3,"einheit":"EL","name":"Koriander","hinweis":"gehackt"},{"menge":1,"einheit":"EL","name":"Zitronensaft","hinweis":""},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]},{"gruppe":"Kichererbsen-Backteig","liste":[{"menge":150,"einheit":"g","name":"Kichererbsenmehl (Besan)","hinweis":"im Asialaden oder Reformhaus"},{"menge":0.25,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":1,"einheit":"Msp.","name":"Natron","hinweis":"für knusprige Luftigkeit"},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":170,"einheit":"ml","name":"Wasser","hinweis":"kalt"},{"menge":1,"einheit":"l","name":"neutrales Öl zum Frittieren","hinweis":""}]},{"gruppe":"Chutney und Brötchen","liste":[{"menge":4,"einheit":"EL","name":"Kokosraspeln, trocken geröstet","hinweis":""},{"menge":8,"einheit":"Zehe","name":"Knoblauch","hinweis":"für die rote Chutney"},{"menge":2,"einheit":"TL","name":"Kashmiri-Chilipulver","hinweis":"oder Paprikapulver edelsüß plus Cayenne"},{"menge":1,"einheit":"Bund","name":"Koriander","hinweis":"für die grüne Chutney"},{"menge":2,"einheit":"Stück","name":"grüne Chilis","hinweis":"für die grüne Chutney"},{"menge":8,"einheit":"Stück","name":"weiche Milchbrötchen (Pav)","hinweis":"Ersatz: kleine Burgerbrötchen oder Milchbrötchen"},{"menge":4,"einheit":"EL","name":"Butter","hinweis":"zum Anrösten"},{"menge":4,"einheit":"Stück","name":"grüne Chilis zum Frittieren","hinweis":"optional"}]}],"ausruestung":["Topf zum Frittieren oder Fritteuse","Küchenthermometer","Mörser oder Mixer","Pfanne","Schaumkelle"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schäle die Kartoffeln und würfle sie in 2 cm große Stücke, damit sie gleichmäßig garen. Hacke Knoblauch, Ingwer und grüne Chilis fein, zupfe den Koriander ab und hacke ihn grob. Wiege Besan, Gewürze und Wasser für den Teig bereit, aber rühre ihn noch nicht an. Stelle die Zutaten für die rote und die grüne Chutney sowie die Pav-Brötchen zusammen. Wärme das Öl zum Frittieren erst später an, damit du es nicht zu lange heiß hältst.","dauer":0,"tipp":""},{"titel":"Kartoffeln garen","aktion":"kochen","text":"Gib die Kartoffelwürfel in einen Topf, bedecke sie mit kaltem Wasser, salze es und bring alles zum Kochen. Lass die Kartoffeln zehn bis zwölf Minuten garen, bis sie weich sind und sich mit einer Gabel leicht zerdrücken lassen, aber nicht zerfallen. Gieße sie ab und lass sie fünf Minuten im offenen Sieb ausdampfen, denn jedes Restwasser macht die Füllung matschig und lässt sie später im Fett zerfallen. Zerdrücke sie grob mit einer Gabel, sodass noch kleine Stücke bleiben.","dauer":15,"tipp":"Mehligkochende Kartoffeln saugen weniger Wasser auf und binden besser."},{"titel":"Kartoffelfüllung würzen","aktion":"braten","text":"Erhitze einen Esslöffel Öl in einer Pfanne und gib die Senfsamen hinein; sobald sie springen, folgen Curryblätter, Knoblauch, Ingwer und Chili. Brate die Mischung eine Minute, bis es würzig duftet, ohne dass der Knoblauch dunkel wird. Rühre Kurkuma und Asafoetida ein, gib die zerdrückten Kartoffeln dazu und vermische alles gründlich. Nimm die Pfanne vom Herd, füge Koriander und Zitronensaft hinzu und schmecke kräftig mit Salz ab; die Füllung muss würziger sein als gewöhnliches Kartoffelpüree, da der Teig sie später verdünnt.","dauer":5,"tipp":""},{"titel":"Kugeln formen und kühlen","aktion":"formen","text":"Forme aus der Kartoffelmasse acht gleich große Kugeln, jede etwa so groß wie ein Tischtennisball, und drücke sie leicht zu kleinen Fladen. Lege sie auf einen Teller und stelle sie 20 Minuten in den Kühlschrank. Gut gekühlte Kugeln halten ihre Form besser, wenn sie in den heißen Teig getaucht werden, und fallen im Fett nicht auseinander. Während sie ruhen, bereitest du die Chutneys und den Teig vor.","dauer":20,"tipp":""},{"titel":"Chutneys zubereiten","aktion":"mischen","text":"Für die rote Chutney zerstößt du Knoblauch, Kokosraspeln und Chilipulver mit einer Prise Salz im Mörser oder im Mixer zu einer groben, krümeligen Paste; ein Esslöffel gerösteter Sesam passt gut dazu. Sie soll trocken, scharf und aromatisch schmecken. Für die grüne Chutney pürierst du Koriander, grüne Chilis, Zitronensaft, Salz und einen Schuss Wasser zu einer glatten Sauce. Beide halten sich im Kühlschrank mehrere Tage.","dauer":5,"tipp":"Die rote Chutney ist das Geheimnis eines guten Vada Pavs – sie sollte brennen und nach Knoblauch duften."},{"titel":"Backteig anrühren","aktion":"aufschlagen","text":"Siebe das Besan in eine Schüssel und gib Kurkuma, Natron und Salz dazu. Gieße das kalte Wasser nach und nach unter ständigem Schlagen mit einem Schneebesen hinein, bis ein glatter, dickflüssiger Teig entsteht, der wie Pfannkuchenteig vom Löffel läuft und die Kugeln gleichmäßig überzieht. Schlage ihn zwei Minuten kräftig, damit er luftig wird. Er ist richtig, wenn ein Löffel beim Eintauchen mit einer dünnen, aber deckenden Schicht überzogen bleibt. Ist er zu dünn, wird die Hülle labbrig, ist er zu dick, wird sie dick und teigig.","dauer":3,"tipp":""},{"titel":"Vadas frittieren","aktion":"frittieren","text":"Erhitze das Öl in einem hohen Topf auf 170 °C – prüfe mit einem Thermometer oder einem Teigtropfen, der sofort aufsteigen und blubbern muss. Tauche jede Kartoffelkugel komplett in den Teig, lasse den Überschuss abtropfen und lege sie vorsichtig ins Öl; frittiere höchstens vier gleichzeitig. Wende sie gelegentlich und backe sie acht bis zehn Minuten, bis sie tief goldbraun und knusprig sind und das Fett weniger blubbert. Hebe sie mit einer Schaumkelle heraus und lasse sie auf Küchenpapier abtropfen. Frittiere zum Schluss die grünen Chilis kurz, bis die Haut Blasen wirft.","dauer":15,"tipp":"Wird das Öl zu heiß, bräunt die Hülle zu früh und die Mitte bleibt kalt."},{"titel":"Pav anrösten","aktion":"braten","text":"Schneide die Brötchen an einer Seite auf, ohne sie ganz zu durchtrennen. Erhitze etwas Butter in einer Pfanne und röste die Brötchen kurz von beiden Seiten, bis sie goldgelb und leicht knusprig sind. Das Anrösten schützt sie vor dem Durchweichen und gibt ein buttriges Aroma, das zur Schärfe der Chutneys passt. Wenn du keine Pfanne verwenden möchtest, wärme die Brötchen im Ofen bei 160 °C kurz auf.","dauer":3,"tipp":""},{"titel":"Zusammenbauen","aktion":"anrichten","text":"Streiche die grüne Chutney großzügig in das Brötchen, streue die rote Chutney darauf, lege ein heißes Vada hinein und drücke das Brötchen leicht zusammen. Reiche die frittierte grüne Chili und etwas Chutney dazu. Gegessen wird mit den Händen und möglichst sofort, solange das Vada innen cremig und außen knusprig ist. In Mumbai wird es oft mit einer Tasse Chai genossen.","dauer":0,"tipp":""}],"profitipps":["Mehlige Kartoffeln und gut ausgedampfte Füllung sind der Schlüssel zu Kugeln, die im Fett nicht zerfallen.","Der Teig braucht kaltes Wasser und kräftiges Schlagen – so wird die Hülle knusprig.","Halte das Öl konstant bei 170 °C und frittiere nur wenige Vadas gleichzeitig.","Die trockene Knoblauchchutney macht den Unterschied zum bloßen Kartoffelbrötchen.","Wer scharf mag, serviert die frittierte Chili mit; wer nicht, lässt sie weg."],"varianten":["Dabeli: gujaratische Verwandte mit süß-scharfer Kartoffelmasse, Erdnüssen und Granatapfelkernen.","Vada Pav mit Käse – beliebt in Mumbai als „Cheese Vada Pav“.","Backofen-Version: Vadas in Panko wälzen und bei 220 °C backen."],"beilagen":["Frittierte grüne Chilis","Masala Chai","Zwiebelsalat"],"getraenk":"Süßer, gewürzter Masala-Chai oder Lassi","koeche":[],"quellen":[{"titel":"Vada pav – Wikipedia","url":"https://en.wikipedia.org/wiki/Vada_pav"},{"titel":"HPPR: Meet Mumbai's iconic veggie burger","url":"https://www.hppr.org/2016-11-04/meet-mumbais-iconic-veggie-burger"},{"titel":"The Jam Lab: Iconic Vada Pav","url":"https://thejamlab.co/recipes/iconic-vada-pav/"}],"bild":"burger","farben":["#d9a441","#c0392b","#6aa84f"],"schlagworte":["Mumbai","Kartoffel","Frittiert","Chutney"],"vegetarisch_moeglich":true},{"originalname":"कुल्फी","region":"Nordindien","hauptkategorie":"suess","fleischsorte":"","gang":"dessert","koeche":[{"name":"Sanjeev Kapoor","bezug":"Der bekannte indische TV-Koch und Kochbuchautor veröffentlicht auf seiner Website mehrere Kulfi-Rezepte, darunter Mango-Kulfi und Matka-Kulfi.","quelle":"https://www.sanjeevkapoor.com/Recipe/Mango-Kulfi-.html"}],"vegetarisch_moeglich":true,"id":"indien-kulfi","name":"Kulfi (Malai Kulfi mit Pistazie und Kardamom)","kueche":"indien","beliebtheit":76,"kurz":"Indisches Eis aus stundenlang eingekochter Milch, Kardamom, Safran und Pistazien – dichter, cremiger und karamelliger als jedes Softeis, und ganz ohne Eismaschine.","hintergrund":"Kulfi stammt aus Nordindien und geht vermutlich auf die Mogulzeit zurück, als Eis mit Schnee aus dem Himalaya gekühlt wurde. Der Name bezieht sich auf die kegelförmige Metallform, in der das Eis traditionell gefroren wird. Anders als westliches Eis wird Kulfi nicht aufgeschlagen: Die Milch wird lange eingekocht, bis sie dickflüssig und leicht karamellig wird, und dann ohne Rühren eingefroren. So entsteht eine feste, kompakte und zugleich cremige Textur, die langsamer schmilzt. Klassisch sind Malai (Rahm), Pistazie, Mango und Rose, verkauft werden sie auf Märkten und an Straßenständen, oft am Holzstiel.","portionen":8,"zeit":{"vorbereitung":15,"garen":65,"ruhen":480},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Kulfi-Masse","liste":[{"menge":1,"einheit":"l","name":"Vollmilch","hinweis":"3,5 % Fett, keine H-Milch mit niedrigem Fettgehalt"},{"menge":200,"einheit":"ml","name":"gezuckerte Kondensmilch","hinweis":"aus der Dose oder Tube"},{"menge":100,"einheit":"ml","name":"Sahne","hinweis":"mindestens 30 % Fett"},{"menge":30,"einheit":"g","name":"Zucker","hinweis":"nach Geschmack"},{"menge":1,"einheit":"Prise","name":"Safranfäden","hinweis":""},{"menge":4,"einheit":"Stück","name":"grüne Kardamomkapseln","hinweis":"in Deutschland im Asialaden oder Gewürzhandel; ersatzweise 1/2 TL gemahlener Kardamom"}]},{"gruppe":"Für die Nüsse und zum Garnieren","liste":[{"menge":40,"einheit":"g","name":"Pistazien","hinweis":"ungesalzen, geschält"},{"menge":20,"einheit":"g","name":"Mandeln","hinweis":"blanchiert"},{"menge":1,"einheit":"EL","name":"Rosenwasser","hinweis":"optional"}]}],"ausruestung":["Breiter, schwerer Topf","Kulfi-Formen, kleine Becher oder Eisformen","Mörser oder Gefrierbeutel mit Nudelholz","Holzlöffel","Alufolie oder Frischhaltefolie"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Hacke Pistazien und Mandeln fein, am besten mit dem Messer, damit sie nicht zu Mehl werden. Öffne die Kardamomkapseln und zerstoße die schwarzen Samen im Mörser zu einem groben Pulver; die Hüllen kannst du entsorgen. Zerreibe die Safranfäden zwischen den Fingern und weiche sie in zwei Esslöffeln warmer Milch ein, damit sie sich gleichmäßig lösen. Stelle die Formen oder Becher bereit.","dauer":10,"tipp":""},{"titel":"Milch einkochen","aktion":"reduzieren","text":"Gieße die Milch in einen breiten, schweren Topf und bringe sie bei mittlerer Hitze zum Kochen. Reduziere dann die Hitze auf niedrige Stufe, sodass sie nur leicht köchelt, und lasse sie etwa 45 bis 60 Minuten einkochen, bis nur noch etwa die Hälfte, also rund 500 ml, übrig ist. Rühre dabei häufig um und kratze die Haut, die sich am Rand bildet, immer wieder unter. Die Milch wird allmählich cremefarben, leicht karamellig und riecht nach gekochter Sahne.","dauer":60,"tipp":"Je breiter der Topf, desto schneller verdampft die Milch."},{"titel":"Süßen und würzen","aktion":"abschmecken","text":"Rühre Kondensmilch, Zucker, Kardamom und eingeweichten Safran in die eingekochte Milch und lasse alles drei bis vier Minuten leise köcheln. Die Masse färbt sich goldgelb und riecht nach Kardamom. Probiere und gib bei Bedarf etwas Zucker dazu; sie soll leicht überzuckert schmecken, denn Kälte dämpft die Süße im Gefrierfach. Nimm den Topf vom Herd.","dauer":5,"tipp":""},{"titel":"Abkühlen und Sahne zugeben","aktion":"mischen","text":"Lasse die Masse bei Raumtemperatur etwa 30 Minuten abkühlen, rühre dabei gelegentlich um, damit sich keine Haut bildet. Rühre die Sahne, die gehackten Nüsse und, wenn du magst, das Rosenwasser unter. Die Masse sollte dick wie Sahnepudding sein und gerade noch fließen. Ist sie noch warm, würde sie im Gefrierer Eiskristalle bilden.","dauer":30,"tipp":""},{"titel":"Einfüllen und einfrieren","aktion":"fuellen","text":"Fülle die Masse in die Formen und lasse oben einen Zentimeter Platz, da sich die Masse beim Gefrieren ausdehnt. Decke die Formen mit Alufolie ab und stecke bei Bedarf Holzstiele durch die Folie. Stelle sie für mindestens acht Stunden, am besten über Nacht, ins Gefrierfach. Der Kern muss vollständig durchgefroren sein; Rühren ist nicht nötig.","dauer":480,"tipp":""},{"titel":"Stürzen und garnieren","aktion":"anrichten","text":"Tauche die Formen kurz, etwa zehn Sekunden, in lauwarmes Wasser und löse die Kulfi vorsichtig mit einem Messer vom Rand. Stürze sie auf einen Teller und schneide sie bei Bedarf in Scheiben. Garniere mit Pistazienhackschnitzeln und Safranfäden. Serviere sofort, solange die Kulfi noch fest ist; sie schmilzt langsamer als normales Eis und hat eine dichte, fast butterartige Textur.","dauer":5,"tipp":""}],"profitipps":["Die Milch langsam einkochen – zu starke Hitze lässt sie anbrennen.","Das Rühren nicht vergessen, sonst bildet sich Haut und Karamell am Topfboden.","Die Masse vollständig abkühlen lassen, bevor sie ins Gefrierfach kommt.","Kardamom frisch zerstoßen – gemahlener hat viel weniger Aroma.","Die Kulfi 10 Minuten vor dem Servieren antauen lassen: das Aroma kommt besser zur Geltung."],"varianten":["Mango-Kulfi mit püriertem Mangomus","Kulfi falooda mit Rosensirup, Nudeln und Basilikumsamen","Kesar-Pista (Safran-Pistazie)","Matka Kulfi: im Tontopf gefroren"],"beilagen":["Rosensirup-Nudeln (Falooda)","Frische Mango"],"getraenk":"Masala Chai oder Lassi","quellen":[{"titel":"Mango Kulfi – Sanjeev Kapoor","url":"https://www.sanjeevkapoor.com/Recipe/Mango-Kulfi-.html"},{"titel":"Mango and pistachio malai kulfi recipe – Lovefood","url":"https://www.lovefood.com/recipes/181769/mango-and-pistachio-malai-kulfi-recipe"},{"titel":"Kulfi (Indian Ice Cream With Nuts) – Food.com","url":"https://www.food.com/recipe/kulfi-indian-ice-cream-with-nuts-284802"}],"bild":"dessert","farben":["#e8c36a","#f3e5b7","#7a8f3c"],"schlagworte":["Eis","Kardamom","Safran","Ohne Eismaschine"]},{"id":"indien-besan-ladoo-diwali","name":"Besan Ladoo – Kichererbsenmehl-Kugeln zu Diwali","originalname":"बेसन के लड्डू (Besan ke Laddu)","kueche":"indien","region":"Nordindien","beliebtheit":76,"hauptkategorie":"suess","gang":"dessert","themen":["fest"],"kurz":"Goldgelbe Kugeln aus in Ghee geröstetem Kichererbsenmehl, Zucker und Kardamom: nussig, zart schmelzend, das Lieblingsgebäck zu Diwali.","hintergrund":"Diwali, das Lichterfest, wird im Oktober oder November gefeiert und markiert in Indien den Sieg des Lichts über die Dunkelheit. Häuser werden mit Öllämpchen (Diyas) und Rangoli-Mustern geschmückt, die Familien tauschen Geschenke aus und verteilen Süßigkeiten (Mithai) an Nachbarn und Gäste. Besan Ladoo gehört zu den beliebtesten: Das Kichererbsenmehl wird geduldig in Ghee goldbraun geröstet, bis es herrlich nach Nüssen duftet, danach mit Zucker und Kardamom vermischt und von Hand zu Kugeln geformt. Zu Festen wie Diwali, Raksha Bandhan oder Ganesh Chaturthi werden sie in großen Mengen zubereitet und als Opfergaben (Prasad) verteilt. Wegen des einfachen Rezepts lernen schon Kinder, sie zu rollen.","portionen":8,"zeit":{"vorbereitung":15,"garen":25,"ruhen":30},"schwierigkeit":2,"zutaten":[{"gruppe":"Für ca. 16 Ladoos","liste":[{"menge":250,"einheit":"g","name":"Besan (Kichererbsenmehl)","hinweis":"im Asia- oder Bioladen; für grobere Ladoos „Besan coarse“ (Ladoo besan)"},{"menge":125,"einheit":"g","name":"Ghee (Butterschmalz)","hinweis":"alternativ geklärte Butter"},{"menge":150,"einheit":"g","name":"Puderzucker","hinweis":"oder fein gemahlener Zucker (Boora)"},{"menge":0.5,"einheit":"TL","name":"Kardamom, frisch gemahlen","hinweis":"aus grünen Kapseln"},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":3,"einheit":"EL","name":"Cashews oder Pistazien, gehackt","hinweis":"zum Bestreuen und für Biss"},{"menge":2,"einheit":"EL","name":"Milch","hinweis":"optional, 1 EL zum Aufbrausen des Mehls"}]}],"ausruestung":["Schwere Pfanne oder Wok","Pfannenwender","Schüssel","Küchenwaage","Teller"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege Besan, Ghee und Zucker ab. Siebe das Kichererbsenmehl durch ein feines Sieb, um Klümpchen zu entfernen, denn dann röstet es gleichmäßig. Mahle die Kardamomsamen frisch im Mörser, da sie nur so ihr volles Aroma abgeben, und hacke die Nüsse grob. Wenn dein Zucker nicht fein genug ist, mahle ihn kurz in der Küchenmaschine zu Pulver. Stelle einen Teller und eine Schüssel bereit, in die du das geröstete Mehl später umfüllst, damit es abkühlen kann.","dauer":0,"tipp":""},{"titel":"Ghee erhitzen","aktion":"vorbereiten","text":"Schmilz das Ghee in einer schweren Pfanne oder einem Wok bei niedriger bis mittlerer Hitze, bis es flüssig und klar ist. Das Ghee sollte nur sanft erhitzt sein und leicht duften, aber nicht rauchen; zu heißes Ghee verbrennt das Mehl, ehe es richtig geröstet ist. Verwende eine Pfanne mit dickem Boden, damit die Hitze gleichmäßig verteilt wird, und lege alle Zutaten griffbereit hin, denn das Rösten verlangt volle Aufmerksamkeit.","dauer":3,"tipp":""},{"titel":"Besan langsam rösten","aktion":"anbraten","text":"Gib das gesiebte Besan ins heiße Ghee und rühre es ständig mit einem Pfannenwender bei niedriger bis mittlerer Hitze. Zuerst wird die Masse klumpig und dickflüssig, nach etwa 5 Minuten wird sie lockerer und beginnt zu schäumen. Röste weiter, bis sie nach 15 bis 20 Minuten goldbraun ist, sich cremig anfühlt und ein intensiver, nussiger Duft die Küche füllt. Die Farbe wechselt von hellgelb zu tiefem Goldbraun; wenn das Mehl dunkel wird und bitter riecht, ist es zu stark geröstet. Das Besan muss durch und durch geröstet sein, sonst schmeckt es roh und mehlig.","dauer":20,"tipp":"Geduld ist hier die wichtigste Zutat: Zu hohe Hitze verbrennt das Mehl, bevor es gar ist."},{"titel":"Abkühlen lassen","aktion":"kuehlen","text":"Nimm die Pfanne vom Herd und gib 1 Esslöffel Milch oder etwas Wasser hinein: Es zischt kurz und macht die Masse locker und krümelig. Das Besan muss nun auf eine handwarme Temperatur abkühlen, was etwa 10 bis 15 Minuten dauert; rühre währenddessen zwei- bis dreimal um. Mit dem Zucker darf es erst vermischt werden, wenn es nur noch warm, nicht mehr heiß ist, denn sonst schmilzt der Zucker, die Masse wird klebrig und die Ladoos werden hart.","dauer":15,"tipp":""},{"titel":"Zucker und Gewürze unterheben","aktion":"mischen","text":"Gib den Puderzucker, den Kardamom, das Salz und die Hälfte der gehackten Nüsse zum abgekühlten Besan und vermische alles gründlich mit den Händen oder einem Löffel. Die Masse soll feucht wirken, aber noch lose und krümelig sein; wenn du eine Handvoll fest zusammendrückst, muss sie ihre Form halten. Ist sie zu trocken und bröckelt auseinander, gibst du ein bis zwei Teelöffel warmes Ghee dazu; ist sie zu feucht, lasse sie noch 5 Minuten offen stehen.","dauer":10,"tipp":""},{"titel":"Zu Kugeln formen","aktion":"formen","text":"Nimm etwa zwei gehäufte Esslöffel der Masse in die Hand und drücke sie fest zusammen, während du sie zwischen den Handflächen zu glatten Kugeln von etwa 4 cm Durchmesser rollst. Drücke in jede Kugel mit dem Daumen oben ein paar gehackte Nüsse als Dekor. Arbeite zügig, denn die Masse wird beim Abkühlen fester und lässt sich nicht mehr so gut formen. Leg die fertigen Ladoos auf einen Teller, ohne dass sie sich berühren.","dauer":15,"tipp":"Befeuchte die Handflächen mit ein paar Tropfen Ghee, falls die Masse klebt."},{"titel":"Ruhen und servieren","aktion":"ruhen","text":"Lasse die Ladoos mindestens 30 Minuten bei Raumtemperatur ruhen, damit das Ghee fest wird und die Kugeln ihre Form behalten. Bewahre sie in einer luftdichten Dose bei Zimmertemperatur auf, wo sie sich 2 bis 3 Wochen halten. Zu Diwali bringst du sie auf einem Tablett mit Silber- oder Goldfolie (Varak) zu Tisch, verschenkst sie in Schachteln an Nachbarn oder legst sie als Opfergabe vor das Götterbild. Dazu passt ein würziger Chai.","dauer":30,"tipp":""}],"profitipps":["Langsam und lange rösten: Das Mehl muss richtig duften und goldbraun sein, sonst schmeckt es roh.","Mehl vorher sieben, sonst entstehen Klümpchen.","Zucker erst unterheben, wenn die Masse nur noch handwarm ist.","Reichlich Ghee verwenden; zu wenig macht die Ladoos trocken und bröselig.","Gutes, frisch gemahlenes Kardamom macht den Unterschied."],"varianten":["Mit Kokosraspeln und Mandelsplittern","Mit Rosinen und Safran","Bundi Ladoo: aus frittierten Kichererbsenmehl-Perlen in Zuckersirup","Mit Jaggery (Palmzucker) statt Zucker, dunkler und herber"],"beilagen":["Masala Chai","Weitere Mithai wie Gulab Jamun oder Kaju Katli","Trockenfrüchte"],"getraenk":"Heißer Masala Chai oder warme Milch mit Safran","koeche":[],"quellen":[{"titel":"Ministry of Curry – Besan Ladoo Recipe","url":"https://ministryofcurry.com/besan-ladoo-recipe/"},{"titel":"Indian Healthy Recipes – Authentic Besan Ladoo Recipe","url":"https://www.indianhealthyrecipes.com/besan-ladoo-recipe/"},{"titel":"Gulf News – Make Besan Ladoo for Diwali","url":"https://gulfnews.com/food/cooking-cuisines/make-besan-ladoo-for-the-festival-of-lights-diwali-1.1635942203833"}],"bild":"dessert","farben":["#d99a2b","#e9c55d","#f7e7a8"],"schlagworte":["Diwali","Mithai","Ghee","Indien","Lichterfest"],"vegetarisch_moeglich":true},{"id":"indien-idli-kokos-chutney","name":"Idli mit Kokos-Chutney","originalname":"இட்லி","kueche":"indien","region":"Südindien (Tamil Nadu, Karnataka)","beliebtheit":76,"hauptkategorie":"vegan","kurz":"Fluffige, gedämpfte Reis-Linsen-Küchlein, die aus einem über Nacht fermentierten Teig entstehen, dazu cremiges Kokos-Chutney mit Curryblatt-Tempering.","hintergrund":"Idli sind das Frühstück Südindiens schlechthin, in Tamil Nadu, Karnataka und Kerala isst man sie jeden Morgen, im Restaurant genauso wie zu Hause. Der Teig aus Reis und geschälten schwarzen Linsen (Urad Dal) wird über Nacht fermentiert, wodurch die Küchlein beim Dämpfen luftig aufgehen und leicht säuerlich schmecken. Traditionell werden sie mit Kokos-Chutney, Sambar und Chutney-Pulver serviert. Weil sie ohne Öl gedämpft werden, gelten sie als leicht und gut verdaulich. Die Kunst liegt in der Gärung: Ist der Teig gut aufgegangen, werden die Idli weich wie Wolken.","portionen":4,"zeit":{"vorbereitung":40,"garen":15,"ruhen":1200},"schwierigkeit":2,"zutaten":[{"gruppe":"Idli-Teig (ergibt ca. 20 Idli)","liste":[{"menge":300,"einheit":"g","name":"Idli-Reis oder parboiled Rundkornreis","hinweis":"ersatzweise Parboiled-Reis, kein Basmati"},{"menge":100,"einheit":"g","name":"Urad Dal, ganz und geschält (weiße Linsen)","hinweis":"im indischen Laden"},{"menge":0.5,"einheit":"TL","name":"Bockshornkleesamen (Methi)","hinweis":""},{"menge":1.5,"einheit":"TL","name":"Salz","hinweis":"nicht jodiert, am besten Meersalz"},{"menge":null,"einheit":"","name":"Wasser","hinweis":"zum Einweichen und Mahlen"},{"menge":null,"einheit":"","name":"Öl","hinweis":"zum Einfetten der Formen"}]},{"gruppe":"Kokos-Chutney","liste":[{"menge":100,"einheit":"g","name":"frische oder tiefgekühlte Kokosraspel","hinweis":"ersatzweise ungesüßte Kokosraspel, 10 Minuten in heißem Wasser quellen lassen"},{"menge":2,"einheit":"EL","name":"Röstkichererbsen (Pottukadalai/Dalia)","hinweis":"ersatzweise Erdnüsse oder geröstete Cashews"},{"menge":2,"einheit":"Stück","name":"grüne Chilischoten","hinweis":""},{"menge":1,"einheit":"Stück","name":"Ingwer, daumengroß (ca. 1 cm)","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":100,"einheit":"ml","name":"Wasser","hinweis":""}]},{"gruppe":"Tempering","liste":[{"menge":1,"einheit":"EL","name":"Kokosöl oder Sesamöl","hinweis":""},{"menge":1,"einheit":"TL","name":"schwarze Senfsamen","hinweis":""},{"menge":1,"einheit":"TL","name":"Urad Dal","hinweis":""},{"menge":1,"einheit":"Zweig","name":"Curryblätter","hinweis":""},{"menge":1,"einheit":"Stück","name":"getrocknete rote Chilischote","hinweis":""},{"menge":1,"einheit":"Prise","name":"Asafoetida (Hing)","hinweis":"optional"}]}],"ausruestung":["Idli-Dämpfer mit Formen oder Dampfgarer mit Silikonförmchen","leistungsstarker Mixer oder Standmixer","große Schüssel (Teig geht auf das Doppelte auf)","kleine Pfanne für das Tempering"],"schritte":[{"titel":"Mise en place und Einweichen","aktion":"vorbereiten","text":"Wasche Reis und Urad Dal getrennt in mehreren Wassern, bis das Wasser fast klar ist. Gib den Reis in eine Schüssel und bedecke ihn mit reichlich Wasser; die Linsen kommen mit den Bockshornkleesamen in eine zweite Schüssel, ebenfalls mit Wasser bedeckt. Lasse beides 5–6 Stunden einweichen. Die Körner quellen auf und werden weich, sodass sie sich später leicht zu einem feinen Teig mahlen lassen. Wer abends einweicht, kann morgens mahlen.","dauer":0,"tipp":"Bockshornklee nicht weglassen, er unterstützt die Gärung und gibt einen feinen Duft."},{"titel":"Linsen zu Schaum mahlen","aktion":"puerieren","text":"Gieße die Linsen ab und hebe das Einweichwasser auf. Gib sie in den Mixer und mahle sie mit etwa 100 ml kaltem Wasser, das du esslöffelweise zugibst, 8–10 Minuten, bis eine sehr feine, luftige, schaumige Masse entsteht. Sie sollte vom Löffel in dicken Bändern fließen und sich leicht aufblähen. Zwischendurch den Mixer pausieren lassen, damit der Teig nicht heiß wird, denn Wärme tötet die Gärung ab. Gib den Teig in eine große Schüssel.","dauer":10,"tipp":""},{"titel":"Reis mahlen und mischen","aktion":"puerieren","text":"Gib den abgetropften Reis in den Mixer und mahle ihn mit wenig Wasser 3–4 Minuten, bis die Masse körnig-fein ist, wie sehr feiner Grieß. Der Reisteig soll nicht ganz glatt sein, das gibt den Idli später Struktur. Vermische ihn in der großen Schüssel mit dem Linsenteig und rühre mit der Hand etwa 2 Minuten: Die Wärme der Hand fördert die Gärung. Der Teig soll dickflüssig sein, wie dicker Pfannkuchenteig.","dauer":6,"tipp":"Mahle mit eiskaltem Wasser, damit der Teig im Mixer nicht warm wird."},{"titel":"Fermentieren","aktion":"gehen","text":"Salze den Teig mit 1,5 TL Salz und rühre durch. Stelle die Schüssel abgedeckt an einen warmen Ort (25–30 °C, z. B. im ausgeschalteten Backofen mit Licht) für 8–12 Stunden. Der Teig hat sich in der Zeit fast verdoppelt, ist luftig, riecht leicht säuerlich-hefig und hat kleine Bläschen an der Oberfläche. Bei kühlem Wetter dauert die Gärung länger, bis zu 18 Stunden. Rühre den Teig nach der Gärung nur sanft um, damit die Luftbläschen nicht entweichen.","dauer":600,"tipp":"Zum Fermentieren eignet sich eine Schüssel mit viel Platz, der Teig steigt hoch."},{"titel":"Kokos-Chutney mahlen","aktion":"puerieren","text":"Gib Kokos, Röstkichererbsen, Chili, Ingwer und Salz in den Mixer und mahle mit 100 ml Wasser zu einer feinen, cremigen Paste. Probiere: Das Chutney soll mild nach Kokos schmecken, mit einer feinen Schärfe. Ist es zu dick, gib etwas Wasser dazu; es sollte wie dicker Joghurt vom Löffel fallen. Gib es in eine Schüssel.","dauer":0,"tipp":""},{"titel":"Tempering für das Chutney","aktion":"anbraten","text":"Erhitze das Kokosöl in einer kleinen Pfanne bei mittlerer Hitze, bis es leicht schimmert. Gib die Senfsamen hinein: Sie beginnen nach wenigen Sekunden zu springen und zu knistern, decke die Pfanne dabei kurz mit einem Deckel ab. Füge dann Urad Dal, Chilischote und Asafoetida hinzu und rühre 20–30 Sekunden, bis die Linsen goldgelb sind. Gib die Curryblätter dazu, sie spritzen und duften sofort intensiv nach Zitrus und Nuss. Gieße das heiße Öl samt Gewürzen über das Chutney und lasse es kurz einziehen, bevor du umrührst.","dauer":2,"tipp":"Das Tempering immer heiß über das Chutney gießen, dann entfaltet sich das Aroma."},{"titel":"Idli dämpfen","aktion":"daempfen","text":"Bringe Wasser im Dämpfer zum Kochen und fette die Idli-Formen leicht mit Öl ein. Fülle den Teig mit einem Löffel zu etwa dreiviertel in jede Mulde. Setze die Formen in den Dämpfer, schließe den Deckel und dämpfe die Idli 10–12 Minuten bei starker Hitze. Mache die Garprobe mit einem Zahnstocher: Kommt er sauber heraus, sind die Idli gar. Sie sollen weiß, weich und federnd sein.","dauer":12,"tipp":"Idli 3 Minuten ruhen lassen, dann lassen sie sich leichter lösen. Mit nassem Löffel herauslösen."},{"titel":"Anrichten","aktion":"anrichten","text":"Löse die Idli mit einem nassen Löffel vorsichtig aus den Formen und schichte sie warm auf einen Teller; sie sollen weiß, weich und federnd sein. Serviere sie mit dem Kokos-Chutney, dazu passen Sambar oder Chutney-Pulver mit Sesamöl. Gegessen wird mit den Fingern: Reiße ein Stück ab und tauche es ins Chutney. Übrig gebliebene Idli lassen sich am nächsten Tag kurz nachdämpfen oder in Stücke geschnitten mit Senfsamen und Zwiebeln in der Pfanne anbraten.","dauer":0,"tipp":""}],"profitipps":["Der Teig braucht Wärme: Im kalten Haus Backofen mit Licht oder Joghurt-Modus nutzen.","Reis nicht zu fein mahlen, die Körnigkeit gibt Struktur.","Linsen lange mixen, bis sie schaumig sind – das macht die Idli luftig.","Salz erst direkt vor der Gärung zugeben.","Zum Dämpfen genug Wasser im Topf lassen, es darf nicht trocken kochen."],"varianten":["Rava Idli aus Grieß, ohne Gärung","Kanchipuram Idli mit Gewürzen","Podi Idli mit Chutney-Pulver","Masala Idli in der Pfanne mit Zwiebeln und Tomaten","Poha Idli mit Reisflocken"],"beilagen":["Sambar","Tomaten-Chutney","Chutney-Pulver mit Sesamöl","Filterkaffee"],"getraenk":"Südindischer Filterkaffee (Kaapi) oder Masala Chai.","quellen":[{"titel":"Poha Idli (Veg Recipes of India)","url":"https://www.vegrecipesofindia.com/poha-idli-recipe-idli-recipes/"},{"titel":"Poha Idli Recipe (Tarla Dalal)","url":"https://cdn.tarladalal.com/poha-idli--how-to-make-poha-idli--32834r"}],"bild":"dip","farben":["#f5efe0","#c9a66b","#4f8a3b"],"schlagworte":["Südindien","fermentiert","gedämpft","vegan"],"vegetarisch_moeglich":true,"gang":"fruehstueck","fleischsorte":"","koeche":[]},{"id":"indien-malai-kofta","name":"Malai Kofta","originalname":"","kueche":"indien","region":"Nordindien (Mughlai-Küche)","beliebtheit":76,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"hauptgericht","kurz":"Zarte, frittierte Paneer-Kartoffel-Klößchen in einer reichhaltigen, milden Sahne-Cashew-Sauce – das vegetarische Festessen der Mughlai-Küche.","hintergrund":"Kofta bedeutet gestoßenes Fleisch (persisch kuftan); die Klößchen-Familie reicht von Persien bis zum Balkan. In Nordindien entstand mit Malai Kofta die vegetarische Variante: Paneer und Kartoffeln werden zu Bällchen geformt, mit Nüssen und Rosinen gefüllt, frittiert und in einer cremigen Sauce aus Tomaten, Cashews und Sahne (malai) serviert. Die Sauce gehört zur Mughlai-Tradition mit Nüssen, Sahne und milden Gewürzen. Man isst es zu Naan oder Pulao bei Festessen.","portionen":4,"zeit":{"vorbereitung":45,"garen":50,"ruhen":15},"schwierigkeit":3,"zutaten":[{"gruppe":"Kofta (ca. 12 Stück)","liste":[{"menge":200,"einheit":"g","name":"Paneer","hinweis":"fein gerieben"},{"menge":200,"einheit":"g","name":"mehligkochende Kartoffeln","hinweis":"gekocht, trocken zerdrückt"},{"menge":2,"einheit":"EL","name":"Speisestärke (Maismehl)","hinweis":"bindet; nicht mehr nehmen"},{"menge":1,"einheit":"Stück","name":"grüne Chilischote","hinweis":"fein gehackt"},{"menge":1,"einheit":"TL","name":"Ingwer, gerieben","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Garam Masala","hinweis":""},{"menge":12,"einheit":"Stück","name":"Cashewkerne","hinweis":"gehackt, für die Füllung"},{"menge":12,"einheit":"Stück","name":"Rosinen","hinweis":"für die Füllung"},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":500,"einheit":"ml","name":"Frittieröl","hinweis":""}]},{"gruppe":"Sauce","liste":[{"menge":2,"einheit":"EL","name":"Ghee oder Butter","hinweis":""},{"menge":1,"einheit":"TL","name":"Kreuzkümmelsamen","hinweis":""},{"menge":2,"einheit":"Stück","name":"Zwiebeln","hinweis":"grob gehackt"},{"menge":1,"einheit":"EL","name":"Ingwer-Knoblauch-Paste","hinweis":""},{"menge":3,"einheit":"Stück","name":"reife Tomaten","hinweis":"grob gehackt"},{"menge":40,"einheit":"g","name":"Cashewkerne","hinweis":"30 Minuten in heißem Wasser eingeweicht"},{"menge":4,"einheit":"Stück","name":"grüne Kardamomkapseln","hinweis":""},{"menge":1,"einheit":"TL","name":"Kashmiri-Chilipulver","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":1,"einheit":"TL","name":"gemahlener Koriander","hinweis":""},{"menge":120,"einheit":"ml","name":"Sahne","hinweis":""},{"menge":1,"einheit":"TL","name":"Zucker","hinweis":""},{"menge":1,"einheit":"TL","name":"Garam Masala","hinweis":"zum Schluss"},{"menge":1,"einheit":"EL","name":"Kasuri Methi","hinweis":""},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]}],"ausruestung":["Tiefer Topf zum Frittieren","Fritierthermometer","Mixer","Feines Sieb","Schaumlöffel","Weite Pfanne für die Sauce"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Koche die Kartoffeln in der Schale, lasse sie abkühlen und schäle sie. Zerdrücke sie fein und trocken, damit keine Klumpen entstehen. Reibe den Paneer fein auf der Haushaltsreibe. Weiche die Cashews für die Sauce 30 Minuten in heißem Wasser ein. Hacke Zwiebeln, Tomaten, Chili und Ingwer. Lege die Füllung aus gehackten Cashews und Rosinen bereit. Heize das Öl später auf, denn die Kofta müssen schnell frittiert werden.","dauer":30,"tipp":"Kartoffeln nach dem Kochen auf dem Küchentuch ausdampfen lassen, sie sollen trocken sein."},{"titel":"Kofta-Teig herstellen","aktion":"kneten","text":"Vermische Paneer, Kartoffeln, Speisestärke, Chili, Ingwer, Garam Masala und Salz mit den Händen 2 bis 3 Minuten, bis die Masse glatt und formbar ist. Sie soll fest genug sein, um eine Kugel zu halten, aber nicht trocken. Wenn sie zu weich ist, gib einen Esslöffel Stärke dazu, ist sie zu bröselig, gib einen Teelöffel Milch dazu. Probiere nicht roh, aber würze kräftig, denn die Kofta verlieren im Fett an Aroma. Kühle die Masse 15 Minuten.","dauer":20,"tipp":"Zu viel Stärke macht die Kofta hart – lieber ein bisschen weniger."},{"titel":"Kofta füllen und formen","aktion":"fuellen","text":"Befeuchte die Hände leicht mit Öl. Teile die Masse in 12 Portionen, drücke jede flach, gib einige Cashewstücke und eine Rosine in die Mitte und schließe die Masse fest darüber. Rolle die Bälle zwischen den Handflächen, bis sie völlig glatt und rissfrei sind; Risse lassen im Fett Füllung austreten. Lege sie auf einen Teller und kühle sie bis zum Frittieren.","dauer":15,"tipp":"Ganz glatte Oberflächen verhindern, dass sie im Fett zerfallen."},{"titel":"Kofta frittieren","aktion":"frittieren","text":"Erhitze Öl auf 170 °C. Gib 4 bis 5 Kofta vorsichtig hinein. Rühre sie nicht in den ersten 30 Sekunden an, damit sie eine Kruste bilden. Frittiere sie 3 bis 4 Minuten, bis sie gleichmäßig goldbraun sind, und wende sie sanft mit einem Schaumlöffel. Lasse sie auf Küchenpapier abtropfen. Wenn das Öl zu kalt ist, saugen sie sich voll und zerfallen; ist es zu heiß, bräunen sie außen zu stark, bleiben innen kalt.","dauer":15,"tipp":"Ein Probekloß zeigt, ob die Masse hält, bevor du alle frittierst."},{"titel":"Sauce-Basis kochen","aktion":"anbraten","text":"Erhitze Ghee in einer weiten Pfanne bei mittlerer Hitze, gib Kreuzkümmel und Kardamom hinein und warte 20 Sekunden, bis sie duften. Füge die Zwiebeln hinzu und brate sie 8 bis 10 Minuten glasig, ohne dass sie braun werden; helle Zwiebeln ergeben eine helle, milde Sauce. Gib Ingwer-Knoblauch-Paste dazu, brate eine Minute, dann Tomaten und Gewürze (Kurkuma, Koriander, Chili). Koche 10 bis 12 Minuten, bis die Tomaten völlig weich sind.","dauer":25,"tipp":"Wer eine besonders helle Sauce möchte, lässt Kurkuma und Chili weg."},{"titel":"Sauce pürieren und passieren","aktion":"puerieren","text":"Gib die eingeweichten Cashews zur Sauce, püriere alles im Mixer sehr fein und streiche es durch ein Sieb. Die Sauce soll glatt wie Samt sein. Gib sie zurück in die Pfanne und erhitze sie bei kleiner Hitze 5 Minuten. Rühre häufig, damit sie nicht anbrennt. Die Farbe soll hell orange bis cremig sein. Ist sie zu dick, gib heißes Wasser dazu; ist sie zu dünn, koche sie ein.","dauer":10,"tipp":"Wenn die Cashews nicht lange genug eingeweicht wurden, wird die Sauce körnig."},{"titel":"Sahne und Gewürze","aktion":"abschmecken","text":"Rühre Sahne und Zucker ein und erwärme alles bei sanfter Hitze, ohne zu kochen. Zerreibe Kasuri Methi zwischen den Handflächen und streue es mit dem Garam Masala darüber. Schmecke mit Salz ab. Die Sauce soll reichhaltig, mild süßlich und aromatisch sein. Halte sie warm, aber lasse die Kofta noch nicht hinein.","dauer":5,"tipp":"Zu heiße Sahne kann gerinnen – immer sanft erwärmen."},{"titel":"Zusammenführen und Anrichten","aktion":"anrichten","text":"Lege die Kofta erst unmittelbar vor dem Servieren in die heiße Sauce oder auf einen Teller und gieße die Sauce darüber. Sie sind weich und würden in der Sauce zerfallen, wenn sie zu lange liegen. Streue frischen Koriander und ein paar Cashews darüber und ziehe einen Faden Sahne darüber. Serviere sofort mit Naan, Pulao oder Jeera-Reis.","dauer":0,"tipp":"Immer erst am Tisch zusammenführen, so bleiben die Kofta intakt."}],"profitipps":["Kofta erst kurz vor dem Servieren in die Sauce legen.","Kartoffeln trocken zerdrücken, sonst zerfallen die Kofta.","Zwiebeln für die Sauce hell lassen für eine milde Farbe.","Sauce passieren für Samtkonsistenz.","Temperatur des Öls kontrollieren."],"varianten":["Gebackene Kofta bei 200 °C Ober-/Unterhitze für 20 Minuten.","Lauki Kofta mit Flaschenkürbis.","Kofta-Curry mit Tomaten-Zwiebel-Sauce.","Fleisch-Kofta (Nargisi Kofta) mit Hackfleisch."],"beilagen":["Naan","Jeera-Reis oder Pulao","Zwiebel-Salat","Raita"],"getraenk":"Lassi, Chai oder ein halbtrockener Riesling.","koeche":[],"quellen":[{"titel":"Kofta – Wikipedia (Malai kofta)","url":"https://en.wikipedia.org/wiki/Malai_kofta"},{"titel":"Navratan korma – Wikipedia","url":"https://en.wikipedia.org/wiki/Navratan_korma"}],"bild":"curry","farben":["#d9852a","#f0c070","#f6e6c0"],"schlagworte":["Mughlai","Festessen","Vegetarisch","Kofta"],"vegetarisch_moeglich":true},{"id":"indien-navratan-korma","name":"Navratan Korma","originalname":"","kueche":"indien","region":"Nordindien (Mughlai-Küche)","beliebtheit":75,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"hauptgericht","kurz":"Neun Zutaten wie neun Edelsteine – buntes Gemüse, Paneer, Nüsse und Rosinen in einer milden, cremigen Cashew-Joghurt-Sauce mit Safran und Kardamom.","hintergrund":"Navratan heißt neun Juwelen und spielt auf die neun Berater am Hof des Mughal-Kaisers Akbar an; in der Küche steht der Name für ein festliches Gericht mit vielen Zutaten. Korma stammt aus den Hofküchen der Mughals und ist im 18. Jahrhundert belegt, als Köche ein persisch geprägtes Schmorgericht mit Mandeln, Knoblauch, Gewürzen und Joghurt anreicherten. Das Wort bedeutet schmoren und ist mit dem türkischen Wort für Gebratenes verwandt. Navratan Korma ist die vegetarische Variante mit Gemüse, Paneer, Nüssen und manchmal Obst. Das britische Curry-House-Korma ist eine stark vereinfachte, mildere Version.","portionen":4,"zeit":{"vorbereitung":40,"garen":45,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Gemüse und Einlagen","liste":[{"menge":200,"einheit":"g","name":"Kartoffeln","hinweis":"in 2 cm Würfeln"},{"menge":150,"einheit":"g","name":"Möhren","hinweis":"in 1 cm Würfeln"},{"menge":150,"einheit":"g","name":"grüne Bohnen","hinweis":"in 2 cm Stücken"},{"menge":150,"einheit":"g","name":"Blumenkohl","hinweis":"kleine Röschen"},{"menge":100,"einheit":"g","name":"Erbsen","hinweis":"tiefgekühlt"},{"menge":150,"einheit":"g","name":"Paneer","hinweis":"in 1,5 cm Würfeln, kurz angebraten"},{"menge":2,"einheit":"EL","name":"Rosinen","hinweis":""},{"menge":2,"einheit":"EL","name":"Mandelblättchen","hinweis":"geröstet"},{"menge":100,"einheit":"g","name":"frische Ananasstücke","hinweis":"optional, kurz vor Schluss; Dose als Ersatz abgetropft"}]},{"gruppe":"Nusspaste","liste":[{"menge":50,"einheit":"g","name":"Cashewkerne","hinweis":"30 Minuten in heißem Wasser eingeweicht"},{"menge":20,"einheit":"g","name":"Mandeln, blanchiert","hinweis":"eingeweicht"},{"menge":1,"einheit":"EL","name":"Mohnsamen (weiß, optional)","hinweis":"ersatzweise Kokosraspeln"}]},{"gruppe":"Sauce","liste":[{"menge":3,"einheit":"EL","name":"Ghee","hinweis":""},{"menge":4,"einheit":"Stück","name":"grüne Kardamomkapseln","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zimtstange, 3 cm","hinweis":""},{"menge":4,"einheit":"Stück","name":"Gewürznelken","hinweis":""},{"menge":1,"einheit":"Stück","name":"Lorbeerblatt","hinweis":""},{"menge":2,"einheit":"Stück","name":"Zwiebeln","hinweis":"in feinen Halbringen, gekocht und püriert"},{"menge":1,"einheit":"EL","name":"Ingwer-Knoblauch-Paste","hinweis":""},{"menge":100,"einheit":"g","name":"Vollmilchjoghurt","hinweis":"zimmerwarm, glatt gerührt"},{"menge":1,"einheit":"TL","name":"gemahlener Koriander","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":1,"einheit":"TL","name":"Kashmiri-Chilipulver","hinweis":"für Farbe, sparsam"},{"menge":1,"einheit":"Prise","name":"Safranfäden","hinweis":"in 3 EL warmer Milch eingeweicht"},{"menge":100,"einheit":"ml","name":"Sahne","hinweis":""},{"menge":1,"einheit":"TL","name":"Garam Masala","hinweis":"frisch gemahlen"},{"menge":1,"einheit":"TL","name":"Zucker","hinweis":""},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]}],"ausruestung":["Weiter Schmortopf mit Deckel","Mixer","Feines Sieb","Pfanne für Paneer und Mandeln"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide alle Gemüse in möglichst gleich große Stücke von etwa 1 bis 2 cm, damit sie gleichzeitig gar werden, und halte sie nach Garzeit getrennt: Kartoffeln und Möhren zuerst, Bohnen und Blumenkohl danach, Erbsen zuletzt. Weiche Cashews und Mandeln für die Nusspaste 30 Minuten in heißem Wasser ein, damit sie sich fein pürieren lassen. Weiche den Safran in warmer Milch ein; die Milch färbt sich nach etwa 10 Minuten goldgelb. Schneide den Paneer in Würfel und die Zwiebeln in feine Halbringe.","dauer":30,"tipp":"Je gleichmäßiger das Gemüse geschnitten ist, desto schöner sieht das fertige Gericht aus."},{"titel":"Gemüse vorgaren","aktion":"blanchieren","text":"Koche Kartoffeln und Möhren in Salzwasser 6 Minuten, gib Bohnen und Blumenkohl dazu und koche weitere 3 Minuten, zum Schluss die Erbsen für 1 Minute. Das Gemüse soll bissfest sein, denn es gart später in der Sauce noch nach. Gieße es ab und schrecke es kurz in Eiswasser ab, damit die Farben leuchtend bleiben. Hebe 100 ml Kochwasser auf, es wird später als milde Brühe für die Sauce verwendet.","dauer":12,"tipp":"Wer das Abschrecken weglässt, bekommt matschiges, graugrünes Gemüse."},{"titel":"Zwiebelpüree herstellen","aktion":"kochen","text":"Koche die Zwiebelringe in 150 ml Wasser mit den Kardamomkapseln und der Zimtstange 10 Minuten, bis sie ganz weich sind und das Wasser fast verdampft ist. Nimm Zimt und Kardamom heraus und püriere die Zwiebeln glatt. Diese gekochten, nicht gebratenen Zwiebeln geben der Sauce ihre helle Farbe und milde Süße, ohne die Bräunung eines Currys. Gib sie zur Seite.","dauer":12,"tipp":"Gebratene Zwiebeln würden die helle Farbe zerstören – Korma bleibt hell."},{"titel":"Nusspaste mahlen","aktion":"puerieren","text":"Gib Cashews, Mandeln und Mohn mit 100 ml frischem Wasser in einen Mixer und püriere sie zwei bis drei Minuten, bis eine seidige, glatte Creme entsteht, in der keine Nussstückchen mehr zu spüren sind. Streiche sie durch ein feines Sieb, falls sie körnig bleibt. Diese Paste bindet die Sauce und gibt ihr Fülle, ohne dass Mehl nötig ist. Sie schmeckt süßlich-nussig und sollte keine rohe Bitterkeit haben.","dauer":5,"tipp":"Je länger die Nüsse einweichen, desto glatter wird die Paste."},{"titel":"Ganze Gewürze tempern","aktion":"braten","text":"Erhitze Ghee in einem weiten Topf bei mittlerer Hitze. Gib Kardamom, Zimt, Nelken und Lorbeer hinein und warte etwa 20 bis 30 Sekunden, bis die Nelken aufquellen, der Kardamom leicht aufplatzt und es süßlich und würzig duftet. Das heiße Fett löst die Aromen. Gib Ingwer-Knoblauch-Paste dazu und rühre eine Minute, bis der rohe Geruch verfliegt. Wenn etwas dunkelbraun wird, nimm den Topf kurz vom Herd.","dauer":3,"tipp":"Ghee darf nicht rauchen; riecht es verbrannt, beginne neu."},{"titel":"Sauce aufbauen","aktion":"koecheln","text":"Gib das Zwiebelpüree und die Gewürzpulver (Koriander, Kurkuma, Chilipulver) in den Topf und brate 2 Minuten. Nimm den Topf vom Herd, rühre den Joghurt esslöffelweise ein, damit er nicht gerinnt, und stelle ihn wieder auf kleine Hitze. Gib die Nusspaste dazu und rühre, bis eine glatte Sauce entsteht. Gieße das aufbewahrte Kochwasser dazu und lasse alles 5 Minuten bei kleiner Hitze ziehen. Die Sauce soll dickflüssig wie flüssiger Rahm sein.","dauer":10,"tipp":"Zimmerwarmer Joghurt gerinnt weniger leicht."},{"titel":"Gemüse und Paneer zugeben","aktion":"schmoren","text":"Brate die Paneerwürfel kurz in etwas Ghee goldgelb an und gib sie mit dem vorgegarten Gemüse und den Rosinen in die Sauce. Rühre vorsichtig um, decke den Topf ab und lasse alles 8 bis 10 Minuten bei kleiner Hitze ziehen. Das Gemüse nimmt die Sauce auf und gart fertig, der Paneer wird weich. Rühre nur wenig, damit nichts zerfällt. Die Sauce soll das Gemüse dünn umhüllen.","dauer":10,"tipp":"Paneer nie lange kochen, sonst wird er fest."},{"titel":"Sahne, Safran und Gewürze","aktion":"abschmecken","text":"Rühre Sahne, Safranmilch, Zucker und Garam Masala ein. Erwärme es 2 bis 3 Minuten ohne Kochen. Schmecke mit Salz ab. Die Sauce soll mild, cremig, leicht süßlich und von Safran und Kardamom duftend sein. Gib die Ananasstücke zum Schluss dazu, sie bringen fruchtige Säure. Wenn die Sauce zu dick ist, gib ein paar Esslöffel heißes Wasser dazu.","dauer":5,"tipp":"Safran wirkt am besten, wenn er in warmer Milch ausgezogen wurde."},{"titel":"Anrichten","aktion":"garnieren","text":"Fülle das Navratan Korma in eine vorgewärmte Schüssel, streue geröstete Mandelblättchen, ein paar Safranfäden und frischen Koriander darüber. Serviere es mit Naan, Pulao oder Jeera-Reis. Reiche dazu Raita und einen frischen Salat. Das Gericht ist mild und eignet sich auch für Gäste, die keine Schärfe mögen.","dauer":0,"tipp":"Geröstete Mandeln erst kurz vor dem Servieren aufstreuen, damit sie knusprig bleiben."}],"profitipps":["Zwiebeln kochen statt braten, dann bleibt die Sauce hell.","Joghurt zimmerwarm und langsam einrühren, damit er nicht gerinnt.","Gemüse bissfest vorgaren und abschrecken.","Nusspaste fein pürieren und notfalls sieben.","Safran in warmer Milch einweichen."],"varianten":["Shahi Korma mit Hähnchen oder Lamm.","Vegane Version mit Kokosmilch und Cashewcreme.","Mit Äpfeln und Ananas für einen fruchtigen Charakter.","Schärfere Variante mit grünen Chilis."],"beilagen":["Naan oder Roti","Pulao oder Jeera-Reis","Raita","Salat"],"getraenk":"Lassi, Chai oder ein milder Weißwein wie Gewürztraminer.","koeche":[],"quellen":[{"titel":"Navratan korma (Korma) – Wikipedia","url":"https://en.wikipedia.org/wiki/Navratan_korma"},{"titel":"Malai kofta – Wikipedia","url":"https://en.wikipedia.org/wiki/Malai_kofta"}],"bild":"curry","farben":["#e5b45a","#f3d9a0","#7a8a3a"],"schlagworte":["Mughlai","Festessen","Korma","Vegetarisch"],"vegetarisch_moeglich":true},{"id":"indien-shorshe-maach","name":"Shorshe Maach – Bengalischer Fisch in Senfsauce","originalname":"সর্ষে মাছ","kueche":"indien","region":"Bengalen","beliebtheit":74,"hauptkategorie":"fisch","fischsorte":"fisch","gang":"hauptgericht","kurz":"Zarte Fischstücke in einer scharf-nussigen Sauce aus frisch gemahlenem Senf, Senföl und grünen Chilis. Das Herzstück bengalischer Fischküche – und ein Gericht, das nach Senf riecht, aber überraschend mild schmeckt.","hintergrund":"Bengalen ist das Land des Fisches, und Senf ist sein bester Freund. Shorshe Maach (Senf-Fisch) wird traditionell mit Hilsa (Ilish), dem Nationalfisch Bangladeschs, zubereitet, aber auch mit Rohu, Katla oder Bekti. Die Sauce besteht aus einer Paste von gelben oder schwarzen Senfkörnern, die mit grünen Chilis, Salz und Wasser gemahlen werden, dazu Senföl, das hier nicht nur Fett, sondern wichtigster Aromaträger ist. Wird die Senfpaste zu lange gemahlen oder gekocht, schmeckt sie bitter; deshalb verwenden Bengalen kaltes Wasser, mahlen nur kurz und garen die Sauce nur wenige Minuten. Gegessen wird mit warmem Reis.","portionen":4,"zeit":{"vorbereitung":25,"garen":20,"ruhen":15},"schwierigkeit":2,"zutaten":[{"gruppe":"Fisch","liste":[{"menge":700,"einheit":"g","name":"Süßwasserfisch in Steaks oder dicken Stücken (Karpfen, Wels, Forelle, Zander oder Hilsa)","hinweis":"mit Gräte lässt sich Fisch besser braten; Fischtheke bitten, in 4 cm dicke Steaks zu schneiden"},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Senfpaste","liste":[{"menge":1.5,"einheit":"EL","name":"gelbe Senfsamen","hinweis":"für mildere Schärfe; Ersatz: 1 EL gelb + 1 EL braun"},{"menge":1,"einheit":"EL","name":"braune oder schwarze Senfsamen","hinweis":"für mehr Schärfe, optional"},{"menge":2,"einheit":"Stück","name":"grüne Chilis","hinweis":""},{"menge":0.25,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":150,"einheit":"ml","name":"kaltes Wasser","hinweis":"kaltes Wasser verhindert Bitterkeit"}]},{"gruppe":"Zum Braten und Kochen","liste":[{"menge":4,"einheit":"EL","name":"Senföl","hinweis":"kalt gepresst, Asia-Laden; muss vor Gebrauch erhitzt werden"},{"menge":0.5,"einheit":"TL","name":"Nigella-Samen (Kalonji)","hinweis":"optional, für das bengalische Aroma"},{"menge":2,"einheit":"Stück","name":"grüne Chilis, längs eingeschnitten","hinweis":""},{"menge":1,"einheit":"Handvoll","name":"Koriander","hinweis":""}]}],"ausruestung":["Mörser oder leistungsstarker Mixer","schwere Pfanne","Pfannenwender"],"schritte":[{"titel":"Fisch vorbereiten","aktion":"vorbereiten","text":"Spüle die Fischstücke kalt ab und tupfe sie trocken. Prüfe bei einem frischen Fisch Augen, Kiemen und Geruch (klare Augen, rote Kiemen, kein strenger Geruch). Reibe die Stücke mit Salz und Kurkuma ein und lasse sie 10 Minuten stehen. Das Salz festigt das Fleisch, sodass es beim Braten und späteren Garen in der Sauce nicht zerfällt.","dauer":10,"tipp":""},{"titel":"Senf einweichen","aktion":"marinieren","text":"Weiche die Senfsamen in 100 ml kaltem Wasser 15 Minuten ein. Dadurch quellen sie auf und lassen sich leichter zu einer glatten Paste mahlen, und die enthaltenen Enzyme entfalten ihre Schärfe. Verwende wirklich kaltes Wasser: Heißes Wasser macht den Senf bitter. In dieser Zeit lässt sich der Fisch in Ruhe vorbereiten, und die Samen verlieren etwas von ihrer Härte.","dauer":15,"tipp":""},{"titel":"Senfpaste mahlen","aktion":"puerieren","text":"Püriere die eingeweichten Senfsamen mit grünen Chilis, Salz und Kurkuma in einem Mixer oder Mörser nur 30 bis 40 Sekunden zu einer feinen Paste. Je länger du mahlst, desto bitterer wird sie, weil der Mixer Wärme erzeugt. Fülle sofort mit dem restlichen kalten Wasser auf, rühre und stelle die Mischung beiseite. Sie sollte gelblich, leicht körnig und scharf-säuerlich riechen.","dauer":1,"tipp":"Mixbecher vorher kühlen und nur im Intervall mixen."},{"titel":"Senföl erhitzen","aktion":"vorbereiten","text":"Erhitze das Senföl in einer schweren Pfanne bei mittlerer bis hoher Hitze, bis es leicht raucht und der scharfe Geruch weicht. Reduziere die Hitze dann auf mittlere Stufe. Kalt gepresstes Senföl ist roh sehr scharf und sticht in der Nase; erst wenn es erhitzt wurde, schmeckt es nussig und mild. Stelle die Dunstabzugshaube an.","dauer":2,"tipp":""},{"titel":"Fisch anbraten","aktion":"braten","text":"Brate die Fischstücke im heißen Senföl auf jeder Seite 1 bis 2 Minuten, bis die Haut leicht goldfarben ist und eine dünne Kruste hat. Der Fisch soll noch nicht durchgegart sein. Nimm ihn mit der Fischzange heraus und lege ihn auf einen Teller. Das Anbraten festigt die Stücke und gibt Röstaromen. Das Senföl nimmt dabei Fischaroma auf und wird später zur Basis der Sauce, deshalb bleibt es in der Pfanne.","dauer":4,"tipp":"Fischstücke nur einmal wenden, sie reißen sonst."},{"titel":"Gewürze und Senfpaste ins Öl geben","aktion":"braten","text":"Gib im gleichen Öl die Nigella-Samen hinein und lasse sie 10 Sekunden knistern. Gieße dann die Senfpaste dazu, rühre sie 1 bis 2 Minuten bei mittlerer Hitze, bis sie leicht blubbert und das Aroma sich ändert: Der rohe, scharfe Duft wird nussig-warm. Koche sie nicht länger, denn zu langes Kochen macht sie bitter.","dauer":2,"tipp":""},{"titel":"Fisch in der Sauce garen","aktion":"koecheln","text":"Lege die Fischstücke zurück in die Sauce, gib die längs eingeschnittenen Chilis dazu, decke die Pfanne zu und lasse alles bei kleiner Hitze 6 bis 8 Minuten sanft ziehen. Bewege den Fisch nur durch Schwenken der Pfanne. Er ist gar, wenn das Fleisch an der Gräte milchig-weiß ist und sich leicht lösen lässt, die Kerntemperatur beträgt 60 bis 63 °C.","dauer":8,"tipp":"Die Sauce soll nur schwach köcheln; heftiges Kochen macht sie bitter und den Fisch trocken."},{"titel":"Abschmecken und servieren","aktion":"abschmecken","text":"Schmecke mit Salz ab und gib einen Teelöffel rohes Senföl über das fertige Gericht, wenn du es besonders authentisch magst. Streue Koriander darüber und serviere das Gericht sofort mit warmem weißem Reis. Die Sauce soll leicht scharf, nussig und mild-bitter schmecken; ein winziges Bitternis ist erwünscht, aber nicht unangenehm.","dauer":0,"tipp":""}],"profitipps":["Senf nur kurz mahlen und mit kaltem Wasser, sonst wird die Sauce bitter.","Senföl vor Gebrauch erhitzen, bis es mild riecht.","Fisch mit Gräte verwenden: Das Fleisch bleibt saftiger und die Sauce wird aromatischer.","Nach dem Hinzufügen der Senfpaste nur kurz kochen.","Die Menge Senfpaste an die Schärfe anpassen; gelbe Samen sind milder als braune."],"varianten":["Ilish Bhapa: Hilsa mit Senf im Dampf gegart, in Bananenblatt","Shorshe Chingri: mit Garnelen statt Fisch","Mit Kokosraspel in der Senfpaste für mildere Sauce","Mit Auberginen oder Kartoffeln als Einlage"],"beilagen":["warmer Reis","Dal","Gebratene Aubergine"],"getraenk":"Gut gekühlter Weißwein (Riesling) oder indisches Bier","koeche":[],"quellen":[{"titel":"Archana's Kitchen – Shorshe Maach (Bengali Mustard Fish Curry)","url":"https://www.archanaskitchen.com/recipe/shorshe-maach-recipe-bengali-style-mustard-fish-curry"},{"titel":"Easy Cooking with Molly – Authentic Bengali Mustard Fish","url":"https://www.easycookingwithmolly.com/?p=1141"},{"titel":"Archana's Kitchen – Doi Shorshe Chingri (Prawn in Mustard Curry)","url":"https://www.archanaskitchen.com/doi-shorshe-chingri-bengali-prawn-in-mustard-curry-recipe"}],"bild":"curry","farben":["#d9b83a","#f1e6a8","#6b8a2b"],"schlagworte":["Bengalen","Senf","Süßwasserfisch","Hilsa"],"vegetarisch_moeglich":false},{"id":"indien-kheer","name":"Kheer","originalname":"Payasam / Payesh","kueche":"indien","region":"Nordindien (landesweit, im Süden Payasam)","beliebtheit":74,"hauptkategorie":"suess","fleischsorte":"","gang":"dessert","kurz":"Basmatireis, geduldig in Milch eingekocht, mit Kardamom, Safran und Pistazien – der cremige Reispudding für Feste und Tempel.","hintergrund":"Kheer (von Sanskrit kshira, Milch) ist ein Reispudding, der in Indien schon in alter Zeit bekannt war und als Opfergabe in Hindu-Tempeln eine zentrale Rolle spielt. Im Süden heißt er Payasam, in Bengalen Payesh. Reis, Milch und Zucker oder Jaggery werden lange gekocht und mit Kardamom, Safran und Nüssen aromatisiert. Statt Reis nimmt man in anderen Varianten Vermicelli, Sago oder Weizengrieß. Kheer isst man warm oder kalt, bei Hochzeiten, an Geburtstagen und an Festtagen wie Diwali.","portionen":6,"zeit":{"vorbereitung":15,"garen":75,"ruhen":120},"schwierigkeit":1,"zutaten":[{"gruppe":"Kheer","liste":[{"menge":1.5,"einheit":"l","name":"Vollmilch","hinweis":"3,5 % Fett; keine ultrahocherhitzte Milch mit Stabilisatoren, wenn möglich"},{"menge":60,"einheit":"g","name":"Basmatireis","hinweis":"gewaschen und 30 Minuten eingeweicht"},{"menge":1,"einheit":"TL","name":"Ghee","hinweis":"zum Anrösten des Reises"},{"menge":100,"einheit":"g","name":"Zucker","hinweis":"nach Geschmack; oder Jaggery"},{"menge":5,"einheit":"Stück","name":"grüne Kardamomkapseln","hinweis":"Samen gemahlen"},{"menge":1,"einheit":"Prise","name":"Safranfäden","hinweis":"in 2 EL warmer Milch eingeweicht"},{"menge":1,"einheit":"EL","name":"Rosinen","hinweis":""},{"menge":2,"einheit":"EL","name":"Mandeln","hinweis":"blanchiert, in Scheiben"},{"menge":2,"einheit":"EL","name":"Pistazien","hinweis":"gehackt, zum Garnieren"},{"menge":1,"einheit":"TL","name":"Rosenwasser","hinweis":"optional"}]}],"ausruestung":["Schwerer, breiter Topf mit dickem Boden","Holzlöffel","Mörser"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wasche den Basmatireis in mehreren Wassern, bis das Wasser klar ist, und weiche ihn 30 Minuten in kaltem Wasser ein. Gieße ihn gut ab und lasse ihn auf einem Sieb abtropfen. Zerstoße die Kardamomkapseln im Mörser, entferne die Hülsen und mahle die Samen fein. Löse die Safranfäden in warmer Milch auf; nach 10 Minuten färbt sich die Milch tiefgelb. Schneide die Mandeln in dünne Scheiben und hacke die Pistazien. Ein schwerer Topf ist wichtig, damit die Milch nicht anbrennt.","dauer":30,"tipp":"Spüle den Topf vor dem Kochen mit kaltem Wasser aus – so brennt die Milch weniger an."},{"titel":"Reis anrösten","aktion":"braten","text":"Erhitze das Ghee im Topf bei mittlerer Hitze und gib den abgetropften Reis hinein. Brate ihn 1 bis 2 Minuten unter Rühren, bis er duftet und die Körner leicht durchscheinend wirken. Dieses kurze Anrösten gibt eine nussige Note und lässt den Reis später schön weich zerfallen. Er soll keine Farbe annehmen. Wenn er braun wird, wird der Kheer bitter.","dauer":3,"tipp":"Ein paar Reiskörner im Mörser leicht zerdrücken, sie geben später mehr Cremigkeit."},{"titel":"Milch aufkochen","aktion":"kochen","text":"Gieße die Milch zum Reis und bringe sie unter häufigem Rühren zum Kochen. Reduziere sofort die Hitze, sobald sie aufsteigt. Lasse sie bei mittlerer bis kleiner Hitze sanft köcheln, rühre alle paar Minuten und kratze den Boden ab, damit sich keine Haut und nichts Angebranntes bildet. Du brauchst Geduld: Die Milch soll langsam einkochen, nicht sprudeln. Die entstehende Haut rührst du immer wieder unter, sie gibt Cremigkeit.","dauer":40,"tipp":"Ein Stück Topfdeckel schräg aufgelegt hält die Hitze, ohne dass es überkocht."},{"titel":"Einkochen bis cremig","aktion":"reduzieren","text":"Koche weitere 30 bis 40 Minuten bei kleiner Hitze, bis die Milch auf etwa zwei Drittel eingekocht ist und die Reiskörner ganz weich, fast zerfallen sind. Die Farbe wechselt von weiß zu leicht cremig. Die Masse soll dickflüssig sein, aber noch vom Löffel fließen; sie wird beim Abkühlen noch dicker. Rühre häufig und wische die Topfwand ab. Dieser langsame Prozess lässt den Zucker und die Milchsüße konzentrieren.","dauer":35,"tipp":"Ist der Kheer nach dem Abkühlen zu fest, gib einen Schuss warme Milch dazu."},{"titel":"Süßen und aromatisieren","aktion":"abschmecken","text":"Rühre Zucker, Kardamom, Rosinen und Safranmilch ein und koche noch 5 bis 8 Minuten, bis sich der Zucker gelöst hat und die Mischung noch einmal etwas eindickt. Süße erst jetzt: Zucker früh zugegeben verzögert das Weichwerden des Reises und lässt die Milch leichter anbrennen. Gib Rosenwasser dazu, falls du es magst. Schmecke ab: Der Kheer soll süß, milchig, blumig und leicht nach Safran duften.","dauer":8,"tipp":"Zucker immer erst zum Schluss, sonst bleibt der Reis hart."},{"titel":"Abkühlen lassen und servieren","aktion":"kuehlen","text":"Nimm den Topf vom Herd und lasse den Kheer 20 Minuten abkühlen, rühre gelegentlich, damit sich keine Haut bildet. Fülle ihn in Schalen und garniere mit Mandelscheiben und Pistazien. Du kannst ihn warm, zimmerwarm oder gekühlt servieren; im Kühlschrank wird er fester und die Aromen verbinden sich. Wenn er sehr dick ist, rühre vor dem Servieren einen Schuss kalte Milch ein. Er hält sich im Kühlschrank 3 Tage.","dauer":90,"tipp":"Ein paar Safranfäden obenauf machen ihn festlich."}],"profitipps":["Schwerer Topf und häufiges Rühren verhindern Anbrennen.","Reis kurz anrösten für nussiges Aroma.","Zucker erst am Ende zugeben.","Geduld: langsames Einkochen gibt Cremigkeit.","Kheer wird beim Abkühlen dicker."],"varianten":["Payasam mit Jaggery und Kokosmilch aus Südindien.","Semiya Kheer mit gerösteten Vermicelli.","Sabudana Kheer mit Sago.","Gur ki Kheer mit Jaggery im Winter."],"beilagen":["Pistazien und Mandeln","Frische Früchte","Gulab Jamun","Chai"],"getraenk":"Masala Chai oder ein Dessertwein.","koeche":[],"quellen":[{"titel":"Kheer – Wikipedia","url":"https://en.wikipedia.org/wiki/Kheer"},{"titel":"Khoya (Milch einkochen) – Wikipedia","url":"https://en.wikipedia.org/wiki/Khoya"}],"bild":"dessert","farben":["#f3e3b8","#e2b94a","#7a5a2a"],"schlagworte":["Reispudding","Festtag","Milchspeise","Kardamom"],"vegetarisch_moeglich":true},{"id":"indien-raita","name":"Gurken-Raita","originalname":"Kakdi Raita","kueche":"indien","region":"Nordindien (landesweit)","beliebtheit":72,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"beilage","kurz":"Kühler, cremiger Joghurt mit Gurke, geröstetem Kreuzkümmel und Minze – der Löscher für jedes scharfe Curry.","hintergrund":"Raita ist ein Joghurt-Dip und eine Beilage, die in Indien zu fast jeder Mahlzeit gehört, vor allem zu Biryani, Pulao und scharfen Currys. Der Name stammt aus dem Hindi und taucht in gedruckter Form im 19. Jahrhundert auf; er wird auf Sanskrit-Wörter für Senfsamen und Schärfe zurückgeführt. Es gibt Gurken-, Zwiebel-, Boondi- und Obst-Raita sowie südindische Varianten wie Pachadi, die mit Kokos, Senfsamen und Curryblättern temperiert werden. Kreuzkümmel wird trocken geröstet und über den Joghurt gestreut.","portionen":4,"zeit":{"vorbereitung":15,"garen":5,"ruhen":30},"schwierigkeit":1,"zutaten":[{"gruppe":"Raita","liste":[{"menge":400,"einheit":"g","name":"Vollmilchjoghurt","hinweis":"3,5 % Fett; kein Magerjoghurt, der wird wässrig"},{"menge":1,"einheit":"Stück","name":"Salatgurke","hinweis":"oder 2 kleine; fest und aromatisch"},{"menge":1,"einheit":"TL","name":"Kreuzkümmelsamen","hinweis":"trocken geröstet und frisch gemahlen"},{"menge":0.5,"einheit":"TL","name":"Kala Namak (Schwarzsalz)","hinweis":"optional; gibt typischen Chaat-Geschmack"},{"menge":1,"einheit":"EL","name":"frische Minze","hinweis":"fein gehackt"},{"menge":1,"einheit":"EL","name":"frischer Koriander","hinweis":"fein gehackt"},{"menge":1,"einheit":"Stück","name":"grüne Chilischote","hinweis":"optional, fein gehackt"},{"menge":0.5,"einheit":"TL","name":"Kashmiri-Chilipulver","hinweis":"zum Bestreuen"},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]},{"gruppe":"Optionaler Tadka (Südindien)","liste":[{"menge":1,"einheit":"EL","name":"Kokosöl oder Öl","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Senfsamen","hinweis":""},{"menge":6,"einheit":"Stück","name":"Curryblätter","hinweis":""}]}],"ausruestung":["Reibe oder Messer","Küchentuch","Schüssel","Kleine Pfanne zum Rösten"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wähle einen festen Joghurt mit voller Fettstufe; er gibt cremige Konsistenz und läuft nicht so schnell aus. Kühle ihn gut. Wasche die Gurke, schneide die Enden ab und reibe sie grob auf einer Haushaltsreibe oder schneide sie in feine Würfel von 5 mm. Hacke Minze, Koriander und Chili fein. Stelle Kreuzkümmel und Gewürze bereit. Alles sollte kühl sein, denn Raita lebt von seiner Frische.","dauer":0,"tipp":"Wer Gurke mit Schale verwendet, braucht Bio-Gurken oder muss sie gründlich waschen."},{"titel":"Gurke entwässern","aktion":"vorbereiten","text":"Gib die Gurke in ein Sieb, bestreue sie mit einer Prise Salz und lasse sie 10 bis 15 Minuten Wasser ziehen. Drücke sie dann mit den Händen oder in einem sauberen Küchentuch kräftig aus. Dieses Entwässern verhindert, dass die Raita nach einer halben Stunde wässrig wird und der Joghurt sich verdünnt. Du sollst eine trockene, knackige Gurkenmasse haben. Das ausgedrückte Gurkenwasser kannst du trinken oder wegschütten.","dauer":15,"tipp":"Je trockener die Gurke, desto cremiger bleibt die Raita."},{"titel":"Kreuzkümmel rösten","aktion":"braten","text":"Erhitze eine trockene Pfanne bei mittlerer Hitze und gib den Kreuzkümmel hinein. Schwenke ihn 30 bis 45 Sekunden, bis er einen warmen, nussigen Duft verströmt und leicht dunkler wird. Nimm ihn sofort heraus und zerstoße ihn im Mörser grob. Das Rösten entwickelt Röstaromen und nimmt die Rohheit; zu lange geröstet wird er bitter und beißend. Verwende frisch gerösteten Kreuzkümmel, denn er riecht deutlich intensiver als fertiges Pulver.","dauer":2,"tipp":"Der Duft ist dein Timer: Sobald er stark nach Kreuzkümmel riecht, ist er fertig."},{"titel":"Joghurt glatt rühren","aktion":"mischen","text":"Gib den Joghurt in eine Schüssel und rühre ihn mit einer Gabel oder einem Schneebesen 1 Minute glatt, bis keine Klumpen mehr sichtbar sind und er leicht cremig-flüssig wirkt. Kalter Joghurt aus dem Kühlschrank ist oft fest und braucht kräftiges Rühren. Wenn er sehr dick ist, rühre einen Esslöffel Milch oder Wasser ein. Er soll beim Anheben des Löffels langsam fließen.","dauer":2,"tipp":"Nicht zu lange rühren, sonst wird der Joghurt dünn."},{"titel":"Alles vermischen","aktion":"mischen","text":"Gib die ausgedrückte Gurke, Salz, Schwarzsalz, die Hälfte des Kreuzkümmels, Minze, Koriander und Chili zum Joghurt und rühre alles vorsichtig unter. Schmecke ab: Die Raita soll frisch, leicht salzig und aromatisch schmecken, mit einer kaum spürbaren Schärfe. Wenn sie flach schmeckt, hilft eine Prise Salz oder etwas mehr Kreuzkümmel. Rühre nicht zu viel, damit die Gurkenstücke ganz bleiben.","dauer":2,"tipp":"Das Salz zieht noch Flüssigkeit aus der Gurke – schmecke deshalb zurückhaltend ab und später nach."},{"titel":"Optional: Tadka für die südindische Variante","aktion":"braten","text":"Erhitze Kokosöl in einer kleinen Pfanne bei mittlerer Hitze. Gib die Senfsamen hinein und warte 20 bis 30 Sekunden, bis sie knackend aufspringen. Füge Curryblätter hinzu, rühre 5 Sekunden, bis sie knistern, und gieße das Fett sofort über die Raita. Es zischt und duftet nach Nuss und Zitrus. Rühre kurz um. Dieser Tadka gibt einen warmen, würzigen Kontrast zur kühlen Raita.","dauer":2,"tipp":"Nur machen, wenn du die südindische Variante magst – die nordindische bleibt schlicht."},{"titel":"Kühlen und Anrichten","aktion":"kuehlen","text":"Stelle die Raita 20 bis 30 Minuten in den Kühlschrank, damit sich die Aromen verbinden und sie schön kalt ist. Fülle sie in eine Schale, streue den restlichen Kreuzkümmel und etwas Chilipulver darüber und garniere mit einem Zweig Minze. Serviere sie als Beilage zu Biryani, Tandoori oder scharfen Currys. Gut gekühlt ist sie am besten; innerhalb von 6 Stunden essen, danach wird sie wässrig.","dauer":30,"tipp":"Kurz vor dem Servieren noch einmal umrühren und mit Kreuzkümmel bestäuben."}],"profitipps":["Gurke salzen und ausdrücken, damit die Raita nicht wässrig wird.","Vollfetten Joghurt nehmen.","Kreuzkümmel frisch rösten und mahlen.","Gut kühlen, bevor sie auf den Tisch kommt.","Schwarzsalz gibt den typischen Chaat-Geschmack."],"varianten":["Boondi Raita mit knusprigen Kichererbsenperlen.","Zwiebel-Tomaten-Raita.","Obst-Raita mit Ananas oder Granatapfel.","Südindische Pachadi mit Kokos und Senfsamen."],"beilagen":["Biryani","Tandoori Chicken","Paratha","Scharfe Currys"],"getraenk":"Passt zu allem; selbst ein Lassi.","koeche":[],"quellen":[{"titel":"Raita – Wikipedia","url":"https://en.wikipedia.org/wiki/Raita"},{"titel":"The Crackling Spices Of Indian Tempering – NPR","url":"https://www.npr.org/2011/12/07/143251451/the-crackling-spices-of-indian-tempering"}],"bild":"dip","farben":["#e8eed0","#9ab858","#f6f2e0"],"schlagworte":["Beilage","Joghurt","Erfrischend","Vegetarisch"],"vegetarisch_moeglich":true},{"id":"indien-kati-roll-kolkata","name":"Kati Roll – Hähnchen-Wrap aus Kolkata","originalname":"কাটি রোল (Kathi roll)","kueche":"indien","region":"Kolkata, Westbengalen","beliebtheit":72,"hauptkategorie":"fleisch","fleischsorte":"huhn","gang":"snack","themen":["streetfood"],"kurz":"Marinierte Hähnchenstücke, gebraten im Ei-Paratha, mit scharfem Zwiebelsalat, Chutney und Zitrone gerollt. Der Wrap, der in Kolkata erfunden wurde.","hintergrund":"Kati Rolls wurden in Kolkata geboren: Als Erfinder gilt das Nizam-Restaurant in Kolkata, das in den 1930er Jahren Spießfleisch (Kebab) in Paratha wickelte, damit Gäste es bequem im Gehen essen konnten. Der Name kommt vom Bambusspieß (Kati), auf dem das Fleisch gegart wurde. Heute wird das Fleisch meist in der Pfanne gebraten und der Paratha vorher mit einer Schicht Ei bestrichen, was ihn saftiger und weicher macht. Mit Chutney, Zwiebeln und Limette ist der Kati Roll ein komplettes Gericht für die Hand.","portionen":4,"zeit":{"vorbereitung":45,"garen":35,"ruhen":150},"schwierigkeit":2,"zutaten":[{"gruppe":"Marinade und Hähnchen","liste":[{"menge":600,"einheit":"g","name":"Hähnchenschenkelfilet (ohne Knochen)","hinweis":"in 2 cm große Streifen oder Würfel geschnitten"},{"menge":150,"einheit":"g","name":"Naturjoghurt","hinweis":""},{"menge":1,"einheit":"EL","name":"Ingwer-Knoblauch-Paste","hinweis":"oder je 1 TL frisch gerieben"},{"menge":1,"einheit":"TL","name":"Garam Masala","hinweis":""},{"menge":1,"einheit":"TL","name":"Kashmiri-Chilipulver","hinweis":"oder mildes Paprikapulver plus Cayenne"},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":1,"einheit":"EL","name":"Zitronensaft","hinweis":""},{"menge":2,"einheit":"EL","name":"Senföl oder neutrales Öl","hinweis":"plus Öl zum Braten"},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]},{"gruppe":"Paratha (4 Stück)","liste":[{"menge":300,"einheit":"g","name":"Weizenmehl Type 550","hinweis":"oder halb Weizenvollkornmehl"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":2,"einheit":"EL","name":"Öl","hinweis":""},{"menge":170,"einheit":"ml","name":"lauwarmes Wasser","hinweis":""},{"menge":4,"einheit":"Stück","name":"Eier","hinweis":"verquirlt, je ein Ei pro Paratha"},{"menge":4,"einheit":"EL","name":"Ghee oder Butter","hinweis":"zum Ausbacken"}]},{"gruppe":"Füllung und Chutney","liste":[{"menge":1,"einheit":"Stück","name":"rote Zwiebel","hinweis":"in feine Ringe geschnitten"},{"menge":1,"einheit":"Stück","name":"Limette","hinweis":"Saft"},{"menge":1,"einheit":"TL","name":"Chaat Masala","hinweis":"im Asialaden"},{"menge":1,"einheit":"Stück","name":"grüne Chili","hinweis":"fein gehackt"},{"menge":1,"einheit":"Bund","name":"Koriander","hinweis":"für die Chutney"},{"menge":0.5,"einheit":"Bund","name":"Minze","hinweis":"für die Chutney"}]}],"ausruestung":["Schüssel zum Marinieren","große Pfanne oder Gusseisenpfanne","Nudelholz","Mixer oder Mörser"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege Mehl und Gewürze ab und schneide die Hähnchenschenkelfilets in etwa 2 cm große Streifen, denn so garen sie schnell und bleiben saftig. Schneide die rote Zwiebel in sehr feine Ringe, hacke die grüne Chili und zupfe Koriander und Minze ab. Stelle Eier, Ghee und Öl bereit. Schenkelfilets eignen sich besser als Brust, weil sie beim Braten saftig bleiben und nicht trocken werden.","dauer":0,"tipp":""},{"titel":"Hähnchen marinieren","aktion":"marinieren","text":"Vermische Joghurt, Ingwer-Knoblauch-Paste, Garam Masala, Chili, Kurkuma, Zitronensaft, Senföl und Salz in einer Schüssel zu einer dickflüssigen Marinade. Gib das Fleisch dazu und knete es gründlich durch, damit jedes Stück bedeckt ist. Decke die Schüssel ab und lass das Hähnchen mindestens zwei Stunden, besser über Nacht, im Kühlschrank ziehen. Der Joghurt macht das Fleisch zart, die Säure lässt die Gewürze eindringen und bringt Farbe.","dauer":120,"tipp":"Nimm das Fleisch 20 Minuten vor dem Braten aus dem Kühlschrank."},{"titel":"Paratha-Teig kneten","aktion":"kneten","text":"Vermische Mehl und Salz, gib Öl und Wasser dazu und knete alles acht Minuten zu einem weichen, geschmeidigen Teig. Er soll sich glatt und elastisch anfühlen und nicht an den Händen kleben. Forme ihn zu einer Kugel, bestreiche sie mit etwas Öl und lass sie abgedeckt 30 Minuten ruhen. So wird der Teig dehnbar und lässt sich dünn rollen, ohne zu schrumpfen.","dauer":38,"tipp":""},{"titel":"Chutney und Zwiebelsalat","aktion":"mischen","text":"Püriere Koriander, Minze, grüne Chili, Zitronensaft und eine Prise Salz mit etwas Wasser zu einer glatten, hellgrünen Chutney. Mische die roten Zwiebelringe mit Limettensaft, Chaat Masala und gehackter Chili und lass sie zehn Minuten ziehen, bis sie leicht mariniert und weich werden. Die Säure und Schärfe der beiden Beilagen sind notwendig, um das fettige Fleisch und den Paratha auszugleichen.","dauer":10,"tipp":""},{"titel":"Hähnchen braten","aktion":"braten","text":"Erhitze zwei Esslöffel Öl in einer großen Pfanne bei hoher Hitze, bis es leicht raucht. Brate das Hähnchen in zwei Portionen vier bis fünf Minuten, ohne es zu oft zu wenden, bis es gebräunt ist und an den Rändern leicht karamellisiert. Die Kerntemperatur sollte 75 °C erreichen, das Fleisch ist dann innen nicht mehr rosa und der Saft läuft klar. Nimm es heraus und halte es warm. Überfülle die Pfanne nicht, sonst kocht das Fleisch statt zu braten.","dauer":12,"tipp":""},{"titel":"Paratha ausrollen","aktion":"ausrollen","text":"Teile den Teig in vier Portionen und rolle jede zu einem dünnen Kreis von etwa 22 cm aus. Streiche ein wenig Ghee auf, falte den Teig zu einem Dreieck, streiche erneut Ghee darauf, falte noch einmal und rolle ihn wieder dünn aus. So entstehen die Schichten, die dem Paratha seine Blättrigkeit geben. Er sollte am Ende rund oder quadratisch und etwa 2 mm dick sein.","dauer":8,"tipp":""},{"titel":"Paratha mit Ei backen","aktion":"braten","text":"Erhitze eine Pfanne mit etwas Ghee bei mittlerer bis hoher Hitze und lege den ersten Paratha hinein. Backe ihn eine Minute, wende ihn und gib sofort ein verquirltes Ei auf die gebackene Seite. Verteile es mit dem Löffelrücken und drehe den Paratha nochmals, sodass die Eiseite unten liegt. Backe eine weitere Minute, bis das Ei gestockt und der Teig goldbraun ist. Schiebe den Paratha auf einen Teller und halte ihn warm; wiederhole mit den übrigen.","dauer":12,"tipp":"Der Ei-Überzug macht den Paratha stabil und verhindert, dass er durchweicht."},{"titel":"Füllen und rollen","aktion":"rollen","text":"Lege einen Paratha mit der Eiseite nach unten, streiche etwas grüne Chutney in die Mitte, gib ein Viertel des Hähnchens darauf und verteile Zwiebelsalat und einen Spritzer Limette. Schlage die beiden Seiten ein und rolle den Paratha fest auf, sodass eine Rolle entsteht. Wickle das untere Ende in Backpapier oder Alufolie, damit du den Roll bequem in der Hand halten kannst. Serviere sofort, solange alles heiß ist.","dauer":3,"tipp":""}],"profitipps":["Das Hähnchen am besten über Nacht marinieren – das Fleisch wird zarter und aromatischer.","Das Ei im Paratha ist das Geheimnis eines klassischen Kati Rolls.","Brate das Fleisch bei hoher Hitze in kleinen Portionen für Röstaromen.","Der Zwiebelsalat mit Limette und Chaat Masala sorgt für Frische und Biss.","Fertige Parathas aus dem Asialaden sind eine gute Abkürzung."],"varianten":["Vegetarisch mit Paneer oder gewürzten Kichererbsen.","Mit Lamm- oder Rinderhack (Seekh-Kebab-Stil).","Egg Roll: nur mit Ei, Zwiebeln und Chutney."],"beilagen":["Minz-Joghurt-Raita","Gurkenscheiben","Zitronenspalten"],"getraenk":"Masala Chai, Lassi oder ein indisches Lagerbier","koeche":[{"name":"Nisha Katona","bezug":"Die britische Mowgli-Gründerin hat in ihrem Buch „Meat Free Mowgli“ ein Rezept für vegetarische Kichererbsen-Kati-Rolls veröffentlicht und betont, dass Kati Rolls in Kolkata geboren wurden.","quelle":"https://www.stylist.co.uk/food-drink/meat-free-mowgli-indian-lunch-recipes/730088"}],"quellen":[{"titel":"Stylist: Meat Free Mowgli – Nisha Katonas Rezepte (Kichererbsen-Kati-Rolls)","url":"https://www.stylist.co.uk/food-drink/meat-free-mowgli-indian-lunch-recipes/730088"},{"titel":"Eat Your Books: Mowgli Street Food von Nisha Katona","url":"https://wp.eatyourbooks.com/blog/2018/9/12/mowgli-street-food-by-nisha-katona"}],"bild":"wrap","farben":["#d9a55a","#b04a2a","#7fae4a"],"schlagworte":["Kolkata","Wrap","Paratha","Huhn"],"vegetarisch_moeglich":true},{"id":"indien-kanda-poha","name":"Kanda Poha – Reisflocken mit Zwiebeln und Erdnüssen","originalname":"कांदा पोहे","kueche":"indien","region":"Maharashtra und Madhya Pradesh (Indore)","beliebtheit":70,"hauptkategorie":"vegan","kurz":"Zarte Reisflocken mit Zwiebeln, Kurkuma, Senfsamen, Curryblättern und knusprigen Erdnüssen, mit Zitrone und Koriander frisch abgeschmeckt.","hintergrund":"Poha ist eines der beliebtesten Frühstücksgerichte Indiens, besonders in Maharashtra und Madhya Pradesh. Es wird aus gepressten Reisflocken zubereitet, die nur kurz gewaschen und dann mit Gewürzen gedünstet werden. Die Maharashtra-Variante Kanda Poha enthält Zwiebeln, Erdnüsse und Curryblätter, Indori Poha wird mit Fenchel und Sev (Kichererbsenfäden) serviert. Das Gericht ist in 15 Minuten fertig, leicht und sättigend. Es wird oft mit Chai gegessen und auch Besuchern als schneller Imbiss angeboten.","portionen":4,"zeit":{"vorbereitung":15,"garen":12,"ruhen":10},"schwierigkeit":1,"zutaten":[{"gruppe":"Poha","liste":[{"menge":200,"einheit":"g","name":"dicke Reisflocken (Poha)","hinweis":"im Asialaden; dicke Sorte verwenden, nicht dünne"},{"menge":2,"einheit":"EL","name":"neutrales Öl","hinweis":""},{"menge":40,"einheit":"g","name":"rohe Erdnüsse","hinweis":""},{"menge":1,"einheit":"TL","name":"schwarze Senfsamen","hinweis":""},{"menge":1,"einheit":"TL","name":"Kreuzkümmel","hinweis":"optional"},{"menge":2,"einheit":"Stück","name":"mittelgroße Zwiebeln","hinweis":"fein gewürfelt"},{"menge":1,"einheit":"Stück","name":"mittelgroße Kartoffel","hinweis":"fein gewürfelt, optional"},{"menge":2,"einheit":"Stück","name":"grüne Chilischoten","hinweis":"in Ringen"},{"menge":1,"einheit":"Zweig","name":"Curryblätter","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Kurkumapulver","hinweis":""},{"menge":1,"einheit":"TL","name":"Zucker","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":2,"einheit":"EL","name":"Zitronensaft","hinweis":""},{"menge":2,"einheit":"EL","name":"gehackter Koriander","hinweis":""},{"menge":2,"einheit":"EL","name":"frische Kokosraspel","hinweis":"optional"}]}],"ausruestung":["Sieb","große flache Pfanne oder Kadai","Pfannenwender","Deckel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Würfle die Zwiebeln fein (etwa 5 mm), schneide die Chilis in dünne Ringe und die Kartoffel in sehr kleine Würfel von 5 mm, damit sie schnell gar werden. Stelle Gewürze, Erdnüsse, Zucker, Salz und Zitrone in kleinen Schälchen bereit, denn Poha gart so schnell, dass du keine Zeit zum Suchen hast. Hacke den Koriander und halbiere die Zitrone. Diese Vorbereitung ist das halbe Rezept: Wer alles bereit hat, braucht danach nur noch 10 Minuten am Herd.","dauer":0,"tipp":""},{"titel":"Poha waschen","aktion":"vorbereiten","text":"Gib die Reisflocken in ein Sieb und spüle sie unter kaltem Wasser 30–60 Sekunden, bis sie weich, aber nicht matschig sind. Schüttle das Wasser gut ab und lasse sie 10 Minuten im Sieb stehen, damit sie in der Restfeuchte quellen. Streue Zucker, Salz und Kurkuma darüber und mische mit einer Gabel locker. Die Flocken sollen sich weich anfühlen und nicht mehr hart brechen.","dauer":10,"tipp":"Zu langes Waschen macht die Flocken matschig, besser kurz und gründlich abtropfen."},{"titel":"Erdnüsse rösten","aktion":"anbraten","text":"Erhitze 1 EL Öl in der Pfanne bei mittlerer Hitze, bis es leicht schimmert. Gib die Erdnüsse hinein und rühre sie 2–3 Minuten ständig, bis sie goldbraun sind, knacken und nach Röstaroma duften. Hole sie mit einer Schaumkelle heraus, lasse sie auf einem Teller abtropfen und salze sie leicht. Sie werden erst am Ende über das Poha gestreut, damit sie knusprig bleiben und nicht im Dampf weich werden.","dauer":3,"tipp":""},{"titel":"Tempering","aktion":"anbraten","text":"Gib das restliche Öl in dieselbe Pfanne und erhitze es bei mittlerer Hitze. Füge die Senfsamen hinzu und warte, bis sie zu springen und zu knistern beginnen, denn erst dann haben sie ihr nussiges Aroma entfaltet. Gib Kreuzkümmel, Chili und Curryblätter dazu und brate sie 20 Sekunden, bis sie intensiv duften; Vorsicht, die Curryblätter spritzen. Füge dann die Kartoffelwürfel hinzu und brate sie 4–5 Minuten bei mittlerer Hitze, bis sie fast weich und leicht goldgelb sind.","dauer":6,"tipp":""},{"titel":"Zwiebeln dünsten","aktion":"anbraten","text":"Gib die gewürfelten Zwiebeln zu den Kartoffeln in die Pfanne und dünste sie 3–4 Minuten bei mittlerer Hitze, bis sie glasig und weich sind, aber noch leichten Biss haben. Sie sollen auf keinen Fall braun werden, sonst schmeckt das Poha zu kräftig und bitter. Der Duft ist süßlich-würzig. Salze leicht, das Salz zieht Wasser aus den Zwiebeln und lässt sie schneller weich werden. Falls etwas ansetzt, gib einen Schuss Wasser dazu.","dauer":4,"tipp":""},{"titel":"Poha dazugeben und dämpfen","aktion":"daempfen","text":"Gib die vorbereiteten Reisflocken in die Pfanne und hebe sie mit einem Wender vorsichtig unter das Gemüse, ohne zu rühren, sodass die Flocken ganz bleiben. Reduziere die Hitze auf niedrigste Stufe, decke die Pfanne ab und dämpfe das Poha 2–3 Minuten. Der Dampf macht die Flocken noch weicher und lässt die Gewürze einziehen. Sie sollen warm, weich, gelb gefärbt und locker sein, nicht klebrig. Nimm die Pfanne vom Herd und träufle Zitronensaft darüber.","dauer":3,"tipp":"Nicht zu viel rühren, sonst werden die Flocken matschig."},{"titel":"Abschmecken und anrichten","aktion":"anrichten","text":"Schmecke das Poha mit Salz, Zucker und Zitronensaft ab; es soll leicht süßlich, salzig und frisch sauer schmecken, mit dem Aroma von Senf und Curryblatt. Gib die Erdnüsse, den Koriander und nach Belieben Kokosraspeln darüber und hebe alles kurz unter. Serviere es sofort warm in Schalen, mit Zitronenspalten und nach Wunsch Sev oder Granatapfelkernen. Poha wird mit der Zeit klebrig, deshalb wird es immer frisch zubereitet und gleich gegessen. Dazu passt ein heißer Chai.","dauer":0,"tipp":""}],"profitipps":["Dicke Reisflocken verwenden, dünne zerfallen.","Poha nur kurz waschen und gut abtropfen lassen.","Zucker und Zitrone balancieren die Würze.","Curryblätter erst nach den Senfsamen zugeben.","Erdnüsse separat rösten, damit sie knusprig bleiben."],"varianten":["Indori Poha mit Fenchel, Sev und Granatapfel","Batata Poha mit mehr Kartoffeln","Tomaten-Poha","Mit Erbsen und Karotten","Kolhapuri Poha scharf mit Chili"],"beilagen":["Sev","Chai","Zitronenspalten","Joghurt"],"getraenk":"Masala Chai oder Buttermilch (Chaas).","quellen":[{"titel":"Poha Recipe (Veg Recipes of India)","url":"https://www.vegrecipesofindia.com/kanda-poha-or-onion-poha/."},{"titel":"Maharashtrian Kanda Poha (Archana's Kitchen)","url":"https://www.archanaskitchen.com/recipe/maharashtrian-kanda-poha"},{"titel":"Easy Kanda Poha (Ministry of Curry)","url":"https://ministryofcurry.com/wprm_print/easy-kanda-poha-traditional-maharashtrian-recipe"}],"bild":"reis","farben":["#e8c33c","#f4e9a8","#5a8f3a"],"schlagworte":["Maharashtra","Indori","schnell","vegan"],"vegetarisch_moeglich":true,"gang":"fruehstueck","fleischsorte":"","koeche":[]},{"id":"indien-chicken-chettinad","name":"Chicken Chettinad","originalname":"Chettinad Kozhi Curry","kueche":"indien","region":"Südindien (Chettinad, Tamil Nadu)","beliebtheit":70,"hauptkategorie":"fleisch","fleischsorte":"huhn","gang":"hauptgericht","kurz":"Hähnchen in einer dunklen, röstigen Gewürzpaste aus frisch gemahlenem Pfeffer, Fenchel und Kokos – das würzige Aushängeschild der Chettinad-Küche.","hintergrund":"Die Chettinad-Küche stammt von der Händlergemeinschaft der Chettiars im Süden Tamil Nadus und gilt als eine der aromatischsten Südindiens. Typisch sind frisch gemahlene Gewürzmischungen mit Sternanis, Fenchel, Pfeffer, Zimt, Nelken, Kreuzkümmel und Kalpasi, einer Steinflechte. Hähnchen, Ziege und Fisch sind häufige Fleischsorten. Beim Chicken Chettinad werden die Gewürze trocken geröstet und mit Kokos zu einer Paste gemahlen, die dem Gericht Farbe, Schärfe und Tiefe verleiht. Das Gericht wird mit Reis, Parotta oder Dosa gegessen.","portionen":4,"zeit":{"vorbereitung":30,"garen":50,"ruhen":60},"schwierigkeit":2,"zutaten":[{"gruppe":"Hähnchen und Marinade","liste":[{"menge":900,"einheit":"g","name":"Hähnchenschenkel mit Knochen, in Stücken","hinweis":"Keulen in Ober- und Unterschenkel teilen; Knochen geben Geschmack"},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"EL","name":"Ingwer-Knoblauch-Paste","hinweis":""},{"menge":1,"einheit":"EL","name":"Zitronensaft","hinweis":""}]},{"gruppe":"Chettinad-Masala (frisch geröstet)","liste":[{"menge":2,"einheit":"EL","name":"Koriandersamen","hinweis":""},{"menge":1,"einheit":"TL","name":"Kreuzkümmelsamen","hinweis":""},{"menge":1,"einheit":"TL","name":"Fenchelsamen","hinweis":""},{"menge":1.5,"einheit":"TL","name":"schwarze Pfefferkörner","hinweis":"viel Pfeffer ist typisch"},{"menge":1,"einheit":"Stück","name":"Sternanis","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zimtstange, 4 cm","hinweis":""},{"menge":4,"einheit":"Stück","name":"Gewürznelken","hinweis":""},{"menge":3,"einheit":"Stück","name":"grüne Kardamomkapseln","hinweis":""},{"menge":6,"einheit":"Stück","name":"getrocknete rote Chilischoten","hinweis":"Kashmiri für Farbe, einige scharfe für Feuer"},{"menge":1,"einheit":"TL","name":"Chana Dal","hinweis":"bindet und gibt Röstaroma"},{"menge":1,"einheit":"Stück","name":"Stück Kalpasi (Steinblume), optional","hinweis":"im Asialaden; nicht zwingend"},{"menge":4,"einheit":"EL","name":"frische Kokosraspeln oder ungesüßte Kokosflocken","hinweis":""}]},{"gruppe":"Curry","liste":[{"menge":4,"einheit":"EL","name":"Sesamöl oder Kokosöl","hinweis":"Sesamöl ist traditionell"},{"menge":1,"einheit":"TL","name":"Fenchelsamen","hinweis":""},{"menge":1,"einheit":"Stück","name":"Sternanis","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zimtstange, 3 cm","hinweis":""},{"menge":15,"einheit":"Stück","name":"Curryblätter","hinweis":""},{"menge":2,"einheit":"Stück","name":"große Zwiebeln","hinweis":"fein gehackt"},{"menge":2,"einheit":"Stück","name":"Tomaten","hinweis":"gewürfelt"},{"menge":1,"einheit":"EL","name":"Ingwer-Knoblauch-Paste","hinweis":""},{"menge":250,"einheit":"ml","name":"heißes Wasser","hinweis":""},{"menge":1,"einheit":"TL","name":"frisch gemahlener schwarzer Pfeffer","hinweis":"zum Schluss"},{"menge":1,"einheit":"Handvoll","name":"frischer Koriander","hinweis":""},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]}],"ausruestung":["Schwerer Topf oder Kadai","Pfanne zum Rösten","Mixer oder Mörser","Deckel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Teile die Hähnchenschenkel in Stücke von etwa 5 cm, lasse Haut und Knochen dran, und tupfe sie trocken. Mariniere sie mit Kurkuma, Salz, Ingwer-Knoblauch-Paste und Zitronensaft und stelle sie mindestens eine Stunde kühl. Hacke Zwiebeln und Tomaten. Stelle für die Masala alle Gewürze in getrennten Schälchen nach Röstzeit sortiert bereit: erst die harten Samen, dann Chilis, zuletzt Kokos.","dauer":60,"tipp":"Je länger das Hähnchen marinieren darf, desto aromatischer."},{"titel":"Masala-Gewürze trocken rösten","aktion":"braten","text":"Erhitze eine trockene Pfanne bei kleiner bis mittlerer Hitze. Röste zuerst Chana Dal 30 Sekunden, dann Koriander, Kreuzkümmel, Fenchel und Pfeffer weitere 1 bis 1,5 Minuten unter ständigem Schwenken, bis sie intensiv duften und Koriander und Kreuzkümmel leicht dunkeln. Gib Sternanis, Zimt, Nelken, Kardamom und Kalpasi dazu und röste 30 Sekunden, bis die Kardamomhülsen leicht knistern. Gib zuletzt die getrockneten Chilis für 10 bis 15 Sekunden dazu, bis sie leicht aufquellen. Verbrannte Chilis riechen stechend und machen die Masala bitter.","dauer":5,"tipp":"Röste harte und weiche Gewürze nacheinander, nicht alles auf einmal."},{"titel":"Kokos rösten und Paste mahlen","aktion":"braten","text":"Röste die Kokosraspeln in einer trockenen Pfanne bei kleiner Hitze 2 bis 3 Minuten, rühre ständig, bis sie hellgoldbraun sind und nach geröstetem Kokos duften. Sie dürfen nicht dunkel werden, sonst schmecken sie bitter. Lasse alle gerösteten Zutaten auskühlen und mahle sie mit 100 ml Wasser im Mixer zu einer feinen, dunkelbraunen Paste. Sie soll nach Röstgewürzen und Kokos duften. Wenn sie zu dick ist, gib wenig Wasser dazu.","dauer":10,"tipp":"Kalpasi nur in kleiner Menge nehmen; es schmeckt erdig und kann dominieren."},{"titel":"Ganze Gewürze tempern","aktion":"braten","text":"Erhitze das Sesamöl in einem schweren Topf bei mittlerer Hitze. Gib Fenchel, Sternanis und Zimt hinein, warte 20 bis 30 Sekunden, bis es duftet, und füge die Curryblätter hinzu. Sie zischen und werden knusprig. Die ganzen Gewürze geben ihre Aromen an das Fett ab; bleiben sie zu lang, wird das Öl bitter. Gib sofort die Zwiebeln dazu, bevor etwas verbrennt.","dauer":3,"tipp":"Curryblätter spritzen – halte einen Deckel bereit."},{"titel":"Zwiebeln und Tomaten kochen","aktion":"anbraten","text":"Brate die Zwiebeln bei mittlerer Hitze 12 bis 15 Minuten, bis sie tief goldbraun sind. Gib die Ingwer-Knoblauch-Paste dazu und brate 1 Minute. Füge die Tomaten hinzu und koche sie 6 bis 8 Minuten, bis sie zerfallen und Öl sich absetzt. Die Zwiebeln sind die Basis der Sauce; sie sollen nicht verbrannt, sondern süß-karamellig riechen. Rühre häufig und gib einen Schluck Wasser bei, falls es ansetzt.","dauer":20,"tipp":"Salz hilft den Zwiebeln, Wasser abzugeben und gleichmäßig zu bräunen."},{"titel":"Hähnchen anbraten","aktion":"anbraten","text":"Gib die marinierten Hähnchenstücke in den Topf und brate sie bei mittlerer bis hoher Hitze 6 bis 8 Minuten unter Wenden an, bis sie an den Seiten Farbe nehmen. Das Anbraten versiegelt das Fleisch und bringt Röstaroma in die Sauce. Wenn es spritzt, reduziere die Hitze. Das Fleisch ist noch roh im Inneren; es gart später in der Sauce zu Ende.","dauer":8,"tipp":"Nicht zu viele Stücke gleichzeitig, sonst kocht das Fleisch."},{"titel":"Masala-Paste einarbeiten","aktion":"schmoren","text":"Gib die gemahlene Chettinad-Paste in den Topf und rühre sie 3 bis 4 Minuten bei mittlerer Hitze mit Fleisch und Zwiebeln. Die Paste wird dunkler und das Öl beginnt sich abzusetzen. Das ist das Zeichen, dass die Gewürze gar sind und ihre Rohheit verloren haben. Gieße das heiße Wasser dazu, rühre den Bratensatz vom Boden und bringe alles zum Köcheln.","dauer":5,"tipp":"Heißes Wasser verwenden, kaltes bremst das Garen."},{"titel":"Schmoren","aktion":"schmoren","text":"Setze den Deckel schräg auf und lasse das Hähnchen bei kleiner Hitze 25 bis 30 Minuten garen, rühre alle 10 Minuten um. Das Fleisch ist fertig, wenn es sich leicht vom Knochen löst und die Kerntemperatur 78 bis 80 °C erreicht. Nimm in den letzten 5 Minuten den Deckel ab, damit die Sauce eindickt und das Öl rot an der Oberfläche glänzt. Eine dicke, fast trockene Sauce ist für Chettinad typisch; wenn sie zu dünn ist, lasse sie einkochen.","dauer":30,"tipp":"Zu hohe Hitze macht Hähnchen zäh – bleib bei kleiner Flamme."},{"titel":"Pfeffer-Finish und Anrichten","aktion":"garnieren","text":"Streue zum Schluss 1 Teelöffel frisch gemahlenen schwarzen Pfeffer in die Sauce und rühre kurz um; der frische Pfeffer gibt eine scharfe, aromatische Note, die lange Kochzeit nicht überlebt. Schmecke mit Salz und etwas Zitronensaft ab. Fülle das Gericht in eine Schüssel und streue Koriander darüber. Serviere es mit Reis, Parotta oder Dosa. Das Curry schmeckt am nächsten Tag noch intensiver.","dauer":2,"tipp":"Pfeffer erst ganz zum Schluss mahlen, so bleibt sein Aroma erhalten."}],"profitipps":["Gewürze frisch rösten und mahlen – die Paste ist das Herz des Gerichts.","Reihenfolge beim Rösten: harte Samen, dann Gewürze, Chilis zuletzt.","Kokos nur hellbraun rösten.","Pfeffer zum Schluss frisch zugeben.","Kalpasi sparsam einsetzen."],"varianten":["Chettinad Mutton Curry mit Lamm oder Ziege.","Chettinad Pepper Chicken, trockener mit viel Pfeffer.","Chettinad Fischcurry mit Tamarinde.","Vegetarische Variante mit Kartoffeln oder Blumenkohl."],"beilagen":["Parotta oder Dosa","Gedämpfter Reis","Zwiebel-Raita","Papad"],"getraenk":"Kühle Buttermilch oder ein trockener Rosé.","koeche":[],"quellen":[{"titel":"Chettinad cuisine – Wikipedia","url":"https://en.wikipedia.org/wiki/Chettinad_cuisine"},{"titel":"Tadka: the simple Indian cooking technique – SBS Food","url":"https://www.sbs.com.au/food/article/tadka-the-simple-indian-cooking-technique-you-should-know/8nucpkdcu"},{"titel":"The art of tadka – World Spice Cooks Club","url":"https://cooksclub.worldspice.com/posts/32-the-art-of-tadka-indian-tempering-technique-explained"}],"bild":"curry","farben":["#5a2a14","#a0501e","#d9a05a"],"schlagworte":["Chettinad","Pfeffer","Röstgewürze","Tamil Nadu"],"vegetarisch_moeglich":false},{"id":"indien-kerala-fischcurry","name":"Kerala-Fischcurry","originalname":"Meen Curry","kueche":"indien","region":"Südindien (Kerala)","beliebtheit":68,"hauptkategorie":"fisch","fleischsorte":"","fischsorte":"fisch","gang":"hauptgericht","kurz":"Fester Fisch in einer roten, sauren Chili-Sauce mit Kokosöl, Curryblättern und Kodampuli – das Herz der Küstenküche Keralas.","hintergrund":"Kerala am Arabischen Meer lebt vom Fisch. Die Kerala-Küche nutzt reichlich Kokos in allen Formen, Curryblätter, Senfsamen, Chili, Tamarinde und Pfeffer. Meen Curry, das Fischcurry, wird je nach Region mit Kokosmilch oder wie im berühmten Kottayam-Stil ohne Kokos und mit Kodampuli (Malabar-Tamarinde, Garcinia) gekocht, die dem Curry eine rauchig-saure Note gibt. Traditionell gart es in einem Tontopf (Manchatti), der den Geschmack vertieft, und wird am Tag danach besonders geschätzt. Gegessen wird es mit gedämpftem Reis, Tapioka oder Appam.","portionen":4,"zeit":{"vorbereitung":25,"garen":30,"ruhen":30},"schwierigkeit":2,"zutaten":[{"gruppe":"Fisch","liste":[{"menge":600,"einheit":"g","name":"festfleischiger Fisch (Seeteufel, Kabeljau, Red Snapper oder Königsmakrele) in Steaks oder dicken Stücken","hinweis":"Fisch mit festem Fleisch zerfällt nicht"},{"menge":0.5,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Sauce","liste":[{"menge":3,"einheit":"EL","name":"Kokosöl","hinweis":"unraffiniert, für das typische Aroma"},{"menge":1,"einheit":"TL","name":"Senfsamen","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Bockshornkleesamen","hinweis":"sparsam, sonst bitter"},{"menge":15,"einheit":"Stück","name":"Curryblätter","hinweis":""},{"menge":6,"einheit":"Stück","name":"Schalotten","hinweis":"in dünnen Scheiben"},{"menge":1,"einheit":"EL","name":"Ingwer, fein gerieben","hinweis":""},{"menge":5,"einheit":"Zehe","name":"Knoblauch","hinweis":"fein gehackt"},{"menge":3,"einheit":"Stück","name":"grüne Chilischoten","hinweis":"längs aufgeschlitzt"},{"menge":2,"einheit":"EL","name":"Kashmiri-Chilipulver","hinweis":"für Farbe und mild-würzige Schärfe"},{"menge":1,"einheit":"TL","name":"Kurkuma","hinweis":""},{"menge":1,"einheit":"TL","name":"gemahlener Koriander","hinweis":""},{"menge":4,"einheit":"Stück","name":"Kodampuli (Malabar-Tamarinde)","hinweis":"in 200 ml warmem Wasser 20 Minuten eingeweicht; ersatzweise 1 EL Tamarindenpaste"},{"menge":1,"einheit":"Stück","name":"Tomate","hinweis":"optional, in Stücken"},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]},{"gruppe":"Zum Vollenden","liste":[{"menge":1,"einheit":"EL","name":"Kokosöl","hinweis":"roh über das fertige Curry"},{"menge":8,"einheit":"Stück","name":"Curryblätter","hinweis":"frisch"}]}],"ausruestung":["Tontopf oder schwerer Topf mit Deckel","Kleine Schüssel für Einweichen","Mörser"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Spüle den Fisch kurz ab und tupfe ihn trocken. Schneide ihn in etwa 4 cm dicke Stücke, reibe sie mit Kurkuma und Salz ein und lasse sie 15 Minuten ruhen. Das Salz festigt das Fleisch, sodass es später nicht zerfällt. Weiche die Kodampuli in warmem Wasser ein, bis sie weich ist und das Wasser sich bräunlich färbt. Schneide Schalotten in dünne Scheiben, hacke Knoblauch und Ingwer fein und schlitze die Chilis.","dauer":20,"tipp":"Kodampuli färbt das Wasser dunkel – nutze das Einweichwasser im Curry."},{"titel":"Sauce-Paste anrühren","aktion":"mischen","text":"Rühre Kashmiri-Chilipulver, Kurkuma und Koriander mit 100 ml kaltem Wasser zu einer glatten Paste. Diese Paste schützt die Gewürze vor dem Verbrennen im heißen Öl und verteilt die Farbe gleichmäßig in der Sauce. Sie soll leuchtend rot sein. Gib sie später in die Pfanne, sobald Schalotten und Knoblauch goldgelb sind. Rühre sie vorher noch einmal auf, damit sich nichts absetzt.","dauer":3,"tipp":"Chilipulver in trockener Pfanne verbrennt in Sekunden; die Wasserpaste verhindert das."},{"titel":"Gewürze im Kokosöl tempern","aktion":"braten","text":"Erhitze das Kokosöl in einem Tontopf oder schweren Topf bei mittlerer Hitze, bis es leicht schimmert. Gib Senfsamen hinein und warte 20 bis 30 Sekunden, bis sie knackend aufspringen. Füge Bockshornklee hinzu, der nur 5 Sekunden braucht, dann sofort die Curryblätter. Sie zischen und werden knusprig. Reihenfolge und Geschwindigkeit sind entscheidend; verbrannter Bockshornklee macht das Curry bitter.","dauer":2,"tipp":"Halte den Deckel bereit, Senfsamen und Curryblätter spritzen."},{"titel":"Schalotten, Ingwer und Knoblauch rösten","aktion":"anbraten","text":"Gib Schalotten in das Gewürzöl und brate sie 5 bis 6 Minuten bei mittlerer Hitze, bis sie weich und goldgelb sind. Füge Ingwer, Knoblauch und Chilis hinzu und brate weitere 2 Minuten, bis der Knoblauch hellgolden wird. Die Mischung duftet jetzt süßlich-scharf. Wenn der Knoblauch dunkelbraun wird, wird die Sauce bitter, nimm in dem Fall den Topf kurz vom Herd.","dauer":8,"tipp":"Schalotten bräunen langsamer als Zwiebeln und sind in Kerala die klassische Wahl."},{"titel":"Gewürzpaste braten","aktion":"braten","text":"Nimm den Topf kurz vom Herd, gib die Gewürzpaste hinein, rühre und stelle ihn wieder auf kleine Hitze. Brate die Paste 2 bis 3 Minuten, bis das Wasser verdampft ist und sich Öl am Rand sammelt. Die Farbe wird tiefrot und der Geruch süßlich-würzig. Erst dann ist die Rohheit der Gewürze weg. Gib bei Bedarf einen Spritzer Wasser dazu, wenn es ansetzt.","dauer":4,"tipp":"Wenn die Paste dunkelbraun wird, ist sie verbrannt; dann neu beginnen."},{"titel":"Kodampuli zugeben und Sauce kochen","aktion":"koecheln","text":"Gieße Kodampuli samt Einweichwasser und weitere 100 ml Wasser dazu, füge Salz und die Tomate hinzu und bringe alles zum Kochen. Lasse die Sauce 8 bis 10 Minuten bei mittlerer Hitze köcheln, bis sie leicht eingedickt ist und rauchig-sauer duftet. Schmecke: Sie muss deutlich sauer und kräftig gewürzt sein, weil der Fisch sie abmildert. Wenn sie zu sauer ist, entferne ein Stück Kodampuli.","dauer":10,"tipp":"Kodampuli bleibt im Curry, wird aber nicht mitgegessen."},{"titel":"Fisch garen","aktion":"koecheln","text":"Lege die Fischstücke vorsichtig in die kochende Sauce, schwenke den Topf, damit sie bedeckt sind, und lasse sie bei kleiner Hitze 8 bis 10 Minuten zugedeckt garen. Rühre nicht mit dem Löffel um, damit der Fisch nicht zerfällt; schwenke stattdessen den Topf. Der Fisch ist fertig, wenn das Fleisch undurchsichtig-weiß ist und sich an der dicksten Stelle leicht mit einer Gabel teilen lässt. Zu lange gekocht wird er trocken.","dauer":10,"tipp":"Den Topf schwenken statt rühren – so bleibt der Fisch heil."},{"titel":"Kokosöl-Finish und Ruhen","aktion":"abschmecken","text":"Nimm den Topf vom Herd, träufle 1 Esslöffel rohes Kokosöl und die frischen Curryblätter darüber und schwenke den Topf. Das rohe Öl gibt ein frisches Kokosaroma, das beim Kochen verloren ginge. Decke den Topf ab und lasse das Curry mindestens 30 Minuten ruhen. Die Aromen ziehen in den Fisch ein, und die Sauce wird runder. Am nächsten Tag schmeckt es noch besser.","dauer":30,"tipp":"Wer Zeit hat, kocht das Curry am Vortag; es schmeckt dann wie in Kerala."},{"titel":"Anrichten","aktion":"anrichten","text":"Wärme das Curry bei kleinster Hitze vorsichtig an, ohne zu rühren. Serviere es in einer Schale mit viel Sauce zu gedämpftem Reis oder Appam. Gib frische Curryblätter und rohe Schalotten dazu. In Kerala isst man dazu oft Tapioka oder Pappadam. Das Curry sollte rot glänzen, mit rotem Öl an der Oberfläche; das ist ein Zeichen für richtig gebratene Gewürze.","dauer":0,"tipp":"Fischgräten vorab entfernen oder die Gäste warnen."}],"profitipps":["Festfleischigen Fisch wählen, der nicht zerfällt.","Gewürze als Wasserpaste anbraten, so verbrennen sie nicht.","Topf schwenken statt rühren, wenn der Fisch drin ist.","Kokosöl roh zum Schluss gibt Aroma.","Am Tag danach schmeckt es am besten."],"varianten":["Mit Kokosmilch als milderes Fischcurry.","Kottayam-Stil im Tontopf mit viel Kodampuli.","Mit Garnelen statt Fisch.","Mit Tamarinde und grüner Mango statt Kodampuli."],"beilagen":["Gedämpfter Reis oder Appam","Tapioka","Papad","Gemüse-Thoran (Kokos-Gemüse)"],"getraenk":"Kühle Buttermilch, Kokoswasser oder ein trockener Riesling.","koeche":[],"quellen":[{"titel":"Kerala cuisine – Wikipedia","url":"https://en.wikipedia.org/wiki/Kerala_cuisine"},{"titel":"Tadka: the simple Indian cooking technique – SBS Food","url":"https://www.sbs.com.au/food/article/tadka-the-simple-indian-cooking-technique-you-should-know/8nucpkdcu"}],"bild":"fisch","farben":["#b8301c","#e06a2a","#f0d8a0"],"schlagworte":["Kerala","Fisch","Kokosöl","Kodampuli"],"vegetarisch_moeglich":false},{"id":"indien-rasmalai","name":"Rasmalai","originalname":"রসমালাই","kueche":"indien","region":"Bengalen","beliebtheit":66,"bild":"dessert","kurz":"Zarte, schwammige Käsebällchen aus Frischkäse in kalter, safranduftender Kardamom-Milch: ein bengalischer Klassiker, der auf der Zunge zergeht.","hintergrund":"Rasmalai stammt aus Bengalen und wird in Indien und Bangladesch zu Festen gereicht. Die genauen Ursprünge sind umstritten: In Comilla (heute Bangladesch) heißt es, die Gebrüder Sen hätten es um 1930 populär gemacht, während die Familie K. C. Das aus Kolkata ihren Gründer als Erfinder reklamiert. Die Grundlage ist Chhena, ein frischer Käse aus gestockter Milch, der geknetet, zu flachen Bällchen geformt, in Zuckersirup gegart und danach in gewürzter Milch (Rabri) eingeweicht wird. Serviert wird Rasmalai kalt, mit Pistazien und Safran.","portionen":6,"zeit":{"vorbereitung":40,"garen":60,"ruhen":480},"schwierigkeit":3,"zutaten":[{"gruppe":"Chhena","liste":[{"menge":1.5,"einheit":"l","name":"Vollmilch","hinweis":"frisch, nicht ultrahocherhitzt (H-Milch gerinnt schlecht)"},{"menge":4,"einheit":"EL","name":"Zitronensaft","hinweis":"frisch gepresst; alternativ weißer Essig, verdünnt"},{"menge":1,"einheit":"TL","name":"Grieß","hinweis":"optional, für Stabilität"},{"menge":1,"einheit":"TL","name":"Speisestärke","hinweis":""}]},{"gruppe":"Zuckersirup","liste":[{"menge":1,"einheit":"l","name":"Wasser","hinweis":""},{"menge":250,"einheit":"g","name":"Zucker","hinweis":""},{"menge":3,"einheit":"Stück","name":"Kardamomkapseln","hinweis":"leicht angedrückt"}]},{"gruppe":"Safranmilch (Rabri)","liste":[{"menge":750,"einheit":"ml","name":"Vollmilch","hinweis":""},{"menge":80,"einheit":"g","name":"Zucker","hinweis":""},{"menge":1,"einheit":"Prise","name":"Safranfäden","hinweis":"ca. 20 Fäden, in 2 EL warmer Milch eingeweicht"},{"menge":0.5,"einheit":"TL","name":"Kardamompulver","hinweis":""},{"menge":30,"einheit":"g","name":"Pistazien","hinweis":"fein gehackt"},{"menge":1,"einheit":"TL","name":"Rosenwasser","hinweis":"optional"}]}],"ausruestung":["großer Topf","Passiertuch oder Mulltuch","Sieb","breiter Topf mit Deckel","kleiner Topf für die Milch","Kühlbehälter"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Lege ein sauberes Mulltuch oder Passiertuch in ein Sieb und stelle es in die Spüle. Presse den Zitronensaft aus, mische ihn mit zwei Esslöffeln Wasser und halte ein Gefäß mit Eiswasser bereit, das du zum Abschrecken des Käses brauchst. Weiche die Safranfäden in zwei Esslöffeln warmer Milch ein und stelle sie beiseite. Zerstoße die Kardamomkapseln leicht, sodass sie aufspringen. Der Schlüssel zum Gelingen ist zügiges, ruhiges Arbeiten, da die Käsebällchen sofort nach dem Formen in den Sirup müssen.","dauer":15,"tipp":""},{"titel":"Milch zum Gerinnen bringen","aktion":"kochen","text":"Bringe die 1,5 Liter Milch in einem großen Topf unter Rühren zum Kochen, damit sie nicht anbrennt. Nimm den Topf vom Herd und warte eine Minute. Gieße den verdünnten Zitronensaft nach und nach unter sanftem Rühren dazu: Die Milch gerinnt in weißen Flocken, und die Molke wird grünlich-klar. Hört das Flocken auf, ist es genug. Gib bei Bedarf noch einen Teelöffel Saft nach, bis die Molke vollständig klar ist. Lass den Topf zwei Minuten ruhen.","dauer":8,"tipp":"Die Molke muss klar sein – ist sie noch milchig, fehlt noch Säure."},{"titel":"Chhena abgießen und kneten","aktion":"abseihen","text":"Gieße die Masse durch das Tuch im Sieb ab und spüle die Käseflocken sofort mit kaltem Wasser, um den Zitronengeschmack zu entfernen. Binde die Tuchenden zusammen und drücke das Wasser aus, ohne den Käse zu quetschen, sodass er noch leicht feucht bleibt. Lege den Käse nach 15 Minuten Abtropfen auf eine glatte Fläche und knete ihn mit dem Handballen fünf bis acht Minuten, bis er glatt, weich und leicht fettig glänzt. Er soll nicht mehr krümelig sein, sondern wie ein formbarer, geschmeidiger Teig. Knete Stärke und Grieß ein.","dauer":30,"tipp":"Zu trockener Käse zerfällt, zu feuchter zerläuft im Sirup – er soll sich anfühlen wie weiche Knetmasse."},{"titel":"Bällchen formen","aktion":"formen","text":"Teile den Käseteig in zwölf gleich große Stücke und rolle jedes zwischen den Handflächen glatt, dann drücke es zu flachen Scheiben von etwa 4 cm Durchmesser. Die Oberfläche muss glatt und ohne Risse sein, sonst brechen sie beim Garen. Lege die geformten Scheiben auf ein Tablett und bedecke sie mit einem feuchten Tuch. Sie dehnen sich im Sirup stark aus, sie verdoppeln fast ihre Größe, deshalb nicht dicker formen.","dauer":15,"tipp":""},{"titel":"Im Sirup garen","aktion":"koecheln","text":"Bringe Wasser, Zucker und Kardamom in einem breiten Topf zum Kochen. Lasse den Sirup sprudeln und gib die Scheiben vorsichtig hinein. Decke den Topf ab und lasse sie 12 bis 15 Minuten bei mittlerer bis starker Hitze kochen, damit sie sich aufblähen und fluffig werden. Du erkennst den richtigen Zeitpunkt, wenn sie doppelt so groß geworden und an der Oberfläche schwimmen. Schalte die Hitze nicht herunter, ein starkes, aber nicht wildes Köcheln hält sie in Bewegung.","dauer":15,"tipp":"Topf nicht überfüllen, die Scheiben brauchen Platz. Gegebenenfalls in zwei Durchgängen garen."},{"titel":"Abschrecken und ausdrücken","aktion":"abseihen","text":"Hebe die Scheiben mit dem Schaumlöffel heraus und lege sie kurz in Eiswasser, damit sie fest bleiben. Nimm sie einzeln in die Handfläche und presse sie vorsichtig zwischen beiden Händen aus, um den Sirup zu entfernen. Dadurch kann sie später die Milch aufsaugen. Sie sehen jetzt flacher und fest aus, werden aber in der Milch wieder schwammig. Lege sie auf einen Teller.","dauer":8,"tipp":""},{"titel":"Safranmilch kochen","aktion":"reduzieren","text":"Koche 750 ml Milch mit dem Zucker in einem Topf auf und lasse sie unter gelegentlichem Rühren 15 bis 20 Minuten auf etwa zwei Drittel einkochen. Die Milch wird cremiger, leicht cremefarben und dicker. Rühre Kardamom, die Safranmilch und zuletzt das Rosenwasser ein. Nimm den Topf vom Herd und lasse sie auf lauwarme Temperatur abkühlen. Heiße Milch würde die Käsebällchen zerfallen lassen.","dauer":25,"tipp":""},{"titel":"Einweichen und kühlen","aktion":"marinieren","text":"Lege die ausgedrückten Käsebällchen in die lauwarme Milch und rühre sie nicht mehr. Lasse alles abkühlen, decke ab und stelle den Topf für mindestens sechs bis acht Stunden, am besten über Nacht, in den Kühlschrank. In dieser Zeit saugen die Scheiben die Milch auf, werden butterweich und duften nach Safran. Serviere sie kalt in Schälchen mit reichlich Milch und streue Pistazien und ein paar Safranfäden obenauf.","dauer":480,"tipp":"Je länger sie ziehen, desto weicher und aromatischer werden sie."}],"profitipps":["Nur frische Vollmilch, keine H-Milch – die gerinnt nicht richtig.","Der Käse muss lange und kräftig geknetet werden, bis er glatt ist; das ist die wichtigste Technik.","Die Scheiben erst dann in die Milch geben, wenn diese lauwarm ist.","Das Ausdrücken des Sirups ist entscheidend – sonst saugen sie keine Milch auf.","Im Kühlschrank halten sie sich zwei bis drei Tage."],"varianten":["Rasmalai-Tres-Leches-Kuchen nach moderner Art","Mit Rosenwasser und Pistazien im Rabri","Ras Malai mit Mango-Püree","Kürzere Version mit fertigem Milchpulver-Teig"],"beilagen":["Pistazien","essbare Rosenblätter"],"getraenk":"Masala Chai oder ein kühler Lassi","koeche":[{"name":"Sanjeev Kapoor","bezug":"Der indische Fernsehkoch hat Rezepte für Rasmalai-Abwandlungen wie Orange Rasmalai mit Pista Coulis veröffentlicht.","quelle":"https://sanjeevkapoor.com/Recipe/Orange-Rasmalai-With-Pista-Coulis-Sanjeev-Kapoor-Kitchen-FoodFood.html"}],"quellen":[{"titel":"Ras malai – Wikipedia","url":"https://en.wikipedia.org/wiki/Ras_malai"},{"titel":"Orange Rasmalai With Pista Coulis – Sanjeev Kapoor","url":"https://sanjeevkapoor.com/Recipe/Orange-Rasmalai-With-Pista-Coulis-Sanjeev-Kapoor-Kitchen-FoodFood.html"}],"farben":["#f2e2b4","#e8b84d","#4f7a3a"],"schlagworte":["Bengalen","Diwali","Frischkäse","Safran"],"themen":["fest"],"fleischsorte":"","hauptkategorie":"suess","gang":"dessert","vegetarisch_moeglich":true}]);
